## [Darker and Darker](https://atcoder.jp/contests/agc033/tasks/agc033_a)

怎么 AGC 还有这种垃圾题啊。

```cpp
const int N = 1e3 + 7;
const int dx[] = {1,-1,0,0};
const int dy[] = {0,0,1,-1};
int n, m, d[N][N], ans;
queue<pi> q; 

int main() {
	rd(n, m);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++) {
			char c;
			rdc(c);
			if (c == '#') q.push(mp(i, j));
			else d[i][j] = -1; 
		}
	while (q.size()) {
		int x = q.front().fi, y = q.front().se;
		q.pop();
		ans = d[x][y];
		for (int i = 0; i < 4; i++) {
			int X = x + dx[i], Y = y + dy[i];
			if (X < 1 || X > n || Y < 1 || Y > m || ~d[X][Y]) continue;
			d[X][Y] = d[x][y] + 1, q.push(mp(X, Y));
		}
	}
	print(ans);
	return 0;
}
```

