char a[N], b[N];

inline bool pd(int t, int w, char p, char q) {
	for (int i = 1; i <= k; i++) {
		if (a[i] == p) --t;
		if (!t) return 0;
		if (t != w && b[i] == q) ++t;
	}
	return 1;
}

