const int N = 1e5 + 7;
int n, ans;
pi a[N];
int l[N], r[N];

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(a[i].fi, a[i].se);
	sort(a + 1, a + n + 1);
	l[0] = r[n+1] = 1e9;
	for (int i = 1; i <= n; i++) l[i] = min(a[i].se, l[i-1]);
	for (int i = n; i; i--) r[i] = min(a[i].se, r[i+1]);
	for (int i = 1; i <= n; i++)
		ans = max(ans, a[i].se - a[i].fi + 1 + max(0, min(l[i-1], r[i+1]) - a[n-(i==n)].fi + 1));
