傻逼模拟题，用 `stable_sort` 排序一下，然后判一下无解。

```cpp
const int N = 5e5 + 7;
int n, m, a[N], p[N], q[N];
vi e[N];

int main() {
	rd(n, m);
	for (int i = 1, x, y; i <= m; i++)
		rd(x, y), e[x].pb(y), e[y].pb(x);
	rda(a, n);
	for (int i = 1; i <= n; i++) p[i] = i;
	stable_sort(p + 1, p + n + 1, [&](int i, int j) {
		return a[i] < a[j];
	});
	for (int i = 1; i <= n; i++) q[p[i]] = i;
	for (int x = 1; x <= n; x++) {
		map<int, bool> v;
		for (int y : e[p[x]])
			if (q[y] < x) v[a[y]] = 1;
		int t = 1;
		while (v[t]) ++t;
		if (t != a[p[x]]) return print(-1), 0;
	}
	printa(p, n);
	return 0;
}
