## [Johnny and Grandmaster](https://codeforces.com/contest/1361/problem/B)

从大到小贪心，每次往少的里面放。

其实是好题，只不过细节很多。

```cpp
const int N = 1e6 + 7;
int n, p, a[N];

inline void solve() {
	rd(n, p), rda(a, n);
	if (p == 1) return print(n & 1);
	sort(a + 1, a + n + 1);
	reverse(a + 1, a + n + 1);
	modint ans = (modint)p ^ a[1];
	ll c = 1;
	int k = a[1], w = log(n) / log(p) + 1;
	for (int i = 2; i <= n; i++) {
		if (k - a[i] > w) {
			if (c > 0) c = n;
			else if (c < 0) c = -n;
			k = a[i];
		} else while (k > a[i]) {
			--k;
			c *= p;
			if (c > n) {
				c = n;
				break;
			}
			if (c < -n) {
				c = -n;
				break;
			}
		}
		if (c <= 0) {
			ans += (modint)p ^ a[i];
			++c;
		} else {
			ans -= (modint)p ^ a[i];
			--c;
		}
	}
	print(ans);
}

int main() {
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
```

