vi e[N];
bool v[N];

void dfs(int x) {
	v[x] = 1;
	for (int y : e[x])
		if (!v[y]) dfs(y);
}

inline bool pd(int t) {
	t = (1 << t) - 1;
	for (int i = 0; i <= t; i++)
		d[i] = 0, e[i].clear(), v[i] = 0;
	for (int i = 1; i <= n; i++)
		e[a[i]&t].pb(b[i] & t), e[b[i]&t].pb(a[i] & t),
		++d[a[i]&t], ++d[b[i]&t];
	for (int i = 0; i <= t; i++)
		if (d[i] & 1) return 0;
	dfs(a[1] & t);
	for (int i = 0; i <= t; i++)
		if (d[i] && !v[i]) return 0;
	return 1;
}

namespace Euler {
	int h[N], e[N], t[N], tot = 1;
	bool v[N];
	vi ans;

	inline void add(int x, int y, int o = 1) {
