const int N = 1e5 + 7;
const ll inf = 1e18;
int n, m, a[N], b[N];
ll k, c[N];
bool v[N];
vi e[N];

struct T {
	int x;
	ll c;
	inline T() {}
	inline T(int x, ll c) : x(x), c(c) {}
	inline friend void operator += (T &a, const T &b) {
		if (a.x < b.x) a.x = b.x, a.c = b.c;
		else if (a.x == b.x) a.c = min(inf, a.c + b.c);
	}
} t[N];

inline void add(int x, T y) {
	while (x) t[x] += y, x -= x & -x;
}

T ask(int x) {
	T y = T(0, 1);
	while (x <= n) y += t[x], x += x & -x;
	return y;
}

int main() {
	rd(n), rd(k);
	for (int i = 1; i <= n; i++) rd(a[i]), b[a[i]] = i;
	for (int i = n; i; i--) {
		T o = ask(b[i] + 1);
		e[++o.x].push_back(i), c[i] = o.c, add(b[i], o);
	}
	m = ask(1).x;
	int now = -1;
	for (int i = m; i; i--)
		for (int j : e[i])
			if (b[j] >= now) {
				if (k <= c[j]) {
					v[j] = 1, now = b[j];
					break;
				} else k -= c[j];
			}
	print(n - m);
	for (int i = 1; i <= n; i++)
		if (!v[i]) print(i);
	return 0;
}
