bool v[N], ans[N];

void dfs(int x) {
	d[x] = d[f[x][0]] + 1;
	for (int i = 0; f[x][i]; i++)
		f[x][i+1] = f[f[x][i]][i];
	for (int y : e[x])
		if (y != f[x][0])
			f[y][0] = x, dfs(y);
}

inline int jump(int x, int d) {
	while (d) x = f[x][b[d&-d]], d -= d & -d;
	return x;
}

inline bool pd(int x, int y) {
	if (d[y] < d[x]) return 0;
	return jump(y, d[y] - d[x]) == x;
}

void dfs1(int x) {
	if (v[x]) return;
	ans[x] = 1;
	for (int y : e[x])
		if (y != f[x][0]) dfs1(y);
}

namespace work {
	int d[N], c[N];
	vi e[N];
	bool v[N];

	void dfs(int x, int f) {
		for (int y : ::e[x])
			if (y != f) d[y] = d[x] + 1, dfs(y, x);
	}

	inline bool main(int rt) {
		d[rt] = 1, dfs(rt, 0);
		for (int x = 1; x <= n; x++)
			for (int y : ::e[x])
				if (d[x] > d[y]) e[x].pb(y), ++c[y];
		for (int i = 1; i <= m; i++)
			e[p[i].fi].pb(p[i].se), ++c[p[i].se];
		queue<int> q;
		for (int i = 1; i <= n; i++)
			if (!c[i]) q.push(i);
		while (q.size()) {
			int x = q.front();
			q.pop();
			for (int y : e[x])
				if (!--c[y]) q.push(y);
		}
		for (int i = 1; i <= n; i++)
			if (c[i]) return 0;
		return 1;
	}
}

int main() {
	rd(n, m);
	for (int i = 1, t = 2; t < n; i++, t <<= 1) b[t] = i;
	for (int i = 1, x, y; i < n; i++)
		rd(x, y), e[x].pb(y), e[y].pb(x);
	dfs(rt = 1);
	for (int i = 1; i <= m; i++) {
		rd(p[i].fi, p[i].se);
		if (pd(p[i].fi, p[i].se)) {
			int x = jump(p[i].se, d[p[i].se] - d[p[i].fi] - 1);
			if (pd(rt, x)) rt = x;
			else if (!pd(x, rt)) Fail;
		} else {
			if (pd(rt, p[i].fi)) {
				if (rt == p[i].fi) Fail;
				v[p[i].fi] = 1;
			} else if (pd(p[i].fi, rt)) Fail;
		}
	}
	if (work::main(rt)) {
		dfs1(rt);
		for (int i = 1; i <= n; i++) print(ans[i]);
	} else Fail;
	return 0;
}
```

