char s[N][N];
int f[N*N], p[N*N];
modint c[N*N], ans = 1;

int get(int x) {
	return x == f[x] ? x : (f[x] = get(f[x]));
}

inline void merge(int x, int y) {
	f[get(x)] = get(y);
}

int get(int x, int y) {
