### [Delegation](https://www.luogu.com.cn/problem/P6142)

跟 [P5021 赛道修建](https://www.luogu.com.cn/problem/P5021) 差不多，二分 + 贪心 + 树形 dp。

```cpp
const int N = 1e5 + 7;
int n, m;
vi e[N];

inline int dp(int x, int f) {
	multiset<int> s;
	for (int y : e[x])
		if (y != f) {
			int k = dp(y, x);
			if (!~k) return -1;
			s.insert(k + 1);
		}
	int p = 0, q = 0;
	while (s.size()) {
		int t = *s.begin();
		s.erase(s.begin());
		if (t >= m) p = t;
		else {
			auto o = s.lower_bound(m - t);
			if (o == s.end()) {
				if (p) return -1;
				p = t;
			} else {
				if (*o >= m) q = t;
				s.erase(o);
			}
		}
	}
	return x != 1 ? p ? p : q : p; 
}

int main() {
	rd(n);
	for (int i = 1, x, y; i < n; i++)
		rd(x), rd(y), e[x].pb(y), e[y].pb(x);
	int l = 1, r = n - 1;
	while (l < r) {
		m = (l + r + 1) >> 1;
		int k = dp(1, 0);
		if (!k || k >= m) l = m;
		else r = m - 1;
	}
	print(l);
	return 0;
}
```

### [Equilateral Triangles](https://www.luogu.com.cn/problem/P6143)

曼哈顿距离转成切比雪夫距离，可以发现满足要求的三角形在新的坐标下一定是**一个平行与坐标轴的正方形的两个相邻的顶点和对面的边上的任意一点**连接而成。

那么前缀和计数一下即可，显然要横着和竖着各算一次，时间复杂度 $\mathcal O(n^3)$。

如果出现三个点都是正方形的顶点的情况，会被横着竖着各计算一次，需要去掉这样的情况，在后一次计算的时候不算到即可。

```cpp
const int N = 307;
int n, a[N*2][N*2], b[N*2][N*2];
char s[N];
ll ans;

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) {
		rds(s, n);
		for (int j = 1; j <= n; j++)
			if (s[j] == '*') a[i+j-1][i-j+n] = 1;
	}
	n *= 2;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			b[i][j] = a[i][j] + b[i][j-1];
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			if (a[i][j])
				for (int k = j + 1; k <= n; k++)
					if (a[i][k]) {
						if (i - (k - j) >= 1)
							ans += b[i-(k-j)][k] - b[i-(k-j)][j-1];
						if (i + (k - j) <= n)
							ans += b[i+(k-j)][k] - b[i+(k-j)][j-1];
					}
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			b[i][j] = a[i][j] + b[i-1][j];
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			if (a[j][i])
				for (int k = j + 1; k <= n; k++)
					if (a[k][i]) {
						if (i - (k - j) >= 1)
							ans += b[k-1][i-(k-j)] - b[j][i-(k-j)];
						if (i + (k - j) <= n)
							ans += b[k-1][i+(k-j)] - b[j][i+(k-j)];
					}
	print(ans);
	return 0;
}
```

### [Help Yourself](https://www.luogu.com.cn/problem/P6144)

$$
\begin{aligned}Ans &= \sum_{s} ans(s)^k \\\\&= \sum_{s} \sum_{i=0}^k S_2(k, i) ans(s)^{\underline{k}} \\\\&= \sum_{i=0}^k S_2(k,i) i! \sum_s \binom{ans(s)}{i}\end{aligned}
$$

将区间按 $l$ 排序，每次加入一个区间做 DP。

设 $f_i$ 表示最右边的端点为 $i$ 的集合的答案，分 $i<l$，$l \le i \le r$，$i>r$ 三种情况转移，线段树优化，时间复杂度 $\mathcal O(nk\log n)$。

本题中**常幂转下降幂**的 Trick 非常重要。

## [2020 US Open Contest](http://www.usaco.org/index.php?page=open20results)

### [Sprinklers 2: Return of the Alfalfa](https://www.luogu.com.cn/problem/P6275)

设 $f_{i,j}$ 表示考虑前 $i$ 行，第 $i$ 行中，第 $1\sim j-1$ 列为 `C`，第 $j\sim n$ 列为 `A`，且第 $i+1$ 行的第 $j$ 列为 `C` 的方案数。

这个定义要求我们从 $f_{i_1,j_1}$ 转移到 $f_{i_2,j_2}$ 的条件为：

- $i_1 < i_2$，$j_1 < j_2$。
- $s_{i_1+1, j_2-1},s_{i_2,j_2}$ 都为 `.` 或不存在。

设第 $i_1+1 \sim i_2$ 行中 `.` 的个数为 $c$，则转移系数为 $2^{c-k}$，其中 $k$ 是固定必须放的个数。

边界为 $f_{0,0} = 1$，目标为 $\sum_{j=1}^{n+1} f_{n,j}$。

直接做是 $\mathcal O(n^4)$ 的，二维前缀和优化一下就是 $\mathcal O(n^2)$ 的了。

```cpp
const int N = 2e3 + 7;
int n;
char s[N][N];
modint f[N][N], h[N][N], g[N], vg[N], v2, ans;

int main() {
	rd(n), v2 = (modint)1 / 2, g[0] = vg[0] = 1;
	for (int i = 1; i <= n; i++) {
		rds(s[i], n);
		g[i] = g[i-1];
		for (int j = 1; j <= n; j++)
			if (s[i][j] == '.') g[i] *= 2;
		vg[i] = 1 / g[i];
	}
	f[0][0] = 1;
	for (int j = 0; j <= n; j++)
		h[0][j] = !j || s[1][j] == '.';
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n + 1; j++) {
			if (j == n + 1 || s[i][j] == '.')
				f[i][j] += h[i-1][j-1] * g[i] * (j - 1 == 0 ? (modint)1 : v2) * (j == n + 1 ? (modint)1 : v2);
			h[i][j] = h[i][j-1] + f[i][j];
		}
		if (i == n) continue;
		for (int j = 0; j <= n; j++)
			if (!j || s[i+1][j] == '.') h[i][j] = h[i][j] * vg[i] + h[i-1][j];
			else h[i][j] = h[i-1][j];
	}
	print(h[n][n+1]);
	return 0;
}
