namespace shai {
	const int N = 1e6 + 7;
	int p[N], v[N], phi[N], miu[N];

	inline void init(int n) {
		v[1] = phi[1] = miu[1] = 1;
		for (int i = 2; i <= n; i++) {
			if (!v[i]) p[++p[0]] = v[i] = i, phi[i] = i - 1, miu[i] = -1;
			for (int j = 1; j <= p[0] && i * p[j] <= n && p[j] <= v[i]; j++)
				v[i*p[j]] = p[j],
				phi[i*p[j]] = phi[i] * (p[j] - 1 + (p[j] == v[i])),
				miu[i*p[j]] = p[j] == v[i] ? 0 : -miu[i];
		}
	}
}
using shai::p;

const int N = 1e5 + 7, M = 2e5 + 7;
int n, a[N], c[M];
pq<int> q[M];

inline vector<pair<ll, int>> divide(ll n) {
	vector<pair<ll, int>> p;
	for (ll i = 2; i * i <= n; i++)
		if (!(n % i)) {
			p.pb(mp(i, 0));
			while (!(n % i)) ++p.back().se, n /= i;
		}
	if (n > 1) p.pb(mp(n, 1));
	return p;
}

int main() {
	rd(n), rda(a, n);
	shai::init(2e5);
	for (int i = 1; i <= n; i++) {
		auto p = divide(a[i]);
		for (auto o : p) {
			q[o.fi].push(o.se);
			if (q[o.fi].size() > 2u) q[o.fi].pop();
			++c[o.fi];
		}
	}
	ll ans = 1;
	for (int i = 1; i <= p[0]; i++) {
		int x = p[i];
		if (c[x] == n) {
			int y = q[x].top();
			while (y--) ans *= x;
		}
		if (c[x] == n - 1) {
			if (q[x].size() > 1u) q[x].pop();
			int y = q[x].top();
			while (y--) ans *= x;
		}
	}
	print(ans);
	return 0;
}
