```cpp
const int N = 207;
int n, c[N], d[N], ans;
vi e[N];

void dfs(int x, int o) {
	c[x] = o;
	for (int y : e[x])
		if (!c[y]) dfs(y, 3 - o);
		else if (c[x] == c[y]) print(-1), exit(0);
}

inline int calc(int s) {
	for (int i = 1; i <= n; i++) d[i] = 0;
	d[s] = 1;
	queue<int> q;
	q.push(s);
	while (q.size()) {
		int x = q.front();
		q.pop();
		for (int y : e[x])
			if (!d[y]) d[y] = d[x] + 1, q.push(y);
			else if (d[y] != d[x] - 1 && d[y] != d[x] + 1) return 0;
	}
	return *max_element(d + 1, d + n + 1);
}

int main() {
	rd(n);
	for (int x = 1; x <= n; x++)
		for (int y = 1; y <= n; y++) {
			char c;
			rdc(c);
			if (c == '1') e[x].pb(y);
		}
	dfs(1, 1);
	for (int i = 1; i <= n; i++) ans = max(ans, calc(i));
	print(ans);
	return 0;
}
