## Phoenix and Berries

简单 DP。

```cpp
const int N = 507;
const ll inf = 1e18;
int n, k, x, y;
ll f[N][N], s, ans;
bool v[N][N];

inline void upd(ll &x, ll y) {
	x = max(x, y);
}

int main() {
	rd(n, k);
	f[0][0] = 0, v[0][0] = 1;
	for (int i = 1; i <= n; i++) {
		rd(x, y);
		for (int j = 0; j < k; j++)
			if (v[i-1][j]) {
				upd(f[i][(j+x)%k], f[i-1][j] + (j + x) / k + (s - f[i-1][j] * k - j + y) / k);
				v[i][(j+x)%k] = 1;
				for (int u = 1; u < k; u++)
					if (u <= x && k - u <= y)
						upd(f[i][(j+x-u)%k], f[i-1][j] + (j + x - u) / k + (s - f[i-1][j] * k - j + y - (k - u)) / k + 1),
						v[i][(j+x-u)%k] = 1;
			}
		s += x + y;
	}
	for (int i = 0; i < k; i++)
		if (v[n][i]) upd(ans, f[n][i]);
	print(ans);
	return 0;
}
