## [たのしいたのしいたのしい家庭菜園 (Growing Vegetables is Fun 3)](https://atcoder.jp/contests/joi2019ho/tasks/joi2019ho_c)

考虑确定了最终的字符串后如何计算最少交换次数。

首先同一个字符的相对顺序不变，于是可以一一对应起来。

考虑计算逆序对的个数，由于每次交换可以使逆序对个数减 $2$，因此答案就是逆序对个数除以 $2$。

把这个玩意儿套到一个 $\mathcal O(n^3)$ 的 DP 上去即可。

```cpp
const int N = 407, inf = 1e9;
int n, p[3][N], f[3][N][N][N], a[N], b[N], c[N];
char s[N];

inline void upd(int &x, int y) {
	x = min(x, y);
}

int main() {
	rd(n), rds(s, n);
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j < 3; j++) p[j][i] = p[j][i-1];
		switch (s[i]) {
			case 'R' : a[++a[0]] = i, ++p[0][i]; break;
			case 'G' : b[++b[0]] = i, ++p[1][i]; break;
			case 'Y' : c[++c[0]] = i, ++p[2][i]; break;
		}
	}
	for (int i = 0; i < 3; i++)
		for (int x = 0; x <= a[0]; x++)
			for (int y = 0; y <= b[0]; y++)
				for (int z = 0; z <= c[0]; z++)
					f[i][x][y][z] = inf;
	if (a[0]) f[0][a[0]-1][b[0]][c[0]] = abs(n - a[a[0]]);
	if (b[0]) f[1][a[0]][b[0]-1][c[0]] = abs(n - b[b[0]]);
	if (c[0]) f[2][a[0]][b[0]][c[0]-1] = abs(n - c[c[0]]);
	for (int i = n - 1; i; i--)
		for (int x = 0; x <= a[0] && x <= i; x++)
			for (int y = 0; y <= b[0] && x + y <= i; y++) {
				int z = i - x - y;
				if (z > c[0]) continue;
				if (x) upd(f[0][x-1][y][z], min(f[1][x][y][z], f[2][x][y][z]) + abs(p[1][a[x]] - y) + abs(p[2][a[x]] - z));
				if (y) upd(f[1][x][y-1][z], min(f[0][x][y][z], f[2][x][y][z]) + abs(p[0][b[y]] - x) + abs(p[2][b[y]] - z));
				if (z) upd(f[2][x][y][z-1], min(f[0][x][y][z], f[1][x][y][z]) + abs(p[0][c[z]] - x) + abs(p[1][c[z]] - y));
			}
	int ans = min(min(f[0][0][0][0], f[1][0][0][0]), f[2][0][0][0]);
	print(ans == inf ? -1 : (ans >> 1));
	return 0;
}
```

## [コイン集め (Coin Collecting)](https://atcoder.jp/contests/joi2019ho/tasks/joi2019ho_d)

依然是贪心，先把每个方块移到离它最近的范围内的位置，然后调整一下即可，时间复杂度 $\mathcal O(n)$。

```cpp
const int N = 1e5 + 7;
int n, c[N][3];
ll ans;

int main() {
	rd(n);
	for (int i = 1, x, y; i <= (n << 1); i++) {
		rd(x, y);
		if (x < 1) ans += 1 - x, x = 1;
		if (x > n) ans += x - n, x = n;
		if (y < 1) ans += 1 - y, y = 1;
		if (y > 2) ans += y - 2, y = 2;
		++c[x][y];
	}
	for (int i = 1, c1 = 0, c2 = 0; i <= n; i++) {
		c1 += c[i][1] - 1, c2 += c[i][2] - 1;
		while (c1 < 0 && c2 > 0) ++c1, --c2, ++ans;
		while (c1 > 0 && c2 < 0) --c1, ++c2, ++ans;
		if (i < n) ans += abs(c1) + abs(c2);
	}
	print(ans);
	return 0;
}
```

## [珍しい都市 (Unique Cities)](https://atcoder.jp/contests/joi2019ho/tasks/joi2019ho_e)

关于 $x$ 合法的城市一定在以 $x$ 为根的最长链上，这条最长链的另一端一定是直径的某一端。

因此我们对于直径的两端各算一次答案，取 $\max$ 即为最终的答案。

考虑对于直径的一端如何计算答案，将这个点设为根，然后长链剖分。

全局上用一个栈记录从根到每个点的路径上合法的点，用一个桶维护答案。

处理到一个点时，优先递归重儿子，因此要先把栈中和他距离不大于深度最大的轻儿子的点退栈。接着再递归所有轻儿子，把栈中和他距离不大于重儿子的点退栈。

这样可以保证每个点的贡献被删掉后不可能还需要加回来。

总时间复杂度 $\mathcal O(n)$。

```cpp
const int N = 2e5 + 7;
int n, m, a[N], ans[N];
vi e[N];

int rt, d[N];

void dfs1(int x, int fa) {
	d[x] = d[fa] + 1;
	if (d[x] > d[rt]) rt = x;
	for (int y : e[x])
		if (y != fa) dfs1(y, x);
}

int f[N], son[N][2];
#define s0 son[x][0]
#define s1 son[x][1]

void dfs2(int x, int fa) {
	d[x] = d[fa] + 1;
	s0 = s1 = 0;
	for (int y : e[x])
		if (y != fa) {
			dfs2(y, x);
			if (f[y] > f[s1]) s1 = y;
			if (f[s1] > f[s0]) swap(s0, s1);
		}
	f[x] = f[s0] + 1;
}

int st[N], tp;
int c[N], cnt;

inline void ins(int x) {
	cnt += !c[x]++;
}

inline void del(int x) {
	cnt -= !--c[x];
}

void dfs3(int x, int fa) {
	if (fa) ins(a[fa]), st[++tp] = fa;
	if (s0) {
		while (tp && d[st[tp]] >= d[x] - f[s1]) del(a[st[tp--]]);
		dfs3(s0, x);
	}
	while (tp && d[st[tp]] >= d[x] - f[s0]) del(a[st[tp--]]);
	for (int y : e[x])
		if (y != fa && y != s0)
			dfs3(y, x);
	ans[x] = max(ans[x], cnt);
	if (st[tp] == fa) del(a[st[tp--]]);
}

inline void work(int x) {
	rt = x;
	dfs1(x, 0);
	dfs2(rt, 0);
	for (int i = 1; i <= m; i++) c[i] = 0;
	cnt = tp = 0;
	dfs3(rt, 0);
}

int main() {
	rd(n, m);
	for (int i = 1, x, y; i < n; i++)
		rd(x, y), e[x].pb(y), e[y].pb(x);
	rda(a, n);
	work(1), work(rt);
	for (int i = 1; i <= n; i++) print(ans[i]);
	return 0;
}
```

> [ARC099F Eating Symbols Hard](https://atcoder.jp/contests/arc099/tasks/arc099_d)

## 题意

- 有一个长度为 $2 \times 10^9 + 1$ 的整数序列 $a_{-10^9 \dots 10^9}$，和一个整数 $p$，一开始均为 $0$。
- 对于一个仅包含 `+-><` 的字符串，按顺序依次执行每个字符对应的操作，可以得到新的 $a$ 序列。
- 每个字符对应的操作如下：
  - `+`：$a_p$ 加上 $1$。
  - `-`：$a_p$ 减去 $1$。
  - `>`：$p$ 加上 $1$。
  - `<`：$p$ 减去 $1$。
- 现在有一个长度为 $n$ 的仅包含 `+-><` 的字符串 $s$，问有多少个 $s$ 的非空子串得到的 $a$ 序列与 $s$ 得到的 $a$ 序列一样。
- $n \le 2.5 \times 10^5$。

## 题解

首先对于 $a$ 显然可以 hash，hash 函数设为模意义下的 $\sum_{i=-10^9}^{10^9} a_ix^i$，其中 $x$ 是一个自己设定的 base，注意可能要多个 base/mod。

对于一个操作序列，我们可以得到其操作完后的 hash 值以及 $p$ 所在的位置 $(h,p)$，显然这个信息是可以合并的，$\operatorname{merge}((h_i,p_i), (h_j,p_j)) = (h_i + h_jx^{p_i}, p_i + p_j)$。

预处理出 $s$ 的每个前缀 $s[:i]$ 对应的 $(h_i,p_i)$，题目要求 $s$ 与 $s[i:j]$ 得到的 $h$ 相等，等价于 $s[:i-1] + s$ 与 $s[:j]$ 得到的 $h$ 相等，即 $h_{i-1} + h_{n}x^{p_{i-1}} = h_j$。

从左往右扫 $j$，用个 `map` 记录 $h_{i-1} + h_nx^{p_{i-1}}$ 的值的个数即可，时间复杂度 $\mathcal O(n \log n)$。

## 代码

```cpp
const int N = 2.5e5 + 7, M = 2;
int n;
char s[N];
struct H {
	vector<modint> a;
	inline H() { a.resize(M); }
	inline modint &operator [] (int i) { return a[i]; }
	inline friend bool operator < (H x, H y) { return x.a < y.a; }
	inline friend H operator + (H x, H y) {
		for (int i = 0; i < M; i++) x[i] += y[i];
		return x;
	}
	inline friend H operator - (H x, H y) {
		for (int i = 0; i < M; i++) x[i] -= y[i];
		return x;
	}
	inline friend H operator * (H x, H y) {
		for (int i = 0; i < M; i++) x[i] *= y[i];
		return x;
	}
} a[N], x, y, h[N];
map<H, int> f;
ll ans;

int main() {
	srand(time(0));
	rd(n), rds(s, n);
	for (int i = 0; i < M; i++)
		a[0][i] = 1, x[i] = rdm(1, P - 1), y[i] = 1 / x[i];
	for (int i = 1; i <= n; i++)
		switch (s[i]) {
			case '+' : h[i] = h[i-1] + (a[i] = a[i-1]); break;
			case '-' : h[i] = h[i-1] - (a[i] = a[i-1]); break;
			case '>' : h[i] = h[i-1], a[i] = a[i-1] * x; break;
			case '<' : h[i] = h[i-1], a[i] = a[i-1] * y; break;
		}
	for (int i = 1; i <= n; i++) ++f[h[i-1]+h[n]*a[i-1]], ans += f[h[i]];
	print(ans);
	return 0;
}
```

> [ARC089F ColoringBalls](https://atcoder.jp/contests/arc089/tasks/arc089_d)

## 题意

- 有 $n$ 个白色小球排成一排。
- 给定一个长度为 $k$ 的只包含红色和蓝色的染色操作序列。
- 按照染色操作序列的顺序，每次选择一段区间（可以为空），将区间内的小球全部染成当前颜色。
- 另外，要求整个过程中不存在把白色小球染成蓝色的情况，即当染成蓝色时，选择的区间内不能包含白色小球。
- 求最终可以染出多少个不同的小球颜色序列。
- $n,k \le 70$，答案对 $10^9+7$ 取模。

## 题解

考虑一个暴力做法：枚举最终的小球颜色序列，判断是否合法。

考虑如何判断，以 `BRBRBWRRBRBBWWRRRRWRBBWWRRBBBR` 为例：

- 首先显然可以先进行一次 `unique` 而不影响答案，即变成 `BRBRBWRBRBWRWRBWRBR`。
- 以 `W` 分段：`BRBRB`，`RBRB`，`R`，`RB`，`RBR`。
- 对每一段按照 `B` 的个数分组，设 `B` 的个数为 $x$，将其分到第 $x+1$ 组：
  1. `R`。
  2. `(B)`，`(BR)`，`RB`，`RBR`（`()` 内的是不在这个例子中的情况）。
  3. `(BRB)`，`(BRBR)`，`RBRB`，`(RBRBR)`。
  4. `BRBRB`，`(BRBRBR)`，`(RBRBRB)`，`(RBRBRBR)`。
  5. ...。
- 注意到每一组实际上是等价的。对于第 $i$ 组，只要染色操作序列存在对应的子序列，就可以得到这一组内所有的小球颜色序列：
  1. `r`。
  2. `rb`。
  3. `rb?`（`?` 是通配符）。
  4. `rb??`。
  5. ...
- 因此，如果染色操作序列存在互不相交的五个子序列 `rb??`，`rb?`，`r`，`rb`，`rb`，则意味着合法，否则不合法。
- 按照要求的子序列长度从大到小贪心的匹配，先匹配 `r`，再匹配 `b`，再匹配 `?` 即可。

可以发现我们枚举最终的小球颜色序列，会有非常多等价的情况。

由于每一段是相互独立的，因此我们把一个小球颜色序列**无序**地写成一个序列，表示每一段所在组的编号（例子中的 `BRBRBWRRBRBBWWRRRRWRBBWWRRBBBR` 写成的序列为 $1,2,2,3,4$），则写成的序列相同的是等价的。

这个序列类似整数拆分，所以其实可能的序列很少，在 $n = 70$ 的时候也只有 $418662$ 种。

最后的问题是，对于一个合法的序列，如何计算其对应了多少个最终的小球颜色序列呢？

依然以 $1,2,2,3,4$ 为例，首先是一个多重组合数 $\binom {5}{1,2,1,1}$，然后乘上一个方案数。

$1,2,2,3,4$ 这个序列对应的小球颜色序列一定包含子序列 `RWBWBWBRBWBRBRB`，长度为 $15$。而 `unique` 后一定是 `WRWRBRWRBRWRBRBRWRBRBRBRW` 的子序列，长度为 $25$。即相当于把 $n-15$ 个字符分成 $25$ 组，每组可以为空的方案数。考虑隔板法，答案为 $\binom {n-15+25-1}{25-1}$。

时间复杂度 $\mathcal O(能过)$。

## 代码

```cpp
int n, k;
string s;
modint ans;

inline bool pd(vi p) {
	vector<bool> v(k, 0);
	vi t(p.size(), -1);
	for (ui i = 0; i < p.size(); i++) {
		while (++t[i] < k && (v[t[i]] || s[t[i]] == 'b'));
		if (t[i] == k) return 0;
		v[t[i]] = 1;
	}
	while (p.size() && p.back() == 1) p.pop_back();
	for (ui i = 0; i < p.size(); i++) {
		while (++t[i] < k && (v[t[i]] || s[t[i]] == 'r'));
		if (t[i] == k) return 0;
		v[t[i]] = 1;
	}
	while (p.size() && p.back() == 2) p.pop_back();
	for (ui i = 0; i < p.size(); i++)
		for (int j = 2; j < p[i]; j++) {
			while (++t[i] < k && v[t[i]]);
			if (t[i] == k) return 0;
			v[t[i]] = 1;
		}
	return 1;
}

void dfs(int o, int l, int r, vi p) {
	if (!o) {
		if (!pd(p)) return;
		modint now = binom(n - l + r - 1, r - 1);
		while (p.size()) {
			int t = 0, x = p.back();
			while (p.size() && p.back() == x) ++t, p.pop_back();
			now *= binom(p.size() + t, t); 
		}
		return ans += now, void();
	}
	while (1) {
		dfs(o - 1, l, r, p);
		l += (o == 1 ? 1 : 2 * o - 3) + (l != 0);
		if (l > n) return;
		r += 2 * o;
		p.pb(o);
	}
}

int main() {
	rd(n, k), rds(s);
	init(1e6);
	vi p;
	dfs((n + 3) >> 1, 0, 1, p);
	print(ans);
	return 0;
}
```

> [ARC100F Colorful Sequences](https://atcoder.jp/contests/arc100/tasks/arc100_d)

## 题意

- 给定 $n,k$ 和序列 $a_{1\dots m}$。
- 定义存在「长度为 $k$ 的连续子序列是一个连续段」的序列为 colorful 序列。
- 求所有长度为 $n$ 值域 $[1,k]$ 的 colorful 序列的所有连续子序列中有多少个恰好是 $a_{1 \dots m}$。
- $n \le 2.5 \times 10^4$，$k \le 400$，答案对 $10^9+7$ 取模。

## 题解

答案等于所有序列的答案减去不 colorful 序列的答案。

前者答案为 $k^{n-m}(n-m+1)$，考虑如何计算后者，即计算不 colorful 序列中 $a_{1\dots m}$ 的个数。

先考虑一个这样一个问题：计算不 colorful 序列的个数。

> 考虑 DP，设 $f_{i,j}$ 表示考虑前 $i$ 个数，当前极长的没有重复数的后缀长度为 $j$ 的方案数。
>
> 初始状态为 $f_{0,0} = 1$，目标答案为 $\sum_{j=0}^{k-1} f_{n,j}$，转移如下：
> $$
> f_{i,j} \leftarrow f_{i-1,j^\prime} \cdot\begin{cases}0 & j^\prime + 1 < j \\\\k - j^\prime & j^\prime + 1 = j \\\\1 & j^\prime + 1 > j\end{cases}
> $$
> 复杂度 $\mathcal O(nk^2)$，前缀和优化一下为 $\mathcal O(nk)$。

接下来考虑原问题：计算不 colorful 序列中 $a_{1\dots m}$ 的个数。

考虑三种情况：

1. $a_{1\dots m}$ 本身就是 colorful 序列，答案显然为 $0$。
2. 否则，若 $a_{1\dots m}$ 中的数互不相同，但由于 $m<k$ 所以不是 colorful 序列。
   考虑计算不 colorful 序列中「长度为 $m$ 的其中的数互不相同的连续子序列」个数，然后除以 $k^{\underline{m}}$ 就是答案。
   计算方法就是上面的 DP，另外定义一个 $g_{i,j}$ 表示 $f_{i,j}$ 中 $a_{1\dots m}$ 的个数，当 $j \ge m$ 时让 $g_{i,j}$ 加上 $f_{i,j}$，然后一起转移即可。
3. 否则，意味着 $a_{1 \dots m}$ 中有相同的数且不是 colorful 序列。
   先求出极长的没有重复数的前后缀长度，设为 $l,r$。
   同样采用上面的 DP，只是将初值改成 $f_{0,l} = 1$，同理设 $g_{0,r} = 1$。
   枚举 $a_{1\dots m}$ 的开头位置 $i$，则方案数为 $\left(\sum_{j=0}^{k-1} f_{i-1,j}\right)\left(\sum_{j=0}^{k-1} g_{n-(i-1)-m,j}\right)$。

总时间复杂度 $\mathcal O(nk)$。

## 代码

```cpp
const int N = 2.5e4 + 7, K = 407;
int n, k, m, a[N], l, r;
bool v[K];
modint f[N][K], g[N][K], ans;

inline void clear() {
	for (int i = 1; i <= k; i++) v[i] = 0;
}

inline bool pd(int l, int r) {
	clear();
	for (int i = l; i <= r; i++)
		if (v[a[i]]) return 0;
		else v[a[i]] = 1;
	return 1;
}

inline bool colorful() {
	for (int l = 1, r = k; r <= m; l++, r++)
		if (pd(l, r)) return 1;
	return 0;
}

inline void DP(modint f[N][K]) {
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j < k; j++)
			f[i][j] = (f[i-1][j-1] - f[i-1][j]) * (k - j + 1) + f[i-1][j];
		for (int j = k - 1; ~j; j--) f[i][j] += f[i][j+1];
	}
}

int main() {
	rd(n, k, m), rda(a, m);
	if (colorful()) return print(((modint)k ^ (n - m)) * (n - m + 1)), 0;
	clear();
	for (int i = 1; i <= m; i++)
		if (v[a[i]]) break;
		else v[a[i]] = 1, ++l;
	clear();
	for (int i = m; i; i--)
		if (v[a[i]]) break;
		else v[a[i]] = 1, ++r;
	if (l == m) {
		f[0][0] = 1;
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j < k; j++)
				f[i][j] = (f[i-1][j-1] - f[i-1][j]) * (k - j + 1) + f[i-1][j],
				g[i][j] = (g[i-1][j-1] - g[i-1][j]) * (k - j + 1) + g[i-1][j] + (j >= m) * f[i][j];
			for (int j = k - 1; ~j; j--)
				f[i][j] += f[i][j+1], g[i][j] += g[i][j+1];
		}
		ans = g[n][0];
		for (int i = k; i > k - m; i--) ans /= i;
	} else {
		for (int i = 0; i <= l; i++) f[0][i] = 1;
		for (int i = 0; i <= r; i++) g[0][i] = 1;
		DP(f), DP(g);
		for (int i = 1, j = m; j <= n; i++, j++)
			ans += f[i-1][0] * g[n-j][0];
	}
	print((((modint)k ^ (n - m)) * (n - m + 1)) - ans);
	return 0;
}
```

> [ARC095F Permutation Tree](https://atcoder.jp/contests/arc095/tasks/arc095_d)

## 题意

- 对于一个 $1\sim n$ 的排列 $p_{1\cdots n}$，可以通过如下方法生成一棵树：
  - 对于 $i$，如果 $p_i \ne 1$，则找到一个最大的 $j$ 满足 $p_j < p_i$，在 $i,j$ 之间连边。
- 现在要求找到一个字典序最小的**生成的树与给定的树同构**的排列，或判断无解。
- $n \le 10^5$。

## 题解

给定树必须要是一个毛毛虫，即去掉叶子之后要是一条链。

正反方向贪心一下，取字典序更小的方案即可。

## 代码

```cpp
const int N = 1e5 + 7;
int n, d[N], c[N], l, r;
vi e[N];
bool v[N];

inline int find(int x) {
	for (int y : e[x])
		if (!v[y] && d[y] != 1) return y;
	return 0;
}

inline vi work(int l, int r) {
	vi ret(1, 1), p(1, d[l] - 2);
	for (int i = 1; i <= n; i++) v[i] = 0;
	while (l != r) v[l] = 1, l = find(l), p.pb(d[l] - 2);
	int t = 1;
	for (int x : p) {
		dbg(x);
		for (int i = 1; i <= x; i++) ret.pb(t + i + 1);
		ret.pb(t + 1), t += x + 1;
	}
	ret.pb(n);
	return ret;
}

int main() {
	rd(n);
	if (n == 2) return prints("1 2"), 0;
	for (int i = 1, x, y; i < n; i++)
		rd(x, y), e[x].pb(y), e[y].pb(x), ++d[x], ++d[y];
	for (int i = 1; i <= n; i++) c[i] = d[i];
	for (int i = 1; i <= n; i++)
		if (d[i] == 1) --c[e[i][0]], --c[i];
	if (*max_element(c + 1, c + n + 1) > 2) return print(-1), 0;
	if (!*max_element(c + 1, c + n + 1)) {
		print(1, ' ');
		for (int i = 3; i < n; i++) print(i, ' ');
		print(2, ' '), print(n);
		return 0;
	}
	for (int i = 1; i <= n; i++)
		if (c[i] == 1) r = i;
	for (int i = n; i; i--)
		if (c[i] == 1) l = i;
	vi ans = min(work(l, r), work(r, l));
	for (int x : ans) print(x, ' ');
	return 0;
}
```

> [ARC101E Ribbons on Tree](https://atcoder.jp/contests/arc101/tasks/arc101_c)

## 题意

- 给定一棵 $n$ 个点的树，保证 $n$ 为偶数。
- 将 $n$ 个点分成 $\frac n2$ 个无序点对。
- 对于每个点对，将树上两点之间的最短路径上的边染色。
- 问有多少种方案使得每条边都被染色。
- $n \le 5 \times 10^3$，答案对 $10^9+7$ 取模。

## 题解

考虑容斥，设 $f(S)$ 表示强制不覆盖边集 $S$ 中的边的方案数，则答案为 $\sum_{S \subseteq E} (-1)^{|S|} f(S)$。

考虑 $f(S)$ 如何计算，设 $S$ 中的边割掉后将树分成了大小为 $a_{1},a_2,\cdots,a_t$ 这 $t$ 个连通块，则 $f(S) = \prod_{t=1}^t \left[2 | a_i\right]\left(a_i-1\right)!!$，其中 $x!!$ 表示 $x(x-2)(x-4)\cdots$。

考虑树形 DP，设 $f_{i,j}$ 表示考虑 $i$ 的子树，割掉若干条边后 $i$ 所在的连通块大小为 $j$，不包含 $i$ 所在的连通块的贡献总和。

转移就是树上背包，时间复杂度 $\mathcal O(n^2)$。

## 代码

```cpp
const int N = 5e3 + 7;
int n, s[N];
vi e[N];
modint p[N], f[N][N], ans;

void dfs(int x, int fa) {
	f[x][1] = s[x] = 1;
	for (int y : e[x])
		if (y != fa) {
			dfs(y, x);
			for (int i = s[x]; i; i--) {
				modint w = 0;
				for (int j = s[y]; j; j--)
					f[x][i+j] += f[x][i] * f[y][j], w -= p[j] * f[y][j];
				f[x][i] *= w;
			}
			s[x] += s[y];
		}
}

int main() {
