## 题意

- 给定一棵 $n$ 个点的树。
- 有 $m$ 个人，第 $i$ 个人会在 $t_i$ 时刻出现在 $v_i$，并以每时刻 $c_i$ 条边的速度向 $u_i$ 移动，到达 $u_i$ 立刻消失。出现的时段是左闭右闭的，因此如果 $v_i = u_i$，则在 $t_i$ 时刻 $i$ 仍会出现。
- 求第一次有人相遇的时刻，或判断始终无人相遇。
- $n,m \le 10^5$，$t_i,c_i \le 10^4$。

## 题解

首先考虑一条链的情况。

暴力做法显然是对 $m$ 个人两两求答案然后取 $\min$，时间复杂度 $\mathcal O(m^2)$ 无法接受。

考虑用 `multiset` 按时间顺序维护所有人的相对位置，则只有在 `multiset` 中相邻的两个人有可能是答案。

时间复杂度 $\mathcal O(m \log m)$。

扩展到树上，将树进行树链剖分，则每个人被划分为 $\mathcal O(\log n)$ 条重链和轻链。

对每条链的答案求 $\min$ 即为最终答案，时间复杂度 $\mathcal O(n + m \log m \log n)$。

## 代码

```cpp
struct frac {
	ll x, y;
	inline frac() {}
	inline frac(ll _x, ll _y = 1ll) : x(_x), y(_y) {
		ll g = __gcd(abs(x), abs(y));
		if (y < 0) g = -g;
		x /= g, y /= g;
	}
	inline friend frac operator + (frac e, frac b) { return frac(e.x * b.y + e.y * b.x, e.y * b.y); }
	inline friend frac operator - (frac e, frac b) { return frac(e.x * b.y - e.y * b.x, e.y * b.y); }
	inline friend frac operator * (frac e, frac b) { return frac(e.x * b.x, e.y * b.y); }
	inline friend frac operator / (frac e, frac b) { return frac(e.x * b.y, e.y * b.x); }
	inline friend bool operator < (frac e, frac b) { return e.x * b.y < b.x * e.y; }
	inline friend bool operator > (frac e, frac b) { return e.x * b.y > b.x * e.y; }
	inline friend bool operator <= (frac e, frac b) { return e.x * b.y <= b.x * e.y; }
	inline friend bool operator >= (frac e, frac b) { return e.x * b.y >= b.x * e.y; }
	inline friend bool operator == (frac e, frac b) { return e.x * b.y == b.x * e.y; }
};

const int N = 1e5 + 7, inf = 1e9;
int n, m, d[N], f[N], s[N], son[N], dfn[N], top[N], num;
vi e[N];
double Ans = inf;
frac tim, ans;
struct P {
	frac k, b, l, r;
	inline P() {}
	inline P(frac k, frac b, frac l, frac r) : k(k), b(b), l(l), r(r) {}
	inline friend bool operator < (P a, P b) {
		if (a.k * tim + a.b == b.k * tim + b.b)
			return a.l == b.l ? a.r == b.r ? a.k < b.k : a.r < b.r : a.l < b.l;
		return a.k * tim + a.b < b.k * tim + b.b;
	}
};
multiset<P> st;
vector<P> heavy[N], light[N];

inline int lca(int x, int y) {
	while (top[x] != top[y]) {
		if (d[top[x]] < d[top[y]]) swap(x, y);
		x = f[top[x]];
	}
	return d[x] < d[y] ? x : y;
}

inline frac dist(int x, int y) {
	return frac(d[x] + d[y] - 2 * d[lca(x,y)]);
}

void dfs(int x) {
	s[x] = 1;
	for (int y : e[x])
		if (y != f[x]) {
			f[y] = x, d[y] = d[x] + 1, dfs(y), s[x] += s[y];
			if (s[y] > s[son[x]]) son[x] = y;
		}
}

void dfs(int x, int p) {
	dfn[x] = ++num, top[x] = p;
	if (son[x]) dfs(son[x], p);
	for (int y : e[x])
		if (y != son[x] && y != f[x]) dfs(y, y);
}

inline void solve(int x, int y, frac s, frac v) {
	frac t = s + dist(x, y) / v;
	while (top[x] != top[y])
		if (d[top[x]] > d[top[y]]) {
			int p = top[x];
			heavy[p].pb(P(frac(0) - v, frac(d[x]) + v * s, s, s + frac(d[x] - d[p]) / v));
			s = s + frac(d[x] - d[p]) / v, x = top[x], p = f[x];
			light[x].pb(P(frac(0) - v, frac(d[x]) + v * s, s, s + frac(d[x] - d[p]) / v));
			s = s + frac(d[x] - d[p]) / v, x = f[x];
		} else {
			int p = top[y];
			heavy[p].pb(P(v, frac(d[y]) - v * t, t - frac(d[y] - d[p]) / v, t));
			t = t - frac(d[y] - d[p]) / v, y = top[y], p = f[y];
			light[y].pb(P(v, frac(d[y]) - v * t, t - frac(d[y] - d[p]) / v, t));
			t = t - frac(d[y] - d[p]) / v, y = f[y];
		}
	int p = top[x];
	if (d[x] > d[y]) heavy[p].pb(P(frac(0) - v, frac(d[x]) + v * s, s, t));
	else heavy[p].pb(P(v, frac(d[y]) - v * t, s, t));
}

inline frac get(P a, P b) {
	if (a.k == b.k) return a.b == b.b ? max(a.l, b.l) : frac(inf);
	frac o = (b.b - a.b) / (a.k - b.k);
	return o >= max(a.l, b.l) && o <= min(a.r, b.r) ? o : frac(inf);
}

inline void work(vector<P> p) {
	st.clear(), ans = frac(inf);
	vector<pair<P, bool>> q;
	for (P x : p) q.pb(mp(x, 1)), q.pb(mp(x, 0)); 
	sort(q.begin(), q.end(), [](pair<P, bool> x, pair<P, bool> y) {
		frac tx = x.se ? x.fi.l : x.fi.r, ty = y.se ? y.fi.l : y.fi.r;
		return tx == ty ? x.se > y.se : tx < ty;
	});
	for (auto x : q) {
		frac now = x.se ? x.fi.l : x.fi.r;
		if (now >= ans) break;
		tim = now;
		if (x.se) {
			auto tmp = st.insert(x.fi), pre = tmp, suf = tmp;
			if (pre != st.begin()) ans = min(ans, get(*--pre, *tmp));
			if (++suf != st.end()) ans = min(ans, get(*tmp, *suf));
		} else {
			auto tmp = st.lower_bound(x.fi), pre = tmp, suf = tmp;
			if (++suf != st.end() && pre != st.begin()) ans = min(ans, get(*--pre, *suf));
			st.erase(tmp);
		}
	}
	Ans = min(Ans, 1.0 * ans.x / ans.y);
}

int main() {
	rd(n), rd(m);
	for (int i = 1, x, y; i < n; i++) rd(x), rd(y), e[x].pb(y), e[y].pb(x);
	d[1] = 1, dfs(1), dfs(1, 1);
	for (int i = 1, t, c, x, y; i <= m; i++)
		rd(t), rd(c), rd(x), rd(y), solve(x, y, frac(t), frac(c));
	for (int i = 1; i <= n; i++) work(heavy[i]), work(light[i]);
	if (Ans == inf) return prints("-1"), 0;
	printf("%.10f\n", Ans);
	return 0;
}
```

> [CF671E Organizing a Race](https://codeforces.com/contest/671/problem/E)

## 题意

- 有 $n$ 个点排成一行，第 $i$ 个点与第 $i + 1$ 个点之间的距离为 $w_i$ 个单位。
- 每个点都有一个加油站，第 $i$ 个点的加油站可以给你的车加能跑 $g_i$ 个单位的油。
- 若一辆初始没有油的车能从 $l$ 一路向右开到 $r$，也能从 $r$ 一路向左开到 $l$，则称 $l,r$ 之间可以往返。
- 另外，你有 $k$ 次将某个 $g_i$ 加 $1$ 的机会。
- 请你求出在 $l,r$ 之间可以往返的情况下，$r-l+1$ 的最大值。
- $n \le 10^5$，$k,w_i,g_i \le 10^9$。

## 题解

考虑什么条件下 $l,r$ 之间可以往返。

显然为：
$$
\begin{cases}w_l \le g_l \\\\w_l + w_{l+1} \le g_l + g_{l+1} \\\\\cdots \\\\\sum_{i=l}^{r-1} w_i \le \sum_{i=l}^{r-1} g_i\end{cases}
$$
以及
$$
\begin{cases}w_{r-1} \le g_r \\\\w_{r-1} + w_{r-2} \le g_r + g_{r-1} \\\\\cdots \\\\\sum_{i=l}^{r-1} w_i \le \sum_{i=l+1}^{r} g_i\end{cases}
$$
考虑对 $w,g$ 的前缀和 $a,b$，则条件变为：
$$
\begin{cases}a_l-a_{l-1} \le b_l-b_{l-1} \\\\a_{l+1}-a_{l-1} \le b_{l+1}-b_{l-1} \\\\\cdots \\\\a_{r-1}-a_{l-1} \le b_{r-1}-b_{l-1}\end{cases}
$$
以及
$$
\begin{cases}a_{r-1} - a_{r-2} \le b_r - b_{r-1} \\\\a_{r-1} - a_{r-3} \le b_r - b_{r-2} \\\\\cdots \\\\a_{r-1} - a_{l-1} \le b_r - b_{l}\end{cases}
$$
设 $c_i = a_{i-1} - b_{i-1}$，$d_i = b_i - a_{i-1}$，则条件变为简单的两个等式：
$$
\begin{cases}c_{l} = \max_{i=l}^{r} c_i\\\\d_{r} = \max_{i=l}^{r} d_i\end{cases}
$$
若 $g_i$ 加 $1$，则对于 $j \ge i$，$b_j$ 加 $1$；对于 $j > i$，$c_j$ 减 $1$；对于 $j \ge i$，$d_j$ 加 $1$。

先考虑 $l \to r$。

从 $n$ 到 $1$ 枚举 $l$，用单调栈维护一个单调上升的子序列 $c_{x_0} < c_{x_1} < c_{x_2} < \cdots$，其中 $x_0 = l$。则 $k$ 一定是贪心地依次对 $g_{x_1-1},g_{x_2-1},\cdots$ 使用，每次将 $g_{x_i-1}$ 加 $c_{x_i} - c_{x_{i-1}}$。

再考虑 $r\to l$。

到某个 $x_p$ 后，设剩下的 $k$ 为 $k^\prime$，上一步使用完后的 $d$ 为 $d^\prime$，则要满足 $d^\prime_r + k^\prime \ge d^\prime_{l \dots r-1}$，即 $d_r + k \ge \max_{i=l}^{r-1} d^\prime_{i}$。

因此，我们可以先在单调栈上二分出只考虑 $l \to r$ 的情况下的最大 $r^\prime$，即找到满足 $c_{x_i} - c_{l} \le k$ 的最大 $x_i$，则最大 $r^\prime = x_{i+1} - 1$。

此时，最优解的范围一定在 $[l,r^\prime]$ 中，再在这个范围内的线段树上二分找到最大的 $r$，然后取每次 $r-l+1$ 的最大值即可。

具体来说，我们用线段树维护 $d^\prime$，每次往单调栈里加一个位置 $x$ 后，将单调栈中前一个位置 $y$ 的贡献 $c_{y} - c_{x}$ 加到 $d^\prime_{y-1\dots n}$ 上，退栈时相应减去。另外，对于 $l$ 左边的部分，为了方便可以将 $d^\prime$ 设为 $-\infty$。

线段树上二分时，对于一个节点 $p$，如果 $\max_{rs} d_i + k \ge \max_{1\dots p_{mid}} d^\prime_i$，则意味着 $\max_{rs} d_i$ 的 $i$ 处一定是一个合法解，因此递归往右儿子找，否则递归往左儿子找。

为什么 $\max_{rs} d_i + k \ge \max_{1\dots p_{mid}} d^\prime_i$ 就意味着 $\max_{rs} d_i$ 的 $i$ 处一定是一个合法解呢？合法条件为 $d_r + k \ge \max_{i=l}^{r-1} d^\prime_{i}$，那么 $d^\prime_{p_{mid+1}\dots i-1}$ 中有没有可能比 $d_i + k$ 大呢？

其实很显然，注意到 $d^\prime$ 是 $d$ 加上 $\le k$ 的一个数生成的就可以了。

时间复杂度 $\mathcal O(n \log n)$。

## 代码

```cpp
const int N = 1e5 + 7;
const ll inf = 1e18;
int n, ans, s[N], p;
ll k, w[N], g[N], a[N], b[N], c[N], d[N];
struct T {
	int l, r;
	ll x, z, d;
} t[N<<2];

void build(int p, int l, int r) {
	t[p].l = l, t[p].r = r, t[p].x = -inf;
	if (t[p].l == t[p].r) return;
	build(ls, l, md), build(rs, md + 1, r);
}

inline void upd(int p) {
	t[p].x = max(t[ls].x, t[rs].x);
	t[p].d = max(t[ls].d, t[rs].d);
}

inline void spd(int p) {
	if (t[p].z) {
		t[ls].x += t[p].z;
		t[ls].z += t[p].z;
		t[rs].x += t[p].z;
		t[rs].z += t[p].z;
		t[p].z = 0;
	}
}

void setx(int p, int x, ll k) {
	if (t[p].l == t[p].r)
		return t[p].x = t[p].d = k, void();
	spd(p);
	if (x <= md) setx(ls, x, k);
	else setx(rs, x, k);
	upd(p);
}

void add(int p, int l, int r, ll k) {
	if (t[p].l >= l && t[p].r <= r)
		return t[p].x += k, t[p].z += k, void();
	spd(p);
	if (l <= md) add(ls, l, r, k);
	if (r > md) add(rs, l, r, k);
	upd(p);
}

int ask(int p, int l, int r, ll x) {
	if (t[p].l > r || t[p].d + k < x) return 0;
	if (t[p].l == t[p].r) return t[p].l;
	spd(p);
	if (md < l) return ask(rs, l, r, x);
	if (r <= md) return ask(ls, l, r, x);
	if (t[rs].d + k >= max(x, t[ls].x)) {
		int ret = ask(rs, l, r, max(x, t[ls].x));
		if (ret) return ret;
	}
	return ask(ls, l, r, x);
}

int main() {
	rd(n), rd(k), rda(w, n - 1), rda(g, n);
	for (int i = 1; i < n; i++) a[i] = a[i-1] + w[i];
	for (int i = 1; i <= n; i++) b[i] = b[i-1] + g[i];
	for (int i = 1; i <= n; i++) c[i] = a[i-1] - b[i-1];
	for (int i = 1; i <= n; i++) d[i] = b[i] - a[i-1];
	build(1, 1, n);
	for (int i = n; i; i--) {
		while (p && c[i] >= c[s[p]]) {
			if (p > 1)
				add(1, s[p-1] - 1, n, c[s[p]] - c[s[p-1]]);
			--p;
		}
		s[++p] = i, setx(1, i, d[i]);
		if (p > 1) add(1, s[p-1] - 1, n, c[s[p-1]] - c[i]);
		int l = 1, r = p;
		while (l < r) {
			int mid = (l + r) >> 1;
			if (c[s[mid]] - c[i] <= k) r = mid;
			else l = mid + 1;
		}
		r = r == 1 ? n : s[r-1] - 1;
		ans = max(ans, ask(1, i, r, -inf) - i + 1);
	}
	print(ans);
	return 0;
}
```

> [CF666E Forensic Examination](https://codeforces.com/contest/666/problem/E)

## 题意

- 给定一个字符串 $s$，以及 $m$ 个字符串 $t_{1 \dots m}$。
- $q$ 次询问，每次询问 $s[p_l:p_r]$ 在字符串 $t_{l\dots r}$ 中的哪个串里作为子串出现的次数最多，如果有多个答案，输出最小的一个。
- $|s|,q \le 5 \times 10^5$，$m,\sum_{i=1}^m |t_i| \le 5 \times 10^4$。

## 题解

将 $s$ 和 $t_{1\dots m}$ 合成一个字符串，中间用一个其它的分隔符隔开。

设这个新字符串为 $s^\prime$，有 $|s^\prime| = |s| + \sum_{i=1}^{m}|t_i| + m$。

对这个字符串求 SA，则一次询问 $(p_l,p_r,l,r)$ 的答案为：

SA 中 $p_l$ 所在的位置前后 $\operatorname{height}$ 不小于 $p_r - p_l + 1$ 的区间中，每个后缀对应 $t_i$ 的 $i$ 在 $[l,r]$ 中的众数。

如果我们按照 $\operatorname{height}$ 由大到小合并，并建出 kruskal 重构树。

那一次询问就等价于查询一棵子树内颜色在 $[l,r]$ 中的众数，倍增找到子树的根后，线段树合并即可。

总时间复杂度 $\mathcal O(|s^\prime| \log |s^\prime| + q (\log |s^\prime| + \log m))$。

## 代码

```cpp
const int N = 6e5 + 7, M = 21;
int n, m, len[N], q;
char s[N], ss[N];
struct SA {
	int n, m = 127, sa[N], rk[N<<1], tp[N<<1], tx[N], he[N];
	char s[N];
	inline void sort() {
		for (int i = 1; i <= m; i++) tx[i] = 0;
		for (int i = 1; i <= n; i++) ++tx[rk[i]];
		for (int i = 1; i <= m; i++) tx[i] += tx[i-1];
		for (int i = n; i; i--) sa[tx[rk[tp[i]]]--] = tp[i];
	}
	inline bool pd(int i, int j, int k) {
		return tp[i] == tp[j] && tp[i+k] == tp[j+k];
	}
	inline void main() {
		for (int i = 1; i <= n; i++) rk[i] = s[i], tp[i] = i;
		sort();
		for (int k = 1, p; p < n; k <<= 1, m = p) {
			p = 0;
			for (int i = 1; i <= k; i++) tp[++p] = n - k + i;
			for (int i = 1; i <= n; i++)
				if (sa[i] > k) tp[++p] = sa[i] - k;
			sort(), swap(rk, tp), rk[sa[1]] = p = 1;
			for (int i = 2; i <= n; i++)
				rk[sa[i]] = p += !pd(sa[i], sa[i-1], k);
		}
	}
	inline void height() {
		for (int i = 1, p = 0; i <= n; i++) {
			if (p) --p;
			int j = sa[rk[i]-1];
			while (s[i+p] == s[j+p]) ++p;
			he[rk[i]] = p;
		}
	}
} sa;
struct T {
	int l, r;
	pi x;
} t[N<<6|1];
int p[N], rt[N<<1], tot, d[N<<1], num, f[N<<1][M], u[N<<1];

int get(int x) {
	return x == u[x] ? x : (u[x] = get(u[x]));
}

inline pi operator + (pi x, pi y) {
	return x.se < y.se ? y : x;
}

int ins(int l, int r, int x) {
	int p = ++tot;
	if (l == r) return t[p].x = mp(x, 1), p;
	int mid = (l + r) >> 1;
	if (x <= mid) t[p].l = ins(l, mid, x);
	else t[p].r = ins(mid + 1, r, x);
	t[p].x = t[t[p].l].x + t[t[p].r].x;
	return p;
}

int merge(int p, int q, int l, int r) {
	if (!p || !q) return p | q;
	int o = ++tot;
	if (l == r) return t[o].x = t[p].x, t[o].x.se += t[q].x.se, o;
	int mid = (l + r) >> 1;
	t[o].l = merge(t[p].l, t[q].l, l, mid);
	t[o].r = merge(t[p].r, t[q].r, mid + 1, r);
	t[o].x = t[t[o].l].x + t[t[o].r].x;
	return o;
}

pi ask(int p, int l, int r, int L, int R) {
	if (l >= L && r <= R) return t[p].x;
	int mid = (l + r) >> 1;
	pi o = mp(0, 0);
	if (L <= mid) o = ask(t[p].l, l, mid, L, R);
	if (R > mid) o = o + ask(t[p].r, mid + 1, r, L, R);
	return o;
}

int main() {
	rds(s, n), rd(m);
	for (int i = 1; i <= m; i++) {
		rds(ss, len[i]);
		for (int j = 1; j <= len[i]; j++) sa.s[++sa.n] = ss[j];
		sa.s[++sa.n] = sa.m, len[i] += len[i-1] + 1;
	}
	for (int i = 1; i <= n; i++) sa.s[++sa.n] = s[i];
	sa.main(), sa.height();
	for (int i = 1; i <= m; i++)
		for (int j = len[i-1] + 1; j < len[i]; j++)
			rt[sa.rk[j]] = ins(1, m, i);
	for (int i = 1; i <= sa.n; i++) p[i] = u[i] = i;
	sort(p + 2, p + sa.n + 1, [](int i, int j) {
		return sa.he[i] > sa.he[j];
	});
	num = sa.n;
	for (int i = 2; i <= sa.n; i++) {
		d[++num] = sa.he[p[i]];
		int x = get(p[i]), y = get(p[i] - 1);
		f[x][0] = f[y][0] = u[x] = u[y] = u[num] = num;
		rt[num] = merge(rt[x], rt[y], 1, m);
	}
	for (int j = 1; j < M; j++)
		for (int i = 1; i <= num; i++)
			f[i][j] = f[f[i][j-1]][j-1];
	rd(q);
	for (int i = 1, l, r, pl, pr; i <= q; i++) {
		rd(l), rd(r), rd(pl), rd(pr);
		int x = sa.rk[pl+len[m]], k = pr - pl + 1;
		for (int j = M - 1; ~j; j--)
			if (d[f[x][j]] >= k) x = f[x][j];
		pi ans = ask(rt[x], 1, m, l, r);
		print(ans.fi ? ans.fi : l, ' '), print(ans.se);
	}
	return 0;
}
```

> [CF700E Cool Slogans](https://codeforces.com/contest/700/problem/E)

## 题意

- 给定一个长度为 $n$ 的字符串 $s$。
- 你要构造一个最长的字符串序列 $t_{1\dots k}$，满足：
  1. 对于 $i \in [1,k]$，$t_i$ 为 $s$ 的子串。
  2. 对于 $i \in [2,k]$，$t_i$ 在 $t_{i-1}$ 中出现了至少两次。
- $n \le 2 \times 10^5$。

## 题解

对字符串建 SAM，用（可持久化）线段树合并求出每个节点的 $\operatorname{endpos}$ 集合。

在 $\operatorname{parent}$ 树上从根向下 dp，设 $f_i$ 表示到节点 $i$ 时的最大值。

如果一个父节点的子串在子节点的子串中出现了至少两次，则转移时 $f$ 加一，否则不变。

考虑如何判断是否出现了至少两次，设此时的子节点为 $x$，父节点为 $pa_x$。

找到 $x$ 对应的 $\operatorname{endpos}$ 中的任意一个位置 $pos$，则 $pos$ 处 $pa_x$ 的子串一定出现了一次。

那么另一次只要在 $[pos - \operatorname{len}(x) + \operatorname{len}(pa_x), pos - 1]$ 中有出现就行了。

总时间复杂度 $\mathcal O(n \log n)$。

## 代码

```cpp
const int N = 2e5 + 7;
struct T {
	int l, r;
} t[N<<6|1];
int rt[N<<1], f[N<<1], g[N<<1], tot, ans = 1;

int insert(int l, int r, int x) {
	int p = ++tot;
	if (l == r) return p;
	int mid = (l + r) >> 1;
	if (x <= mid) t[p].l = insert(l, mid, x);
	else t[p].r = insert(mid + 1, r, x);
	return p;
}

int merge(int p, int q) {
	if (!p || !q) return p | q;
	int o = ++tot;
	t[o].l = merge(t[p].l, t[q].l);
	t[o].r = merge(t[p].r, t[q].r);
	return o;
}

bool ask(int p, int l, int r, int L, int R) {
	if (!p) return 0;
	if (L <= l && R >= r) return 1;
	int mid = (l + r) >> 1;
	if (L <= mid && ask(t[p].l, l, mid, L, R)) return 1;
	if (R > mid && ask(t[p].r, mid + 1, r, L, R)) return 1;
	return 0;
}

struct SAM {
	int n, l, ch[N<<1][26], len[N<<1], pa[N<<1], t;
	char s[N];
	int pos[N<<1];
	inline void init() { pa[0] = -1; }
	inline void add(int c, int o) {
		int w = ++t, p = l;
		len[w] = len[l] + 1, pos[w] = o;
		while (~p && !ch[p][c]) ch[p][c] = w, p = pa[p];
		if (!~p) return pa[l=w] = 0, void();
		int q = ch[p][c];
		if (len[p] + 1 == len[q]) return pa[l=w] = q, void();
		int k = ++t;
		pa[k] = pa[q], pos[k] = pos[q], memcpy(ch[k], ch[q], sizeof(ch[k]));
		len[k] = len[p] + 1, pa[w] = pa[q] = k;
		while (~p && ch[p][c] == q) ch[p][c] = k, p = pa[p];
		l = w;
	}
	inline void build() {
		init();
		for (int i = 1; i <= n; i++) add(s[i] - 'a', i);
	}
	int b[N<<1], c[N];
	inline void sort() {
		for (int i = 1; i <= t; i++) ++c[len[i]];
		for (int i = 1; i <= n; i++) c[i] += c[i-1];
		for (int i = 1; i <= t; i++) b[c[len[i]]--] = i;
	}
	inline void work() {
		for (int i = 1, p = 0; i <= n; i++)
			p = ch[p][s[i]-'a'], rt[p] = insert(1, n, i);
		for (int i = t; i; i--)
			rt[pa[b[i]]] = merge(rt[pa[b[i]]], rt[b[i]]);
		for (int i = 1; i <= t; i++) {
			int x = b[i];
			if (!pa[x]) {
				f[x] = 1, g[x] = x;
				continue;
			}
			if (ask(rt[g[pa[x]]], 1, n, pos[x] - len[x] + len[g[pa[x]]], pos[x] - 1))
				f[x] = f[pa[x]] + 1, g[x] = x;
			else f[x] = f[pa[x]], g[x] = g[pa[x]];
			ans = max(ans, f[x]);
		}
	}
} sam;

int main() {
	rd(sam.n), rds(sam.s, sam.n), sam.build();
	sam.sort(), sam.work(), print(ans);
	return 0;
}
```

