## 题意

- 平面直角坐标系中有四个整点。
- 你可以将每个点水平或者垂直移动到一个整点，使得这四个点恰好成为一个平行于坐标轴的正方形的顶点（正方形不能退化成一个点）。
- 如果存在移动方案，则还要最小化对应点移动的最大距离。

## 题解

四个点明示超级大暴力，知道暴力怎么写就行了。

枚举 $2^4 = 16$ 种移动方向。

对于每种移动方向，由于可能有重合的，不妨设水平移动不少于垂直移动。

考虑每种**有解**的情况：

1. 2 水平 2 垂直：判断四个交点是否构成正方形。
2. 2 水平 1 垂直：相当于固定了正方形的一条边，枚举可能的正方形（只有两个）。
3. 2 水平 0 垂直：相当于固定了正方形的边长，相当于线性规划，也可以二分。

疯狂分类讨论 + 大力枚举就没了。

代码参考了兔兔的。

## 代码

```cpp
const int inf = 1e9;
int p[4], x[4], y[4], ax[4], ay[4], bx[4], by[4], cx, cy, ans;
int lx[4], xy[4][5], ly[4], yx[4][5];

inline void check() {
	int d01 = abs(bx[0] == bx[1] ? by[0] - by[1] : bx[0] - bx[1]);
	int d02 = abs(bx[0] == bx[2] ? by[0] - by[2] : bx[0] - bx[2]);
	int d31 = abs(bx[3] == bx[1] ? by[3] - by[1] : bx[3] - bx[1]);
	int d32 = abs(bx[3] == bx[2] ? by[3] - by[2] : bx[3] - bx[2]);
	if (d01 != d02 || d02 != d31 || d31 != d32) return;
	do {
		int mx = 0;
		for (int i = 0; i < 4; i++) {
			if (x[i] != bx[p[i]] && y[i] != by[p[i]]) {
				mx = inf;
				break;
			}
			if (x[i] == bx[p[i]]) mx = max(mx, abs(y[i] - by[p[i]]));
			else mx = max(mx, abs(x[i] - bx[p[i]]));
		}
		if (mx < ans) {
			ans = mx;
			for (int i = 0; i < 4; i++) ax[i] = bx[p[i]], ay[i] = by[p[i]];
		}
	} while (next_permutation(p, p + 4));
}

inline void pd() {
	if (cx == 2 && cy == 2) {
		bx[0] = lx[0], by[0] = ly[0];
		bx[1] = lx[0], by[1] = ly[1];
		bx[2] = lx[1], by[2] = ly[0];
		bx[3] = lx[1], by[3] = ly[1];
		check();
	} else if (cy == 1) {
		bx[0] = lx[0], by[0] = ly[0];
		bx[1] = lx[1], by[1] = ly[0];
		bx[2] = lx[0], by[2] = ly[0] + (lx[0] - lx[1]);
		bx[3] = lx[1], by[3] = ly[0] + (lx[0] - lx[1]);
		check();
		bx[2] = lx[0], by[2] = ly[0] - (lx[0] - lx[1]);
		bx[3] = lx[1], by[3] = ly[0] - (lx[0] - lx[1]);
		check();
	} else if (cx == 1) {
		bx[0] = lx[0], by[0] = ly[0];
		bx[1] = lx[0], by[1] = ly[1];
		bx[2] = lx[0] + (ly[0] - ly[1]), by[2] = ly[0];
		bx[3] = lx[0] + (ly[0] - ly[1]), by[3] = ly[1];
		check();
		bx[2] = lx[0] - (ly[0] - ly[1]), by[2] = ly[0];
		bx[3] = lx[0] - (ly[0] - ly[1]), by[3] = ly[1];
		check();
	} else if (cy == 0) {
		int d = abs(lx[0] - lx[1]);
		sort(xy[0] + 1, xy[0] + 3);
		sort(xy[1] + 1, xy[1] + 3);
		int a[4] = {xy[0][1], xy[0][2] - d, xy[1][1], xy[1][2] - d};
		sort(a, a + 4);
		int z = (a[0] + a[3]) >> 1;
		bx[0] = lx[0], by[0] = z;
		bx[1] = lx[0], by[1] = z + d;
		bx[2] = lx[1], by[2] = z;
		bx[3] = lx[1], by[3] = z + d;
		check();
	} else {
		int d = abs(ly[0] - ly[1]);
		sort(yx[0] + 1, yx[0] + 3);
		sort(yx[1] + 1, yx[1] + 3);
		int a[4] = {yx[0][1], yx[0][2] - d, yx[1][1], yx[1][2] - d};
		sort(a, a + 4);
		int z = (a[0] + a[3]) >> 1;
		bx[0] = z, by[0] = ly[0];
		bx[1] = z + d, by[1] = ly[0];
		bx[2] = z, by[2] = ly[1];
		bx[3] = z + d, by[3] = ly[1];
		check();
	}
}

inline void solve() {
	ans = inf;
	for (int i = 0; i < 4; i++) rd(x[i]), rd(y[i]);
	for (int k = 0; k < 16; k++) {
		cx = cy = 0;
		for (int i = 0; i < 4; i++)
			if (k >> i & 1) {
				int o = -1;
				for (int j = 0; j < cx; j++) if (lx[j] == x[i]) o = j;
				if (~o) xy[o][++*xy[o]] = y[i];
				else xy[cx][*xy[cx] = 1] = y[i], lx[cx++] = x[i];
			} else {
				int o = -1;
				for (int j = 0; j < cy; j++) if (ly[j] == y[i]) o = j;
				if (~o) yx[o][++*yx[o]] = x[i];
				else yx[cy][*yx[cy] = 1] = x[i], ly[cy++] = y[i];
			}
		if (max(cx, cy) != 2 || (!cy && *xy[0] != 2) || (!cx && *yx[0] != 2)) continue;
		pd();
	}
	if (ans == inf) return print(-1), void();
	print(ans);
	for (int i = 0; i < 4; i++) print(ax[i], ' '), print(ay[i]);
}

int main() {
	for (int i = 0; i < 4; i++) p[i] = i;
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
```

> [CF708E Student's Camp](https://codeforces.com/contest/708/problem/E)

## 题意

- 有一个 $(n+2) \times m$ 的网格。
- 除了第一行和最后一行，其他每一行每一天最左边和最右边的格子都有 $p$ 的概率消失。
- 求 $k$ 天后，网格始终保持连通的概率。
- $n,m \le 1.5 \times 10^3$，$k \le 10^5$，答案对 $10^9+7$ 取模。

## 题解

网格始终保持连通，等价于 $k$ 天后任意相邻两行剩下的区间有交。

考虑区间 dp，设 $f_{i,l,r}$ 表示前 $i$ 行连通且第 $i$ 行剩下的区间为 $[l,r]$ 的概率。

初始条件为 $f_{0,1,m} = 1$，转移：

$$
f_{i,l,r} = p_{l,r}\sum_{[l^\prime, r^\prime] \cap [l,r] \ne \varnothing} f_{i-1,l^\prime,r^\prime}
$$

其中 $p_{l,r}$ 表示 $k$ 天后剩下 $[l,r]$ 的概率，有 $p_{l,r} = p_{l-1} \times p_{m-r}$，$p_i = \binom{k}{i} p^i (1-p)^{k-i}$。

直接做是 $\mathcal O(nm^2)$ 的，显然无法接受。

设 $fr_{i,r} = \sum_{l\le r} f_{i,l,r}$，$sr_{i,j} = \sum_{r \le j} fr_{i,r}$。

同理设 $fl_{i,l} = \sum_{l \le r} f_{i,l,r}$，$sl_{i,j} = \sum_{l \ge j} fl_{i,l}$。

由于左右完全对称，因此 $fl_{i,j} = fr_{i,m+1-j}$，$sl_{i,j} = sr_{i,m+1-j}$。

则有：
$$
\begin{aligned}f_{i,l,r}&= p_{l,r}\sum_{[l^\prime, r^\prime] \cap [l,r] \ne \varnothing} f_{i-1,l^\prime,r^\prime} \\\\&= p_{l,r}(sr_{i-1,m} - sr_{i-1,l-1} - sl_{i-1,r+1}) \\\\&= p_{l,r}(sr_{i-1,m} - sr_{i-1,l-1} - sr_{i-1,m-r})\end{aligned}
$$
于是我们只需要计算 $fr_{i,j}$，然后前缀和求出 $sr_{i,j}$ 即可。

又有：
$$
\begin{aligned}fr_{i,r}&= \sum_{l\le r} f_{i,l,r} \\\\&= \sum_{l\le r} p_{l,r}(sr_{i-1,m} - sr_{i-1,l-1} - sr_{i-1,m-r})\\\\&= \left((sr_{i-1,m}-sr_{i-1,m-r})p_{m-r}\sum_{l\le r} p_{l-1}\right) - \left(p_{m-r} \sum_{l\le r} p_{l-1} sr_{i-1,l-1}\right) \\\\&= p_{m-r}\left((sr_{i-1,m}-sr_{i-1,m-r})\sum_{l\le r} p_{l-1} - \sum_{l\le r} p_{l-1} sr_{i-1,l-1}\right)\end{aligned}
$$
那么我们可以预处理 $q_r = \sum_{l\le r}p_{l-1}$，$g_{i,r} = \sum_{l \le r} p_{l-1}sr_{i,l-1}$，然后 $\mathcal O(nm)$ 计算出所有的 $fr_{i,j},sr_{i,j}$，从而计算出最终的答案，也就是 $sr_{n,m}$。

## 代码

```cpp
const int N = 1.5e3 + 7;
int n, m, k, a, b;
modint x, p[N], q[N], f[N][N], s[N][N], g[N][N];

inline modint binom(int i, int j) {
	modint a = 1, b = 1;
	for (int k = 1; k <= j; k++) a *= i + 1 - k, b *= k;
	return a / b;
}

int main() {
	rd(n), rd(m), rd(a), rd(b), rd(k), x = (modint)a / b;
	for (int i = 0; i <= min(m, k); i++)
		p[i] = binom(k, i) * (x ^ i) * ((1 - x) ^ (k - i));
	for (int i = 1; i <= m; i++) q[i] = q[i-1] + p[i-1];
	f[0][m] = s[0][m] = 1;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			f[i][j] = p[m-j] * ((s[i-1][m] - s[i-1][m-j]) * q[j] - g[i-1][j]),
			s[i][j] = s[i][j-1] + f[i][j],
			g[i][j] = g[i][j-1] + p[j-1] * s[i][j-1];
	print(s[n][m]);
	return 0;
}
```

> [CF696F ...Dary!](https://codeforces.com/contest/696/problem/F)

## 题意

- 给定一个 $n$ 个点的严格凸多边形。
- 你要最小化 $r$，使得可以在这个多边形内或多边形上找到两个点，以它们为圆心以 $r$ 为半径作两个圆，满足多边形的每条边所在的直线与至少一个圆有交点。
- $n \le 300$，答案精度误差 $\le 10^{-6}$。

## 题解

首先二分答案，设此时二分的值为 $r$。

对于一个直线集，如何判断多边形内是否存在一个点，满足以它为圆心以 $r$ 为半径作的圆与直线集中的直线有交点呢？

对于每条直线，这个点一定在与这条直线相距 $r$ 的两条平行线内，也就是两个半平面的交。而多边形也可以看成若干个半平面的交，于是问题变成这若干个半平面是否有交。

那么，如果我们能够把边分成两类，第一类和第二类分别有解，则说明此时的 $r$ 满足条件。

注意到，最终的最优解一定是两个多边形的顶点分隔成的两类，因为如果不是，显然可以通过调整达到更优解。

于是我们可以 $\mathcal O(n)$ two pointers，$\mathcal O(n \log n)$ 半平面交判定。

总时间复杂度 $\mathcal O(n^2 \log n \log w)$。

我的计算几何板子比较丑，所以被卡常了，稍微卡一下就过去了。

## 代码

```cpp
const double eps = 1e-10, PI = acos(-1);

struct P {
	double x, y;
	inline P() {}
	inline P(double x, double y) : x(x), y(y) {}
	inline P &operator += (P o) { return x += o.x, y += o.y, *this; }
	inline P &operator -= (P o) { return x -= o.x, y -= o.y, *this; }
	inline P &operator *= (double o) { return x *= o, y *= o, *this; }
	inline P &operator /= (double o) { return x /= o, y /= o, *this; }
	inline friend P operator + (P a, P b) { return a += b; }
	inline friend P operator - (P a, P b) { return a -= b; }
	inline friend P operator * (P a, double b) { return a *= b; }
	inline friend P operator / (P a, double b) { return a /= b; }
	inline friend bool operator < (P a, P b) { return fabs(a.x - b.x) < eps ? a.y < b.y : a.x < b.x; }
	inline friend bool operator == (P a, P b) { return !(a < b) && !(b < a); }
	inline friend double operator * (P a, P b) { return a.x * b.x + a.y * b.y; }
	inline friend double operator % (P a, P b) { return a.x * b.y - a.y * b.x; }
	inline friend double operator ^ (P a, P b) { return a * b / a.l() / b.l(); }
	inline double a() { return atan2(y, x); }
	inline double l() { return sqrt(*this * *this); }
	inline void r(double o) { double s = sin(o), c = cos(o), X = x * c - y * s, Y = x * s + y * c; x = X, y = Y; }
};

struct L {
	P a, b;
	double c;
	inline L() {}
	inline L(P a, P b) : a(a), b(b) { c = b.a(); }
	inline friend P operator * (L a, L b) { return a.a + a.b * (b.b % (a.a - b.a) / (a.b % b.b)); }
	inline friend double operator / (L a, P b) { return fabs(a.b % (b - a.a)) / a.b.l(); }
	inline friend bool operator < (L a, L b) { return fabs(a.c - b.c) < eps ? (b.a - a.a) % a.b < 0 : a.c < b.c; }
};

inline deque<P> half_plane(vector<L> l) {
	sort(l.begin(), l.end());
	deque<P> r;
	deque<L> q;
	for (L o : l) {
		while (r.size() && (r.back() - o.a) % o.b > 0)
			q.pop_back(), r.pop_back();
		while (r.size() && (r.front() - o.a) % o.b > 0)
			q.pop_front(), r.pop_front();
		if (q.size() && fabs(o.b % q.back().b) < eps) {
			if (fabs(o.b.a() - q.back().b.a()) > eps)
				return r.clear(), r;
			q.pop_back();
			if (r.size()) r.pop_back();
		}
		if (q.size()) r.pb(q.back() * o);
		q.pb(o);
	}
	while (r.size() && (r.back() - q.front().a) % q.front().b > 0)
		q.pop_back(), r.pop_back();
	if (q.size() < 3u) r.clear();
	else r.pb(q.front() * q.back());
	return r;
}

int n;
vector<L> l, q; 
P p1, p2, ans1, ans2;

inline bool pd(int i, int j, double r, P& t) {
	vector<L> s = q;
	for (int k = i; k <= j; k++) {
		L o = l[k];
		P p = o.b;
		p.r(PI / 2);
		p *= r / p.l();
		o.a += p, o.b *= -1, o.c = o.b.a();
		s.pb(o);
	}
	deque<P> p = half_plane(s);
	if (!p.size()) return 0;
	return t = p.back(), 1;
}

inline bool pd(double r) {
	for (int i = 0, j = 0; i < n; i++) {
		while (j < i + n - 2 && pd(i, j, r, p1)) ++j;
		if (pd(j, i + n - 1, r, p2)) return 1;
	}
	return 0;
}

int main() {
	rd(n);
	vector<P> p;
	for (int i = 1, x, y; i <= n; i++) rd(x), rd(y), p.pb(P(x, y));
	p.pb(p[0]);
	for (int i = 0; i < n; i++) l.pb(L(p[i], p[i+1] - p[i]));
	p.pop_back(), q = l;
	for (int i = 0; i < n; i++) l.pb(l[i]);
	double l = 0, r = 1e5;
	while (r - l > eps) {
		double mid = (l + r) / 2;
		if (pd(mid)) r = mid, ans1 = p1, ans2 = p2;
		else l = mid;
	}
	printf("%.10f\n", r);
	printf("%.10f %.10f\n", ans1.x, ans1.y);
	printf("%.10f %.10f\n", ans2.x, ans2.y);
	return 0;
}
```

> [CF685C Optimal Point](https://codeforces.com/contest/685/problem/C)

## 题意

- 立体直角坐标系中有 $n$ 个整点。
- 求一个整点满足到这 $n$ 个整点的曼哈顿距离的最大值最小。
- $n \le 10^5$。

## 题解

显然先二分答案。

考虑如何 check，假设此时二分到的值为 $d$。

则我们可以得到 $n$ 个限制 $|x - x_i| + |y - y_i| + |z - z_i| \le d$。

不妨设 $x_i = y_i = z_i = 0$，我们考虑 $|x| + |y| + |z| \le d$ 的情况。

枚举每个绝对值取正取负，我们可以列出 $2^3 = 8$ 个不等式。

合并这 $8n$ 个不等式，最终会得到一个不等式组：

$$
\begin{cases}l \leq x+y+z \leq r \\\\lx \leq-x+y+z \leq rx \\\\ly \leq x-y+z \leq ry \\\\lz \leq x+y-z \leq rz\end{cases}
$$

设 $a=-x+y+z$，$b=x-y+z$，$c=x+y-z$，则 $x=\frac{b+c}{2}$，$y=\frac{a+c}{2}$，$z=\frac{a+b}{2}$，且 $x+y+z = a+b+c$，且 $a,b,c$ 奇偶性相同。

令 $a = 2a^{\prime} + r$，$b = 2b^{\prime} + r$，$c = 2c^{\prime} + r$，其中 $r \in [0,1]$，则我们最终得到的不等式组为：
$$
\begin{cases}l^{\prime} \leq a^{\prime}+b^{\prime}+c^{\prime} \leq r^{\prime} \\\\lx^{\prime} \leq a^{\prime} \leq rx^{\prime} \\\\ly^{\prime} \leq b^{\prime} \leq ry^{\prime} \\\\lz^{\prime} \leq c^{\prime} \leq rz^{\prime}\end{cases}
$$
我们要求出这个不等式组的一组解。

先贪心的设 $a^{\prime} = lx^{\prime}$，$b^{\prime} = ly^{\prime}$，$c^{\prime} = lz^{\prime}$，若不满足 $l^{\prime} \leq a^{\prime}+b^{\prime}+c^{\prime} \leq r^{\prime}$，则一个一个调大 $a^{\prime}, b^{\prime}, c^{\prime}$。

这样我们就可以 $\mathcal O(n)$ check 并构造了，时间复杂度 $\mathcal O(n \log w)$。

说句题外话，代码不太会写，偷偷看一眼兔兔的，发现他偷偷看了题解代码（

## 代码

```cpp
const int N = 1e5 + 7;
const ll inf = 4e18;
#define Max(a, b) (a = a > b ? a : b)
#define Min(a, b) (a = a < b ? a : b)
int n;
ll x[N], y[N], z[N], X, Y, Z, mx, mxx, mxy, mxz, mn, mnx, mny, mnz;

inline bool pd(ll o) {
	mx = mxx = mxy = mxz = inf, mn = mnx = mny = mnz = -inf;
	for (int i = 1; i <= n; i++)
		Min(mx, o + x[i] + y[i] + z[i]),
		Min(mxx, o - x[i] + y[i] + z[i]),
		Min(mxy, o + x[i] - y[i] + z[i]),
		Min(mxz, o + x[i] + y[i] - z[i]),
		Max(mn, -o + x[i] + y[i] + z[i]),
		Max(mnx, -o - x[i] + y[i] + z[i]),
		Max(mny, -o + x[i] - y[i] + z[i]),
		Max(mnz, -o + x[i] + y[i] - z[i]);
	for (int i = 0; i < 2; i++) {
		ll l = mn + ((mn & 1) ^ i), r = mx - ((mx & 1) ^ i);
		ll lx = mnx + ((mnx & 1) ^ i), rx = mxx - ((mxx & 1) ^ i);
		ll ly = mny + ((mny & 1) ^ i), ry = mxy - ((mxy & 1) ^ i);
		ll lz = mnz + ((mnz & 1) ^ i), rz = mxz - ((mxz & 1) ^ i);
		if (l > r || lx > rx || ly > ry || lz > rz) continue;
		ll a = lx, b = ly, c = lz;
		if (a + b + c > r) continue;
		if (a + b + c < l) a = rx < l - b - c ? rx : l - b - c;
		if (a + b + c < l) b = ry < l - a - c ? ry : l - a - c;
		if (a + b + c < l) c = rz < l - a - b ? rz : l - a - b;
		if (a + b + c < l) continue;
		return X = (b + c) >> 1, Y = (a + c) >> 1, Z = (a + b) >> 1, 1;
	}
	return 0;
}

inline void solve() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(x[i]), rd(y[i]), rd(z[i]);
	ll l = 0, r = inf;
	while (l <= r) {
		ll mid = (l + r) >> 1;
		if (pd(mid)) r = mid - 1;
		else l = mid + 1;
	}
	print(X, ' '), print(Y, ' '), print(Z);
}

int main() {
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
```

> [CF643F Bears and Juice](https://codeforces.com/contest/643/problem/F)

## 题意

- 有 $n$ 只熊和 $p$ 张床，还有若干个无限大的酒桶（至少一个），其中恰好只有一个酒桶里装着酒，其它酒桶里都装着果汁。
- 熊一开始不知道哪桶里面是酒，于是进行了一次挑战，目标是找到哪桶里面是酒。
- 每天，每只还醒着的熊会选择一个酒桶的子集（可以为空集），并且喝下选择的酒桶中的一小杯饮料。
- 如果一只熊喝到了酒，它会上床睡觉一直到挑战结束。但一张床只能容纳一只熊，如果有熊没有床睡觉，则挑战失败。
- 如果 $i$ 天后至少还剩一只熊没睡觉，且能根据前面的线索推理出哪桶里面是酒，则挑战成功。
- 请你求出对于 $i \in [1,q]$，在可以确保挑战成功的情况下，最多有多少个酒桶。
- 设对于 $i$ 的答案为 $R_i$，你需要求出 $\operatorname{xor}_{i=1}^q ((i \times R_i) \bmod 2^{32})$。
- $n \le 10^9$，$p \le 130$，$q \le 2 \times 10^6$。

## 题解

这道题需要从「信息」的角度考虑。什么叫从「信息」的角度呢？

举个例子，我们都知道 $\text{sort}$ 的时间复杂度为 $\mathcal O(n \log n)$，这是**基于比较的排序的时间复杂度下界**吗？

显然一共有 $n!$ 中不同的方案，我们排序的目的就是区分这 $n!$ 个方案。

每次比较可以得到的全部「信息」为**两个元素的相对顺序**，根据这个「信息」，有一半的方案会被区分掉，还剩下一半的方案。

那么 $k$ 次比较还剩下的方案数就应该为 $\frac{n!}{2^k}$，我们最终要求只剩下一个方案，即 $\frac{n!}{2^k} \le 1$，$k = \mathcal O(\log (n!)) = \mathcal O(n \log n)$。

---

回到本题，我们能够得到的全部「信息」为：

- 一只熊最终有没有睡觉。
- 如果它睡觉了，是在第几天睡的。

根据这些「信息」，当天数为 $i$ 时，我们可以区分的方案数的上界为：
$$
R_i = \sum_{j=0}^{\min(p,n-1)}\binom{n}{j} \times i^j
$$
解释一下这个公式：

1. 枚举睡觉的熊的个数 $j$，由于一共只有 $p$ 张床，而不能所有熊都睡觉，因此睡觉的熊的个数最多为 $\min(p,n-1)$。
2. $n$ 只熊里面选 $j$ 个睡觉，方案数为 $\binom nj$。
3. 每只睡觉的熊可以在 $i$ 天中选择一天睡觉，$j$ 只熊的方案数为 $i^j$。

那这个上界是否一定能达到呢？

我们将所有的方案排成一排，第 $k$ 个方案对应第 $k$ 个酒桶里面有酒。

如果在第 $k$ 个方案中，某一只熊最终没有睡觉，则自始至终不让这只熊喝第 $k$ 桶；否则，让它在睡觉的那一天喝第 $k$ 桶。

这样，我们就构造出来了一种达到上界的情况。

---

于是，我们现在要计算的式子为：
$$
\operatorname{xor}_ {i=1}^q \left(\left(i \times \left(\sum_ {j=0}^{\min(p,n-1)}\binom{n}{j} \times i^j\right)\right) \bmod 2^{32}\right)
$$
直接暴力枚举 $i,j$ 计算时间复杂度为 $\mathcal O(pq)$，可以接受。

但问题在于这个组合数 $\binom nj$ 如何计算。

注意到 $p$ 非常小，考虑预处理出 $\binom{n}{0\cdots\min(p,n-1)}$。

对于 $\binom{n}{j}$，我们将其写成 $\frac{n \times (n - 1) \times \cdots \times (n - j + 1)}{j!}$，然后暴力枚举上下的每一项，除以它们的 $\gcd$ 进行约分。

这样到最后，分母一定会被约为 $1$，时间复杂度为 $\mathcal O(p^3 \log p)$。

总时间复杂度 $\mathcal O(p^3 \log p + pq)$。

## 代码

```cpp
const ui N = 137;
ui n, p, q, ans[N], Ans;

inline ui calc(ui j) {
	vector<ui> a, b;
	for (ui i = 1; i <= j; i++)
		a.pb(n + 1 - i), b.pb(i);
	for (ui &x : a)
		for (ui & y : b) {
			ui d = __gcd(x, y);
			x /= d, y /= d;
		}
	ui ans = 1;
	for (ui x : a) ans *= x;
	return ans;
}

int main() {
	rd(n), rd(p), rd(q), p = min(p, n - 1);
	for (ui j = 0; j <= p; j++) ans[j] = calc(j);
	for (ui i = 1; i <= q; i++) {
		ui now = 0;
		for (ui j = 0, k = 1; j <= p; j++, k *= i)
			now += ans[j] * k;
		Ans ^= now * i;
	}
	print(Ans);
	return 0;
}
```

> [CF708D Incorrect Flow](https://codeforces.com/contest/708/problem/D)

## 题意

- 给定一张 $n$ 个点 $m$ 条边的网络，源点为 $1$，汇点为 $n$。
- 对于每条边 $(u,v)$，有容量 $c$，当前流量 $f$。
- 但这个图是错误的，可能存在 $c < f$，或者流量不守恒的情况。
- 你每次操作可以将某条边的 $c$ 或 $f$ 加 $1$ 或减 $1$。
- 请你用最少的操作次数将图变成一个正确的网络。
- $n,m \le 100$，$c,f \le 10^6$，$1$ 没有入边，$n$ 没有出边。

## 题解

建立新的网络，下面用 $(x,y,z,w)$ 表示一条 $x \to y$，容量为 $z$，费用为 $w$ 的边。

首先考虑处理每一条原图中的边，设 $f^\prime$ 表示操作后的流量。

对于 $c \ge f$ 的边：

1. $0 \le f^\prime \le f$：连边 $(v, u, f, 1)$，表示流量每减一，花费加一，最多减 $f$ 次。
2. $f < f^\prime \le c$：连边 $(u, v, c - f, 1)$，表示流量每加一，花费加一，最多加 $c - f$ 次。
3. $f^\prime > c$：连边 $(u, v, +\infty, 2)$，表示流量每加一，花费加二，可以无限加。

对于 $c < f$ 的边，由于至少会产生 $f - c$ 的花费，所以先加上：

1. $0 \le f^\prime < c$：连边 $(v, u, c, 1)$，表示将 $f-c$ 的花费用在将流量减 $f-c$ 上，因此流量每减一，花费加一，最多减 $c$ 次。
2. $c \le f^\prime \le f$：连边 $(v, u, f - c, 0)$，表示将 $f-c$ 的花费用在将流量减 $f - f^\prime$，容量加 $f^\prime - c$ 上，因此流量每减一，花费不变，最多减 $f-c$ 次。
3. $f^\prime > f$：连边 $(u,v,+\infty, 2)$，表示将 $f-c$ 的花费用在将容量加 $f - c$ 上，因此流量每加一，花费加二，可以无限加。

那原本的流量 $f$ 怎么办呢？

考虑把网络改为上下界网络，则对于原图中的一条边，连边 $(u,v,(f,f), 0)$。

然后跑**有源汇上下界最小费用可行流**即可。

## 代码

```cpp
namespace EK {
	const int N = 1e4 + 7, M = 1e5 + 7;
	const ll inf = 1e18;
	int n, S, T, h[N], e[M], t[M], tot, pre[N], v[N];
	ll mxf, ans, f[M], c[M], d[N], now[N];
	inline void add(int x, int y, ll z, ll w, int o = 1) {
		e[++tot] = y, f[tot] = z, c[tot] = w, t[tot] = h[x], h[x] = tot;
		if (o) add(y, x, 0, -w, 0);
	}
	inline bool spfa() {
		for (int i = 1; i <= n; i++) v[i] = 0, d[i] = inf;
		queue<int> q;
		q.push(S), v[S] = 1, d[S] = 0, now[S] = inf;
		while (q.size()) {
			int x = q.front();
			q.pop(), v[x] = 0;
			for (int i = h[x]; i; i = t[i]) {
				int y = e[i];
				ll z = f[i], w = c[i];
				if (!z || d[y] <= d[x] + w) continue;
				d[y] = d[x] + w, now[y] = min(now[x], z), pre[y] = i;
				if (!v[y]) q.push(y), v[y] = 1;
			}
		}
		return d[T] != inf;
	}
	inline void upd() {
		mxf += now[T], ans += d[T] * now[T];
		int x = T;
		while (x != S)
			f[pre[x]] -= now[T], f[pre[x]^1] += now[T], x = e[pre[x]^1];
	}
	inline void main() {
		while (spfa()) upd();
	}
	inline void init(int _n, int _S, int _T) {
		n = _n, S = _S, T = _T, tot = 1, mxf = ans = 0;
		for (int i = 1; i <= n; i++) h[i] = 0;
	}
}

namespace no_min_cost_flow {
	const int N = 1e5 + 7;
	int n, S, T;
	ll d[N], s;
	inline void add(int x, int y, ll l, ll r, ll w) {
		EK::add(x, y, r - l, w), d[y] += l, d[x] -= l;
	}
	inline bool main() {
		for (int i = 1; i <= n; i++)
			if (d[i] > 0) EK::add(S, i, d[i], 0), s += d[i];
			else if (d[i] < 0) EK::add(i, T, -d[i], 0);
		EK::main();
		return EK::mxf == s;
	}
	inline void init(int _n) {
		n = _n, s = 0, S = n + 1, T = n + 2;
		EK::init(n + 2, S, T);
		for (int i = 1; i <= n; i++) d[i] = 0;
	}
}

const ll inf = 1e18;
ll ans;

int main() {
	int n, m, S, T;
	rd(n), rd(m), S = 1, T = n;
	no_min_cost_flow::init(n);
	no_min_cost_flow::add(T, S, 0, inf, 0);
	for (int i = 1, u, v, c, f; i <= m; i++) {
		rd(u), rd(v), rd(c), rd(f);
		no_min_cost_flow::add(u, v, f, f, 0);
		if (c >= f) {
			no_min_cost_flow::add(v, u, 0, f, 1);
			no_min_cost_flow::add(u, v, 0, c - f, 1);
			no_min_cost_flow::add(u, v, 0, inf, 2);
		} else {
			ans += f - c;
			no_min_cost_flow::add(v, u, 0, c, 1);
			no_min_cost_flow::add(v, u, 0, f - c, 0);
			no_min_cost_flow::add(u, v, 0, inf, 2);
		}
	}
	no_min_cost_flow::main();
	print(EK::ans + ans);
	return 0;
}
```

