## 题意

- 给定一棵 $n$ 个点的以 $1$ 为根的树。
- 有 $m$ 条路径 $(x,y)$，保证 $y$ 是 $x$ 的祖先，每条路径有一个权值。
- 你要在这些路径中选择若干条路径，使它们能覆盖每条边，同时权值和最小。
- $n,m \le 3 \times 10^5$。

## 题解

设 $f_i$ 表示**覆盖 $i$ 子树内的所有边和 $i$ 与其父亲的边**的最小权值，则答案就是 $\sum_{x \in \operatorname{son}(1)} f_x$。

然而并不是所有 $f$ 都是最优的，对于一种**覆盖 $i$ 子树内的所有边和 $i$ 与其父亲的边**的方案，可能它并不是最小权值，但是它向上延伸得更长。

因此我们要保留住所有可能最优的方案，同时要计算其中的最小值，这启发我们考虑小根堆。具体来说，对于节点 $i$，$i$ 上的小根堆内存储了**覆盖 $i$ 子树内的所有边和 $i$ 与其父亲的边**的所有可能最优的方案。

考虑如何转移，即当 $x \in \operatorname{son}(y)$ 时，如何将 $x$ 上的方案转移到 $y$ 上。对于一个权值为 $k$ 的方案：

- 如果向上延伸超过了 $y$，则这种方案在 $y$ 的小根堆里权值应该为 $k + \sum_{z \in \operatorname{son}(y)} f_z - f_x$。
- 如果正好向上延伸到 $y$，则这种方案不应该出现在 $y$ 上，需要被扔掉。

这时候我们发现，一个点有来自多个儿子的小根堆，显然我们需要将它们合并起来，于是将小根堆改为左偏树即可。

同时，我们还需要支持整棵左偏树加上一个定值，打个标记即可。

对于需要扔掉的方案，由于我们不需要实时删除，因此考虑我们暂时先保留它们，当它们成为根时再弹出即可。

设 $n,m$ 同阶，总时间复杂度为 $\mathcal O(n \log n)$。

## 代码

```cpp
#define Fail print(-1), exit(0)
const int N = 3e5 + 7;
int n, m, d[N], tot, rt[N];
ll f[N], ans;
vi e[N];
vector<pi> p[N];
struct T {
	pair<ll, int> x;
	ll z;
	int l, r, f, d;
} t[N];

inline void add(int x, ll k) {
	if (x) t[x].x.fi += k, t[x].z += k;
}

inline void spd(int x) {
	if (t[x].z) add(t[x].l, t[x].z), add(t[x].r, t[x].z), t[x].z = 0;
}

int merge(int x, int y) {
	if (!x || !y) return x | y;
	if (t[x].x > t[y].x) swap(x, y);
	spd(x);
	t[t[x].r=merge(t[x].r,y)].f = x;
	if (t[t[x].r].d > t[t[x].l].d) swap(t[x].l, t[x].r);
	t[x].d = t[t[x].r].d + 1;
	return x;
}

void dfs(int x, int fa) {
	d[x] = d[fa] + 1;
	for (pi o : p[x])
		t[++tot].x = o, t[tot].d = 1, rt[x] = merge(rt[x], tot);
	ll s = 0;
	for (int y : e[x])
		if (y != fa) {
			dfs(y, x), s += f[y];
			add(rt[y], -f[y]), rt[x] = merge(rt[x], rt[y]);
		}
	add(rt[x], s);
	while (rt[x] && d[t[rt[x]].x.se] >= d[x])
		spd(rt[x]), rt[x] = merge(t[rt[x]].l, t[rt[x]].r);
	if (!rt[x]) Fail;
	f[x] = t[rt[x]].x.fi;
}

int main() {
	rd(n), rd(m);
	for (int i = 1, x, y; i < n; i++)
		rd(x), rd(y), e[x].pb(y), e[y].pb(x);
	for (int i = 1, x, y, z; i <= m; i++)
		rd(x), rd(y), rd(z), p[x].pb(mp(z, y));
	d[1] = 1;
	for (int x : e[1]) dfs(x, 1), ans += f[x];
	print(ans);
	return 0;
}
```

> 左偏树是一种**可并堆**，具有堆的性质，同时支持快速合并。

## 定义和性质

对于一棵二叉树，定义一个节点的 $\mathrm{dist}$ 为这个点到**它的子树中距离它最近的叶子**的路径上的节点数。一个空节点的 $\mathrm{dist}$ 为 $0$，叶子节点的 $\mathrm{dist}$ 为 $1$，根的 $\mathrm{dist}$ 不超过 $\lceil\log (n+1)\rceil$。

左偏树是一棵二叉树，它不仅具有堆（本文为小根堆）的性质，并且是「左偏」的：每个节点左儿子的 $\mathrm{dist}$ 都大于等于右儿子的 $\mathrm{dist}$。因此，左偏树每个节点的 $\mathrm{dist}$ 都等于其右儿子的 $\mathrm{dist}$ 加一。

## 核心操作：合并

合并两个堆时，由于要满足堆性质，先取值较小的那个根作为合并后堆的根节点，然后将这个根的左儿子作为合并后堆的左儿子，递归地合并其右儿子与另一个堆，作为合并后的堆的右儿子。为了满足左偏性质，合并后若左儿子的 $\mathrm{dist}$ 小于右儿子的 $\mathrm{dist}$，就交换两个儿子，时间复杂度 $\mathcal O(\log n)$。

```cpp
int merge(int x, int y) {
	if (!x || !y) return x | y;
	if (t[x].x > t[y].x) swap(x, y);
	t[t[x].r=merge(t[x].r,y)].f = x;
	if (t[t[x].r].d > t[t[x].l].d) swap(t[x].l, t[x].r);
	t[x].d = t[t[x].r].d + 1;
	return x;
}
```

#### 【模板】[P3377 【模板】左偏树（可并堆）](https://www.luogu.com.cn/problem/P3377)

由于并查集需要路径压缩才能保证时间复杂度，因此这题需要将删掉的点重新指向合并后的新根，因此有些细节要注意。

```cpp
const int N = 1e5 + 7;
int n, m, f[N];
bool v[N];
struct T {
	int x, l, r, f, d;
} t[N];

int get(int x) {
	return x == f[x] ? x : (f[x] = get(f[x]));
}

int merge(int x, int y) {
	if (!x || !y) return x | y;
	if (t[x].x > t[y].x || (t[x].x == t[y].x && x > y)) swap(x, y);
	t[t[x].r=merge(t[x].r,y)].f = x;
	if (t[t[x].l].d < t[t[x].r].d) swap(t[x].l, t[x].r);
	t[x].d = t[t[x].r].d + 1;
	return f[y] = x;
}

int main() {
	rd(n), rd(m);
	for (int i = 1; i <= n; i++) rd(t[i].x), t[i].d = 1, f[i] = i;
	for (int i = 1, o, x, y; i <= m; i++) {
		rd(o), rd(x);
		if (o == 1) {
			rd(y);
			if (v[x] || v[y]) continue;
			x = get(x), y = get(y);
			if (x != y) merge(x, y);
		} else if (v[x]) print(-1);
		else {
			x = get(x), v[x] = 1, print(t[x].x);
			f[x] = f[t[x].l] = f[t[x].r] = merge(t[x].l, t[x].r);
		}
	}
	return 0;
}
```

