## 题意

- 给定一个小写字符串 $s$ 和一个正整数 $n$。
- 要求在 $s$ 中插入恰好 $n$ 个小写字符使其回文的方案数。
- $|s| \le 200$，$n \le 10^9$，答案对 $10^4 + 7$ 取模。

## 题解

首先考虑 $n+|s|$ 为偶数的情况。

考虑 dp。设 $f_{i,l,r}$ 表示只考虑最终回文串的前 $i$ 和后 $i$ 个字符，它们与 $s$ **尽可能**匹配后 $s$ 还剩下 $[l,r]$ 这段区间时的方案数。再设 $g_i$ 表示只考虑最终回文串的前 $i$ 和后 $i$ 个字符，它们与 $s$ 已经能够完全匹配时的方案数。

那么转移有：

1. $s_l = s_r$，$r - l \le 1$。

$$
g_{i+1} \leftarrow f_{i,l,r}
$$

$$
f_{i+1,l,r} \leftarrow 25 \cdot f_{i,l,r}
$$

2. $s_l = s_r$，$r - l \ge 2$。

$$
f_{i+1,l+1,r-1} \leftarrow f_{i,l,r}
$$

$$
f_{i+1,l,r} \leftarrow 25 \cdot f_{i,l,r}
$$

3. $s_l \ne s_r$。

$$
f_{i+1,l+1,r} \leftarrow f_{i,l,r}
$$

$$
f_{i+1,l,r-1} \leftarrow f_{i,l,r}
$$

$$
f_{i+1,l,r} \leftarrow 24 \cdot f_{i,l,r}
$$

4. $g$。

$$
g_{i+1} \leftarrow g_i
$$

此时我们可以得到一个状态数 $\mathcal O(|s|^2)$ 递推 $\mathcal O(n + |s|)$ 次的 dp，这个 dp 可以强行矩阵加速，复杂度为 $\mathcal O(|s|^6 \log (n + |s|))$，一脸的过不去。

仔细观察这个 dp，可以发现这实际上是在一个**有限状态自动机**上匹配的过程。

比如对于 $s = \texttt{abaac}$ 转移的过程如下：

![](http://www.xht37.com/wp-content/uploads/2020/02/61e9c25b977bad7af00165b92070a9acabf16704.png)

如果真的理解了上面的 dp，会发现这张图中不同颜色的点和不同形态的边与上面的状态和转移一一对应。

这个自动机的节点数依旧是 $\mathcal O(|s|^2)$ 的。考虑压缩这个自动机，可以发现，对于每一条从起点到终点的链，如果其上面有 $k$ 个红点，那么就意味着它有 $\lceil \frac{|s|-k}2 \rceil$ 个绿点，同时最终连接终点的点一定是绿点。

而对于两条红点数量相同的链，它们对答案的贡献与红点的具体位置无关，因此本质上是一样的，这意味着本质不同的链只有 $\mathcal O(|s|)$ 条。

但我们还要求出有 $k$ 个红点的链的数量。设 $h_{i,l,r}$ 表示从起点走到 $(l,r)$ 对应的节点的路径中，有多少条经过了 $i$ 个红点。那么我们可以采用**记忆化搜索**的方法 $\mathcal O(|s|^3)$ 求出答案。

现在我们有 $\mathcal O(|s|)$ 条本质不同的链，同时还知道了每条链的数量。至此我们可以对每条链做一次矩阵加速，时间复杂度降为 $\mathcal O(|s|^4 \log (n + |s|))$。

但还不够，我们要想办法建出一个节点数只有 $\mathcal O(|s|)$ 的自动机。构建方法如下（方法来自 [CQzhangyu](https://www.cnblogs.com/CQzhangyu/p/8685601.html)）：

![](http://www.xht37.com/wp-content/uploads/2020/02/1077980-20180401083928510-472522990.png)

同样的，如果真的理解了上面的转化，肯定能自己根据这样图脑补出来压缩后的自动机具体长成什么样。

压缩后的自动机点数只有 $\mathcal O(|s|)$ 个了，这时候再使用矩阵加速，就可以 $\mathcal O(|s|^3 \log (n+|s|))$。

然而这玩意儿稍微有点卡常，但如果我们把状态转移设计成只能从编号小的往编号大的点转移，那么矩阵乘法时常数可以除以 $6$。

最后还有一个问题，$n+|s|$ 如果为奇数，咋办？

唯一的区别在于，在最后一步的时候，包含两个字符的绿点无法再转移到终点。

那么，我们只保留这样的链，同时去掉终点的自环，这样得到的结果就是要去掉的方案数。


## 代码

```cpp
const int N = 207, M = 307;
int n, m, k;
char s[N];
bool v[N][N][N];
modint h[N][N][N], f[M], g[M][M], F[M], G[M][M];

inline modint H(int i, int l, int r) {
	if (i < 0) return 0;
	if (v[i][l][r]) return h[i][l][r];
	v[i][l][r] = 1;
	if (l == 1 && r == m) return h[i][l][r] = !i;
	if (l != 1 && s[l-1] != s[r]) h[i][l][r] += H(i - 1, l - 1, r);
	if (r != m && s[l] != s[r+1]) h[i][l][r] += H(i - 1, l, r + 1);
	if (l != 1 && r != m && s[l-1] == s[r+1]) h[i][l][r] += H(i, l - 1, r + 1);
	return h[i][l][r];
}

inline int ceil(int x) {
	return (x >> 1) + (x & 1);
}

inline void mul(modint f[M], modint g[M][M]) {
	modint a[M];
	for (int j = 1; j <= k; j++)
		for (int i = 1; i <= k; i++)
			a[i] += f[j] * g[j][i];
	for (int i = 1; i <= k; i++) f[i] = a[i];
}

inline void mul(modint g[M][M]) {
	modint a[M][M];
	for (int i = 1; i <= k; i++)
		for (int o = i; o <= k; o++)
			for (int j = o; j <= k; j++)
				a[i][j] += g[i][o] * g[o][j];
	for (int i = 1; i <= k; i++)
		for (int j = 1; j <= k; j++)
			g[i][j] = a[i][j];
}

inline void ksm(int o) {
	while (o) {
		if (o & 1) mul(f, g);
		mul(g), o >>= 1;
	}
}

int main() {
	rds(s, m), rd(n), k = m + ceil(m);
	for (int i = 0; i < m; i++) {
		modint c;
		for (int j = 1; j <= m; j++) {
			c += H(i, j, j);
			if (j != m && s[j] == s[j+1]) c += H(i, j, j + 1);
		}
		if (i) {
			g[i][k-ceil(m-i)] = c, g[i][i] = 24;
			if (i != 1) g[i-1][i] = 1;
			else f[i] = 1;
		} else {
			f[m] = c, g[k][k] = 26;
			for (int j = m; j < k; j++) g[j][j+1] = 1, g[j][j] = 25;
		}
	}
	if ((n + m) & 1) {
		for (int i = 1; i <= k; i++) F[i] = f[i];
		for (int i = 1; i <= k; i++)
			for (int j = 1; j <= k; j++)
				G[i][j] = g[i][j];
	}
	ksm(ceil(n + m));
	if (!((n + m) & 1)) return print(f[k]), 0;
	modint ans = f[k];
	for (int i = 1; i <= k; i++) f[i] = F[i];
	for (int i = 1; i <= k; i++)
		for (int j = 1; j <= k; j++)
			g[i][j] = G[i][j];
	for (int i = 0; i < m; i++) {
		modint c;
		for (int j = 1; j <= m; j++)
			if (j != m && s[j] == s[j+1]) c += H(i, j, j + 1);
		if (i) g[i][k-ceil(m-i)] = c;
		else f[m] = c, g[k][k] = 0;
	}
	ksm(ceil(n + m));
	print(ans - f[k]);
	return 0;
}
```

> [CF571E Geometric Progressions](https://codeforces.com/contest/571/problem/E)

## 题意

- 给定 $n$ 以及 $n$ 个正整数对 $a_i, b_i$。
- 第 $i$ 对 $a_i, b_i$ 确定了一个序列 $\{a_i, a_i b_i, a_i b_i^2, a_i b_i^3, \ldots \}$。
- 询问最小的在 $n$ 个序列中都有出现的数，或者判断不存在。
- $n \le 100$，$a_i, b_i \le {10}^9$，答案对 ${10}^9 + 7$ 取模。

## 题解

本题数据范围相对较小，因此保证正确性即可。

首先，我们显然要将所有 $a_i,b_i$ 分解质因数，根号试除即可。

在先处理掉某个 $a_i$ 就是答案的情况之后，设 $P(x)$ 为 $x$ 的质因数集合，若存在 $i,j$ 有 $P(a_i) \cup P(b_i) \ne P(a_j) \cup P(b_j)$，则显然无解。

否则，设 $P = P(a_i) \cup P(b_i)$。

设 $c_i$ 表示最终的答案在第 $i$ 个序列中被表示成 $a_ib_i^{c_i}$，另外设 $c_p(x)$ 表示 $x$ 中质数 $p$ 的次数。

每次考虑合并两个序列 $i,j$，即对于 $p \in P$，需要找到满足 $c_p(a_i) + c_i \cdot c_p(b_i) = c_p(a_j) + c_j \cdot c_p(b_j)$ 的 $c_i$ 的取值。

那么对于每个 $p \in P$，我们都能列出一个这样的方程。

解这个方程组，结果要么判断出无解，要么直接确定 $c_i$ 的值，要么要解一个不定方程。

前面两种情况都很好处理。对于最后一种情况，可以用扩展欧几里得求出最小非负整数解，若设为 $x$，则合并后的新序列中，$a^{\prime} = a_i \cdot b_i^x$，$b^{\prime} = \sum_{p} p^{\operatorname{lcm}(c_p(b_i), c_p(b_j))}$。

合并到最后，$a^{\prime}$ 即为答案。

整个过程中，涉及到的数肯定会很大，因此直接把每个数用其唯一分解式存就行了。

注意，指数会爆 `int ` 但不会爆 `long long`。

## 代码

```cpp
#define Fail print(-1), exit(0)
const int N = 107;
int n;
struct Num {
	vector<pair<int, ll>> p;
	inline void in() {
		int x;
		rd(x);
		for (int i = 2; i * i <= x; i++)
			if (!(x % i)) {
				p.pb(mp(i, 0ll));
				while (!(x % i)) ++p.back().se, x /= i;
			}
		if (x != 1) p.pb(mp(x, 1ll));
	}
	inline void out() {
		modint ans = 1;
		for (auto o : p) ans *= (modint)o.fi ^ o.se;
		print(ans);
	}
	#define s(o) o.p.size()
	#define x(o) x.p[o]
	#define y(o) y.p[o]
	#define z(o) z.p.pb(o)
	inline friend Num operator * (Num x, Num y) {
		Num z;
		ui i = 0, j = 0;
		while (i < s(x) && j < s(y))
			if (x(i).fi == y(j).fi)
				z(mp(x(i).fi, x(i).se + y(j).se)), ++i, ++j;
			else if (x(i).fi < y(j).fi) z(x.p[i++]);
			else z(y.p[j++]);
		while (i < s(x)) z(x.p[i++]);
		while (j < s(y)) z(y.p[j++]);
		return z;
	}
	inline friend bool operator % (Num x, Num y) {
		for (ui i = 0, j = 0; j < s(y); i++, j++) {
			while (i < s(x) && x(i).fi != y(j).fi) ++i;
			if (i == s(x) || x(i).se < y(j).se) return 1;
		}
		return 0;
	}
	inline friend Num operator / (Num x, Num y) {
		Num z;
		for (ui i = 0, j = 0; i < s(x); i++)
			if (j < s(y) && x(i).fi == y(j).fi) {
				z(mp(x(i).fi, x(i).se - y(j++).se));
				if (!z.p.back().se) z.p.pop_back();
			} else z(x(i));
		return z;
	}
	inline friend Num operator & (Num x, Num y) {
		Num z;
		for (ui i = 0, j = 0; i < s(x); i++)
			if (j < s(y) && x(i).fi == y(j).fi)
				z(mp(x(i).fi, x(i).se - y(j++).se));
			else z(x(i));
		return z;
	}
	inline friend bool operator | (Num x, Num y) {
		if (!s(x)) return 0;
		ll k;
		for (ui i = 0, j = 0; i <= s(x); i++, j++) {
			while (j < s(y) && !y(j).se) ++j;
			if (i == s(x)) {
				if (j == s(y)) return 0;
				return 1;
			}
			if (j == s(y)) return 1;
			if (x(i).fi != y(j).fi || x(i).se % y(j).se) return 1;
			if (!i) k = x(i).se / y(j).se;
			else if ((x(i).se / y(j).se) != k) return 1;
		}
		return 0;
	}
	inline friend Num operator ^ (Num x, ll y) {
		for (auto &o : x.p) o.se *= y;
		return x;
	}
	inline friend Num operator + (Num x, Num y) {
		Num z;
		for (ui i = 0; i < s(x); i++)
			z(mp(x(i).fi, x(i).se * y(i).se / __gcd(x(i).se, y(i).se)));
		return z;
	}
} a[N], b[N], c[N], A, B;

inline bool pd(Num x) {
	for (int i = 1; i <= n; i++)
		if ((x % a[i]) || ((x / a[i]) | b[i])) return 0;
	return 1;
}

struct Pro {
	ll k, b, p;
	inline Pro() {}
	inline Pro(ll k, ll b, ll p) : k(k), b(b), p(p) {}
	inline bool operator == (const Pro o) const {
		return k == o.k && b == o.b && p == o.p;
	}
};

inline ll solve(Pro x, Pro y) {
	ll a = x.b * y.p - y.b * x.p, b = x.k * y.p - y.k * x.p;
	if (!b || a % b) Fail;
	return a / b;
}

ll exgcd(ll a, ll b, ll &x, ll &y, ll d = 0ll) {
	return b ? (d = exgcd(b, a % b, y, x), y -= a / b * x, d) : (x = 1, y = 0, a);
}

inline bool merge(int o) {
	vector<Pro> pro;
	for (ui i = 0; i < A.p.size(); i++) {
		ll k1 = B.p[i].se, b1 = A.p[i].se;
		ll k2 = b[o].p[i].se, b2 = a[o].p[i].se;
		if (!k1 && !k2) {
			if (b1 != b2) Fail;
			continue;
		}
		if (!k1) {
			if (b1 < b2 || (b1 - b2) % k2) Fail;
			A = a[o] * (b[o] ^ ((b1 - b2) / k2));
			return 0;
		}
		if (!k2) {
			if (b2 < b1 || (b2 - b1) % k1) Fail;
			A = A * (B ^ ((b2 - b1) / k1));
			return 0;
		}
		ll d = __gcd(k1, k2), g = b2 - b1;
		if (g % d) Fail;
		g /= d, k1 /= d, k2 /= d;
		if (pro.size()) {
			if (pro[0] == Pro(k1, g, k2)) continue;
			A = A * (B ^ solve(pro[0], Pro(k1, g, k2)));
			return 0;
		}
		pro.pb(Pro(k1, g, k2));
	}
	if (pro.size()) {
		ll k = pro[0].k, b = pro[0].b, p = pro[0].p, x, y;
		b = (b % p + p) % p;
		exgcd(k, p, x, y);
		x = (x * b % p + p) % p;
		A = A * (B ^ x);
		B = B + ::b[o];
	}
	return 1;
}

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) a[i].in(), b[i].in(), c[i] = a[i] * b[i];
	for (int i = 1; i <= n; i++) if (pd(a[i])) return a[i].out(), 0;
	for (int i = 1; i <= n; i++) {
		if (c[i].p.size() != c[1].p.size()) Fail;
		for (ui j = 0; j < c[1].p.size(); j++)
			if (c[i].p[j].fi != c[1].p[j].fi) Fail;
		a[i] = c[i] & b[i], b[i] = c[i] & a[i];
	}
	A = a[1], B = b[1];
	for (int i = 2; i <= n; i++)
		if (!merge(i)) {
			if (pd(A)) return A.out(), 0;
			Fail;
		}
	A.out();
	return 0;
}
```

> [CF627F Island Puzzle](https://codeforces.com/contest/627/problem/F)

## 题意

- 给定一棵 $n$ 个点的树，每个点上都有一个 $[0,n-1]$ 的数，任意两点上的数都不同。
- 每次你可以交换 $0$ 所在的点和与其相连的任一点上的数，同时你可以最多加入一条边。
- 给定目标状态，你需要在加入的边数尽量小的前提下，求出最少的步数，或者判断无法达成目标。
- $n \leq 2 \times 10^5$。

## 题解

设初始时 $0$ 在 $s$，目标时在 $t$。

注意到操作的本质是 $0$ 的移动，同时操作具有可逆性。

因此，我们先不考虑次数最少的要求，先让 $0$ 从 $s$ 以最短距离移动到 $t$。

如果此时已经满足目标状态了，说明不需要加入新的边，此时 $0$ 经过的距离即为最少步数。

否则，接下来我们只能加入一条新的边，然后让 $0$ 从 $t$ 出发，走到包含这条新边的环上距离 $t$ 最近的点 $p$，绕若干次完整的圈之后，回到 $t$。

观察这样操作对权值的变化可以得出，$t$ 到 $p$ 的路径上的所有点的权值都不会改变，同时每绕圈一次，环上除了 $p$ 之外的点上的权值变化形成一个**循环**，而绕若干圈则为一个**轮换**。

因此，权值要改变的点加上 $p$ 应该在树上形成一条路径。

由此我们能够确定连边 $(u,v)$，可以 $t$ 为根，找到所有权值需要改变的点，$p$ 即为这些点中深度最小的点的父节点，而路径 $(u,v)$ 则由 $p$ 和这些点构成。

如果深度最小的点的父节点不唯一，或者 $p$ 和这些点无法构成一条路径，或者这些点的权值不是目标权值的一个**轮换**，则说明无解。

最后来考虑最小化操作次数。

对于一条加边 $(u,v)$，绕圈的方向有两种 $u\to v$ 和 $v \to u$，分别计算取 $\min$ 即可。

假设从 $u \to v$，由这个轮换对循环的次数 $c$ 可以得到最小次数为 $2\cdot \operatorname{dist}(t, p) + c \cdot (\operatorname{dist}(u,v) + 1)$。

但注意这个最小次数是在先将 $0$ 从 $s$ 移到 $t$ 的前提下，因此如果有重复的路径需要减掉。

总时间复杂度 $\mathcal O(n)$，由于复杂度是线性的所以常数什么的就不管了。

## 代码

```cpp
#define Fail print(-1), exit(0);
const int N = 2e5 + 7;
int n, a[N], b[N], s, t, p, v[N], d[N];
vi e[N], g, h, A, B;
pi o = mp(N, 0);

bool dfs1(int x, int f) {
	g.pb(x);
	if (x == t) return 1;
	for (auto y : e[x])
		if (y != f && dfs1(y, x)) return 1;
	g.pop_back();
	return 0;
}

void dfs2(int x, int f, int d) {
	if (a[x] != b[x]) {
		h.pb(x), v[x] = 1;
		if (d - 1 == o.fi && f != o.se) Fail;
		if (d - 1 < o.fi) o = mp(d - 1, f);
	}
	for (auto y : e[x])
		if (y != f) dfs2(y, x, d + 1);
}

void dfs3(int x, int f) {
	if (x != p) A.pb(a[x]), B.pb(b[x]);
	for (auto y : e[x])
		if (y != f && v[y]) dfs3(y, x);
}

int dfs4(int x, int f, int d, int t) {
	if (x == t) return d;
	for (auto y : e[x])
		if (y != f) {
			int o = dfs4(y, x, d + 1, t);
			if (o) return o;
		}
	return 0;
}

inline int calc(vi A, vi B) {
	int pos = 0, siz = A.size();
	for (ui i = 0; i < B.size(); i++)
		if (B[i] == A[0]) pos = i;
	if (!pos) return 0;
	for (ui i = 0; i < A.size(); i++)
		if (A[i] != B[(i+pos)%siz]) return 0;
	return pos;
}

inline int S(int x, int y) {
	return dfs4(x, 0, 0, y);
}

inline ll get(int x, int y) {
	int c = calc(A, B);
	return S(s, x) + 1ll * (c - 1) * (A.size() + 1) + 1 + S(y, t);
}

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(a[i]), s = a[i] ? s : i;
	for (int i = 1; i <= n; i++) rd(b[i]), t = b[i] ? t : i;
	for (int i = 1, x, y; i < n; i++)
		rd(x), rd(y), e[x].pb(y), e[y].pb(x);
	dfs1(s, 0);
	for (ui i = 1; i < g.size(); i++) swap(a[g[i-1]], a[g[i]]);
	bool ok = 1;
	for (int i = 1; i <= n; i++) ok &= a[i] == b[i];
	if (ok) return print(0, ' '), print(g.size() - 1), 0;
	dfs2(t, 0, 0), h.pb(p = o.se), v[p] = 1;
	for (auto x : h)
		for (auto y : e[x])
			if (v[y]) ++d[x];
	vi u;
	for (auto x : h)
		if (d[x] == 1) u.pb(x);
		else if (d[x] != 2) Fail;
	if (u.size() != 2u) Fail;
	if (u[0] > u[1]) swap(u[0], u[1]);
	dfs3(u[0], 0);
	if (!calc(A, B)) Fail;
	print(u[0], ' '), print(u[1], ' ');
	ll ans = get(u[0], u[1]);
	reverse(A.begin(), A.end());
	reverse(B.begin(), B.end());
	print(min(ans, get(u[1], u[0])));
	return 0;
}
```

