## 出言不逊

贪心，找到出现次数最多的字符一直加就行了，注意数据范围很大，最好开 `__int128`。

```cpp
const int N = 1e6 + 7;
int n, ans, k;
char s[N];
__int128 l, m, x;

int main() {
	rds(s, n), rd(l), m = n;
	map<char, int> c;
	for (int i = 1; i <= n; i++) ++c[s[i]];
	for (auto o : c) k = max(k, o.se);
	x = k;
	while (m < l) m += x, x *= 2, ++ans;
	print(ans); 
	return 0;
}
```

## 谔运算

每一位是独立的，按位考虑即可，取模直接自然溢出。

```cpp
const ui N = 5e5 + 7, M = 32;
ui n, a[N], ans;

int main() {
	rd(n);
	for (ui i = 1; i <= n; i++) rd(a[i]);
	for (ui i = 0; i < M; i++) {
		ui c = 0;
		for (ui j = 1; j <= n; j++) c += (a[j] >> i) & 1;
		ans += ((n * n - (n - c) * (n - c)) * (n * n - c * c) + (n - c) * (n - c) * c * c) * (1u << i);
	}
	print(ans);
	return 0;
}
```

## 直接自然溢出啥事没有

考虑递推，设 $f_i$ 表示长度为 $i$ 的「程序片段」，有 $f_0 = 1$。

注意到，「程序片段」只能是「程序片段」$+$「语句」，若设 $c_i$ 表示长度为 $i$ 的「语句」个数，则有 $f_{i} = \sum_{j=0}^{i-1} f_jc_{i-j}$，则可以 $\mathcal O(n^2)$ 递推。

考虑什么东西能当「语句」。

首先，`;` 为一个「语句」，因此有 $f_i \leftarrow f_{i-1}$。

除此之外，「语句」都必须由另外一个「程序片段」生成。

我们枚举这个「程序片段」的长度 $j$，设其为 `A`，则 `A` 的个数为 $f_j$。

它会生成 `{A}`「语句块」和 `{A}`「语句」，此时出现了「语句」，则有 $f_i \leftarrow f_{i-j-2} \times f_{j}$。

如果此时我们还想生成「语句」，那么只能走这样一条路：「语句」$\to$「函数」$\to$「值」$\to$「语句」 。

然后就无法再生成更多的「语句」了。

「语句」$\to$「函数」的过程实际上就是长度 $+2$ 或 $+4$。

「值」$\to$「语句」的过程实际上就是长度 $+1$。

我们只需要考虑「函数」$\to$「值」的过程，这也是最复杂的一个过程。

对于一个长度为 $l$ 的「函数」`A`，它会变成：

- 一个长度为 $l$ 的值 `A`；
- 两个长度为 $l+2$ 的值 `(A),A()`；
- 三个长度为 $l+4$ 的值 `((A)),(A()),(A)()`；
- 四个长度为 $l+6$ 的值 `(((A))),((A())),((A)()),((A))()`；
- $\cdots$
- $n$ 个长度为 $l+(n-1)\times 2$ 的值。

考虑到「语句」$\to$「函数」的过程长度 $+2$ 或 $+4$，「值」$\to$「语句」的过程长度 $+1$。

将这些信息整合起来可以得到 $f_i \leftarrow f_j \sum_{k=1}^{i-j-4} [k \bmod 2 = 1]k \cdot f_{i-j-4}$。

于是我们可以写出下面这个 $\mathcal O(n^3)$ 的程序：

```cpp
const int N = 1e4 + 7;
int n;
ul f[N];

int main() {
	rd(n), f[0] = 1;
	for (int i = 1; i <= n; i++) {
		f[i] = f[i-1];
		for (int j = 0; i - j - 2 >= 0; j++) {
			ul o = f[i-j-2];
			for (int k = 1; i - j - k - 4 >= 0; k += 2)
				o += f[i-j-k-4] * k;
			f[i] += o * f[j];
		}
	}
	print(f[n]);
	return 0;
}
```

然而，数据范围要求我们在 $\mathcal O(n^2)$ 的时间复杂度内解决。

考虑优化，注意到 $\sum_{k=1}^{i-j-4} [k \bmod 2 = 1]k \cdot f_{i-j-4}$ 这玩意儿可以前缀和优化 $\mathcal O(1)$ 得到，于是时间复杂度降为 $\mathcal O(n^2)$。

至于对 $2^{64}$ 取模，题目名已经告诉我们怎么做了。

```cpp
const int N = 1e4 + 7;
int n;
ul f[N], g[N];

int main() {
	rd(n), f[0] = g[1] = 1;
	for (int i = 1; i <= n; i++) {
		f[i] = f[i-1];
		for (int j = 0; i - j - 2 >= 0; j++)
			f[i] += f[i-j-2] * f[j];
		for (int j = 0; i - j - 4 >= 0; j++)
			f[i] += g[i-j-4] * f[j]; 
		for (int j = 1; i + 1 - j >= 0; j += 2)
			g[i+1] += f[i+1-j] * j;
	}
	print(f[n]);
	return 0;
}
```

## 相同的数字

最后那个相同的数只可能是 $m = \max_{i=1}^{n} a_i$ 或者 $\ge m$ 的最小质数，每次算两种的答案然后取 $\min$ 即可。

算答案的时候，将每个数加到目标值的过程按照质数划分成若干段，可以差分实现。对于长度为 $k$ 的一段，选择用 $c_1$ 还是 $c_2$ 取决于 $kc_1$ 和 $c_2$ 哪个大，显然这玩意儿是单调的，那么前缀和一下即可。

注意如果目标值是 $m$ 且 $m$ 不为质数，每个数加到 $m$ 的最后一段可能只能使用 $c_1$。

总时间复杂度 $\mathcal O(n + m + q)$。

```cpp
const int N = 1e5 + 7, M = 1 << 17 | 1, P = 1e7 + 20;
int n, m, q, o, a[N], v[P], f[P], c1, c2;
vi p;
vector<ll> c[2], e[2];
ll g[2], ans;

inline void add(int o, int x, int k) {
	if (!x) return;
	if ((int)c[o].size() < x + 1) c[o].resize(x + 1);
	c[o][x] += k;
}

inline void prework(int o, int m) {
	vi d(p.size());
	for (int i = 1; i <= n; i++) {
		int x = a[i];
		if (v[x] == v[m]) add(o, m - x, 1);
		else {
			add(o, v[x] - x, 1);
			if (m == v[m]) add(o, m - p[f[v[m]]-1], 1);
			else g[o] += m - p[f[v[m]]-1];
			++d[f[v[x]]];
		}
	}
	for (ui i = 0; p[i+1] < v[m]; i++) {
		if (i) d[i] += d[i-1];
		add(o, p[i+1] - p[i], d[i]);
	}
	e[o].resize(c[o].size());
	for (ui i = 0; i < c[o].size(); i++) {
		e[o][i] = c[o][i] * i;
		if (i) e[o][i] += e[o][i-1], c[o][i] += c[o][i-1];
	}
}

inline ll solve(int o) {
	int k = min((int)1.0 * c2 / c1, (int)c[o].size() - 1);
	return (e[o][k] + g[o]) * c1 + (c[o].back() - c[o][k]) * c2;
}

int main() {
	for (int i = 2; i < P; i++) {
		if (!v[i]) p.pb(v[i] = i), f[i] = p.size() - 1;
		for (ui j = 0; j < p.size() && i * p[j] < P && p[j] <= v[i]; j++)
			v[i*p[j]] = p[j];
	}
	for (int i = P - 1; i; i--) if (v[i] != i) v[i] = v[i+1];
	rd(n), rd(q), rd(o);
	for (int i = 1; i <= n; i++) rd(a[i]), m = max(m, a[i]);
	prework(0, m), prework(1, v[m]);
	for (int i = 1; i <= q; i++) {
		rd(c1), rd(c2), c1 ^= o * ans, c2 ^= o * ans;
		print(ans = min(solve(0), solve(1)));
		ans &= M - 2;
	}
	return 0;
}
```

> [CF538G Berserk Robot](https://codeforces.com/contest/538/problem/G)

## 题意

- 有一个机器人，第 $0$ 秒时在 $(0,0)$ 位置。
- 机器人会循环执行一个长度为 $l$ 的指令序列，每秒执行一个指令。
- 指令有 `ULDR` 四种，分别代表向上/左/下/右移动一格。
- 你不知道这个指令序列具体是什么，但是你知道 $n$ 条信息，第 $i$ 条信息为「第 $t_i$ 秒时机器人在 $(x_i,y_i)$」，保证 $t$ 递增。
- 你需要构造一个满足这些信息的指令序列，或判断不存在。
- $n \le 2 \times 10^5$，$l \le 2 \times 10^6$，$t_i,|x_i|,|y_i| \le 10^{18}$。

## 题解

上下左右比较不好做，横纵坐标有关联。

考虑将坐标系逆时针旋转 $45^{\circ}$，同时放大到原来的 $\sqrt 2$ 倍。

这样 `ULDR` 对应的就是 $(1,1),(-1,1),(-1,-1),(1,-1)$，可以分开考虑横纵坐标了。

此时原来的 $(x_i,y_i)$ 则对应着 $(x_i + y_i, y_i - x_i)$。

但这样还不够方便，我们考虑将 $t$ 时刻的横纵坐标都加上 $t$ 再除以 $2$。

这样 `ULDR` 对应的就是 $(1,1),(0,1),(0,0),(1,0)$，此时原来的 $(x_i,y_i)$ 对应成 $(\frac{x_i+y_i+t}2, \frac{y_i-x_i+t}2)$。

先判掉奇偶性不合法的情况，剩下的只用考虑距离上的约束。

设 $s_i$ 表示时刻 $i$ 的位置，一个周期的位移 $v = s_{l}$。

对于第 $i$ 条信息，设 $k_i = \lfloor \frac{t_i}l \rfloor$，$w_i = t_i \bmod l$，则有 $(x_i, y_i) = s_{t_i} = k_i v + s_{w_i}$。

为了方便后面的操作，我们加上 $k_i = 0, w_i = 0$ 和 $k_i = -1, w_i = l$ 这两条信息，显然这两条信息中 $t_i = x_i = y_i = 0$。

对 $w_i$ 排序然后差分，对于前后差分的 $i,j$，设 $k = k_j - k_i$，可以得到 $kv + (s_{w_j} - s_{w_i}) = (x_j - x_i, y_j - y_i)$。

将 $x,y$ 分开考虑，在这里以 $x$ 为例。

由于每次只能 $+0/1$，设 $w = w_j - w_i$，有 $0 \le (s_{w_j} - s_{w_i})_x \le w$。

即 $x_j - x_i - w \le kv_x \le x_j-x_i$。

若 $k = 0$，如果不满足 $x_j - x_i - w \le 0 \le x_j - x_i$，则无解。

若 $k > 0$，得到 $\lceil \frac{x_j - x_i - w}{k}\rceil \le v_x \le \lfloor \frac{x_j - x_i}{k} \rfloor$，同理有 $\lceil \frac{y_j - y_i - w}{k}\rceil \le v_y \le \lfloor \frac{y_j - y_i}{k} \rfloor$。

若 $k < 0$，得到 $\lceil \frac{x_i - x_j}{-k}\rceil \le v_x \le \lfloor \frac{x_i - x_j+w}{-k} \rfloor$，同理有 $\lceil \frac{y_i - y_j}{-k}\rceil \le v_x \le \lfloor \frac{y_i - y_j+w}{-k} \rfloor$。

一共有 $\mathcal O(n)$ 个这样的不等式，形成的不等式组如果有解即可任选一组解构造。

具体构造的方法是，确定 $v$ 之后根据 $(x_i, y_i) = s_{t_i} = k_i v + s_{w_i}$ 确定所有 $s_{w_i}$。

对于差分后相邻的两项，可以先从 $s_i$ 最快地走到 $s_j$，有多余的步数在 $s_j$ 附近反复横跳即可，由于判掉了奇偶性不合法的情况，这样一定可以消耗尽所有多余的步数同时最终停在 $s_j$。

总时间复杂度 $\mathcal O(n \log n)$。

## 代码

```cpp
#define Fail prints("NO"), exit(0)
const int N = 2e5 + 7;
const ll inf = 4e18;
int n, l;
ll lx = -inf, rx = inf, ly = -inf, ry = inf;
struct P {
	ll t, x, y, k;
	int w;
	inline void in() {
		ll p, q;
		rd(t), rd(p), rd(q);
		if ((t ^ p ^ q) & 1) Fail;
		k = t / l, w = t % l;
		x = (p + q + t) / 2, y = (q - p + t) / 2;
	}
	inline bool operator < (const P &o) const { return w < o.w; }
} p[N];

int main() {
	rd(n), rd(l);
	for (int i = 1; i <= n; i++) p[i].in();
	sort(p + 1, p + n + 1);
	p[++n].k = -1, p[n].w = l;
	for (int i = 1; i <= n; i++) {
		ll k = p[i].k - p[i-1].k;
		int w = p[i].w - p[i-1].w;
		if (!k) {
			if (p[i].x - p[i-1].x - w > 0 || p[i].x - p[i-1].x < 0) Fail;
			if (p[i].y - p[i-1].y - w > 0 || p[i].y - p[i-1].y < 0) Fail;
		} else if (k > 0) {
			lx = max(lx, (ll)ceil(1.0L * (p[i].x - p[i-1].x - w) / k));
			rx = min(rx, (ll)floor(1.0L * (p[i].x - p[i-1].x) / k));
			ly = max(ly, (ll)ceil(1.0L * (p[i].y - p[i-1].y - w) / k));
			ry = min(ry, (ll)floor(1.0L * (p[i].y - p[i-1].y) / k));
		} else {
			k *= -1;
			lx = max(lx, (ll)ceil(1.0L * (p[i-1].x - p[i].x) / k));
			rx = min(rx, (ll)floor(1.0L * (p[i-1].x - p[i].x + w) / k));
			ly = max(ly, (ll)ceil(1.0L * (p[i-1].y - p[i].y) / k));
			ry = min(ry, (ll)floor(1.0L * (p[i-1].y - p[i].y + w) / k));
		}
	}
	if (lx > rx || ly > ry) Fail;
	for (int i = 1; i <= n; i++) {
		int dx = (p[i].x - p[i].k * lx) - (p[i-1].x - p[i-1].k * lx);
		int dy = (p[i].y - p[i].k * ly) - (p[i-1].y - p[i-1].k * ly);
		int t = p[i].w - p[i-1].w, x = 0, y = 0;
		while (t--)
			if (x < dx) {
				++x;
				if (y < dy) putchar('U'), ++y;
				else putchar('R');
			} else {
				if (y < dy) putchar('L'), ++y;
				else putchar('D');
			}
	}
	return 0;
}
```

> [CF573E Bear and Bowling](https://codeforces.com/contest/573/problem/E)

## 题意

- 给定一个长度为 $n$ 的序列 $a_{1\dots n}$。
- 你要求一个 $a$ 的子序列 $b_{1\dots m}$（可以为空），使得 $\sum_{i=1}^m ib_i$ 的值最大。
- $n \le 10^5$，$|a_i| \le 10^7$。

## 题解

首先有个显然的贪心：每次选择贡献最大的位置，直到贡献非正，此时贡献和即为答案。

这里的贡献可以简单的写成 $k_ia_i+b_i$，其中 $k_i$ 为 $i$ 之前被选择的位置数 $+1$，$b_i$ 表示 $i$ 之后被选择的位置的 $a$ 之和。

相当于我们要维护 $n$ 个一次函数 $k_ia_i + b_i$，支持区间 $k_i,b_i$ 加和全局最大值。

这玩意儿是有办法 $\text{polylog}$ 维护的（详见 [EI 的提交](https://codeforces.com/contest/573/submission/68101378)），但非常复杂。

考虑分块，块内使用单调队列维护一个上凸壳。

对于每次最大的位置 $p$，先将 $p$ 的贡献计入答案，然后删除 $p$（将 $p$ 的贡献设为 $-\infty$）。

对于 $p$ 之前的位置 $i$，相当于 $b_i$ 加上 $a_p$；对于 $p$ 之后的位置 $i$，相当于 $k_i$ 加上 $1$。

对于每一整块，打上两个分别关于 $k,b$ 的标记即可；而对于 $p$ 所在的块，暴力重构即可。

总时间复杂度 $\mathcal O(n \sqrt n)$。

## 代码

```cpp
const int N = 1e5 + 7, M = 370;
const ld inf = 1e18L;
int n, m, k, a[N], b[N], p[N], l[M], r[M];
ll f[N], ans;

struct T {
	int l, r, q[M];
	ll k, b;
	inline ll c(int i) {
		return f[i] + k * a[i] + b;
	}
	inline ld s(int i, int j) {
		if (a[i] == a[j]) return f[i] > f[j] ? -inf : inf;
		return 1.0L * (f[i] - f[j]) / (a[i] - a[j]);
	}
	inline void build(int x) {
		for (int i = ::l[x]; i <= ::r[x]; i++) f[i] += k * a[i] + b;
		k = b = l = r = 0;
		for (int i = ::l[x]; i <= ::r[x]; i++) {
			while (r - l > 1 && s(q[r-2], q[r-1]) < s(q[r-1], p[i])) --r;
			q[r++] = p[i];
		}
	}
	inline pair<ll, int> ask() {
		while (r - l > 1 && c(q[l]) <= c(q[l+1])) ++l;
		return mp(c(q[l]), q[l]);
	}
} t[M];

int main() {
	rd(n), m = sqrt(n);
	for (int i = k = 1; i <= n; k += !(i % m), i++)
		rd(a[i]), f[i] = a[i], p[i] = i, b[i] = k;
	if (!(n % m)) --k;
	for (int i = 1; i <= k; i++) {
		l[i] = r[i-1] + 1, r[i] = min(i * m, n);
		sort(p + l[i], p + r[i] + 1, [&](int i, int j) { return a[i] < a[j]; });
		t[i].build(i);
	}
	while (1) {
		pair<ll, int> o = mp(0ll, 0);
		for (int i = 1; i <= k; i++) o = max(o, t[i].ask());
		if (!o.fi) return print(ans), 0;
		ans += o.fi, f[o.se] = -inf;
		for (int i = 1; i < b[o.se]; i++) t[i].b += a[o.se];
		for (int i = l[b[o.se]]; i < o.se; i++) f[i] += a[o.se];
		for (int i = o.se + 1; i <= r[b[o.se]]; i++) f[i] += a[i];
		for (int i = b[o.se] + 1; i <= k; i++) ++t[i].k;
		t[b[o.se]].build(b[o.se]);
	}
	return 0;
}
```

> [CF566E Restoring Map](https://codeforces.com/contest/566/problem/E)

## 题意

- 有一棵 $n$ 个点的树，你不知道这棵树的边是怎么连的。
- 你得到了 $n$ 条关于每个点信息，每条信息记录了距离某一个点 $\le 2$ 的所有点。
- 但你不知道每条信息具体是哪个点的。
- 你需要构造一棵满足这些信息的树。
- $n \le 10^3$。

## 题解

我们将**叶子节点**定义为**度数为 $1$** 的节点，**非叶节点**定义为**度数 $>1$** 的节点。

首先我们来考虑大部分情况，即**至少有三个非叶节点**的情况。

在这种情况下，**两个非叶节点 $(x,y)$ 之间存在边，当且仅当存在两个集合的交为 $\\{x,y\\}$**。

于是可以得到所有非叶节点之间的连边，bitset 优化即可做到 $\mathcal O(\frac{n^3}w)$。

**值得一提的是，如果当存在两个集合的交集大小为 $2$ 时，对 bitset 暴力 `for` 循环找值为 $1$ 的位置，复杂度并不会除以那个 $w$，是错的，可以被卡掉，但不知道为什么 CF 没有卡，也许是因为 CF 评测机太快了。正确的写法是借用 `_Find_first()` 和 `_Find_next()` 函数，前者是找到 bitset 中从低位到高位第一个 $1$ 的位置，后者是找到当前位置的下一个为 $1$ 的位置，这样复杂度才会除以那个 $w$。**

现在，我们知道每个点是否为叶子节点，接下来考虑如何找到叶子节点在树中的父亲。

显然，**对于每个叶子节点，在所有包含它的集合中，节点数最少的集合一定就是此叶子节点的集合**。因此我们可以确定每个叶子节点对应的集合是哪个。

如果我们把**连边集合**定义为**一个非叶节点与和它相连的非叶节点**构成的集合，可以发现，**一个叶子节点的集合中去掉所有叶子节点**等于**其父亲的连边集合**，而所有非叶节点的连边集合一定互不相同，那么我们就可以确定所有叶子节点的父亲了，这里同样可以 bitset 优化。

最后来考虑非叶节点数量少于三个的情况。

如果不存在非叶节点，则 $n=2$，可以直接判掉。

如果只有一个非叶节点，那就意味着所有集合都是 $\{1,2,\cdots n\}$，也可以直接判掉。

如果有两个非叶节点，我们先采用至少三个非叶节点的方法找到这两个非叶节点，然后会发现这两个非叶节点的连边集合是一样的。但是，这个时候叶子的集合就只有两种，选其中一种里的叶子挂在一个非叶节点下，另一种里的叶子挂在另外一个非叶节点下就好了。

总时间复杂度 $\mathcal O(\frac{n^3}w)$。

## 代码

```cpp
const int N = 1e3 + 7;
int n, v[N], w[N], cnt;
bitset<N> a[N], b[N], e[N];

int main() {
	rd(n);
	if (n == 2) return prints("1 2"), 0;
	bool ok = 1;
	for (int i = 1, j, k; i <= n; i++) {
		rd(k);
		if (k != n) ok = 0;
		while (k--) rd(j), a[i][j] = 1;
	}
	if (ok) {
		for (int i = 1; i < n; i++) print(n, ' '), print(i);
		return 0;
	}
	for (int i = 1; i <= n; i++)
		for (int j = i + 1; j <= n; j++) {
			bitset<N> o = a[i] & a[j];
			if (o.count() != 2) continue;
			int x = o._Find_first(), y = o._Find_next(x);
			if (e[x][y]) continue;
			print(x, ' '), print(y);
			e[x][y] = e[y][x] = 1, v[x] = v[y] = 1;
		}
	for (int i = 1; i <= n; i++)
		if (!v[i]) {
			int s = n + 1, o = 0;
			for (int j = 1; j <= n; j++)
				if (!w[j] && a[j][i]) {
					int c = a[j].count();
					if (c < s) s = c, o = j;
				}
			b[i] = a[o], w[o] = 1;
		} else e[i][i] = 1, ++cnt;
	if (cnt == 2) {
		int x, y;
		for (int i = 1; i <= n; i++)
			if (v[i]) x = i;
		for (int i = n; i; i--)
			if (v[i]) y = i;
		for (int i = 1; i <= n; i++)
			if ((int)a[i].count() != n) {
				for (int j = 1; j <= n; j++) {
					if (v[j]) continue;
					if (a[i][j]) print(x, ' ');
					else print(y, ' ');
					print(j);
				}
				break;
			}
		return 0;
	}
	for (int i = 1; i <= n; i++)
		if (!v[i]) {
			for (int j = 1; j <= n; j++)
				if (!v[j]) b[i][j] = 0;
			for (int j = 1; j <= n; j++)
				if (v[j] && b[i] == e[j]) {
					print(i, ' '), print(j);
					break;
				}
		}
	return 0;
}
```

> [CF613E Puzzle Lover](https://codeforces.com/contest/613/problem/E)

## 题意

- 给定一个 $2 \times n$ 的矩阵，每个位置上有一个小写字母。
- 有一个长度为 $k$ 的小写字符串 $w$，询问矩阵中有多少条有向路径满足以下条件：
  - 路径上的字母连起来恰好为 $w$。
  - 不多次经过同一个位置。
  - 只能向上下左右四个方向走。
- $n,k \le 2 \times 10^3$，答案对 $10^9+7$ 取模。

## 题解

假设 $n,k$ 同阶。

考虑**头尾不在同一列**的情况，不妨设头在尾的左侧。对于头在尾的右侧的情况，可以将 $w$ 翻转之后在求一遍。

当头在尾的左侧时，我们将路径划分成连续的三个部分：

1. 头所在的列及其左侧的部分；
2. 在头的右侧尾的左侧的部分；
3. 尾所在的列及其右侧的部分。

对于任意一条路径，它的第 $1/3$ 部分都肯定非空，而第 $2$ 部分可能为空。

下面我们依次考虑每一个部分：

1. 这部分要么是一个格子，要么是一个 U 字形，我们可以对于每个格子求出「若第 $1$ 部分在这个格子结束，所有可能的第 $1$ 部分的长度」，借助 Hash 即可做到 $\mathcal O(n^2)$。
2. 这部分不能往左，考虑 dp，设 $f_{i,j,k}$ 表示「若第 $2$ 部分在 $(i,j)$ 结束，上一个格子为 $(i,j-1)$，且第 $1,2$ 部分的长度和为 $k$ 的方案数」，设 $g_{i,j,k}$ 表示「若第 $2$ 部分在 $(i,j)$ 结束，上一个格子其同一列，且第 $1,2$ 部分的长度和为 $k$ 的方案数」，从左到右转移，转移时枚举下一个格子即可，时间复杂度为 $\mathcal O(n^2)$。
3. 与第 $1$ 部分一样，对于每个格子求出「若第 $3$ 部分从这个格子开始，所有可能的第 $3$ 部分的长度」，然后与第 $2$ 部分接上，即第 $2$ 部分的结束的格子的右边一个格子就是第 $3$ 部分开始的格子，同样借助 Hash 可以做到 $\mathcal O(n^2)$。

还剩下**头尾在同一列**的情况，可以发现我们直接在考虑第 $1/3$ 部分时顺便解决掉就好了，注意翻转前后会重复计算一次，最后除掉就好了。

总时间复杂度 $\mathcal O(n^2)$。

## 代码

```cpp
#define Hash pair<modint, modint>
const Hash B = mp(131, 13331);
inline Hash operator + (Hash a, Hash b) { return mp(a.fi + b.fi, a.se + b.se); }
inline Hash operator - (Hash a, Hash b) { return mp(a.fi - b.fi, a.se - b.se); }
inline Hash operator * (Hash a, Hash b) { return mp(a.fi * b.fi, a.se * b.se); }
inline Hash operator + (Hash a, int b) { return mp(a.fi + b, a.se + b); }

const int N = 2e3 + 7;
int n, m;
char s[3][N];
modint f[2][N][N], g[2][N][N], ans, now;
Hash p[N], h[2][3][N];
bool a[2][N][N], b[2][N][N];

inline Hash H(int o, int i, int l, int r) {
	if (!o) return h[o][i][r] - h[o][i][l-1] * p[r-l+1];
	return h[o][i][l] - h[o][i][r+1] * p[r-l+1];
}

inline bool pd(int o, int i, int j, int k) {
	if (!o) {
		if (j < k) return 0;
		if (H(1, i ^ 1, j - k + 1, j) != H(0, 2, 1, k)) return 0;
		if (H(0, i, j - k + 1, j) != H(0, 2, k + 1, 2 * k)) return 0;
		return 1;
	}
	if (j + k - 1 > n) return 0;
	if (H(0, i, j, j + k - 1) != H(0, 2, m - 2 * k + 1, m - k)) return 0;
	if (H(1, i ^ 1, j, j + k - 1) != H(0, 2, m - k + 1, m)) return 0;
	return 1; 
}

inline void solve() {
	for (int i = 1; i <= m; i++) h[0][2][i] = h[0][2][i-1] * B + s[2][i];
	for (int i = 0; i <= 1; i++)
		for (int j = 1; j <= n; j++)
			for (int k = 1; k <= m; k++) {
				f[i][j][k] = g[i][j][k] = 0;
				if (k == 1) {
					g[i][j][k] = a[i][j][k] = s[i][j] == s[2][1];
					b[i][j][k] = s[i][j] == s[2][m];
				} else if (!(k & 1)) {
					g[i][j][k] = a[i][j][k] = pd(0, i, j, k / 2);
					b[i][j][k] = pd(1, i, j, k / 2);
				}
				if (k == m) {
					now += a[i][j][k];
					if (m > 2) now += b[i][j][k];
				}
			}
	dbg(ans.x);
	for (int j = 1; j <= n; j++)
		for (int k = 1; k <= m; k++) {
			for (int i = 0; i <= 1; i++)
				if (s[i][j] == s[2][k])
					f[i][j][k] += f[i][j-1][k-1] + g[i][j-1][k-1];
			for (int i = 0; i <= 1; i++)
				if (s[i][j] == s[2][k])
					g[i][j][k] += f[i^1][j][k-1];
			for (int i = 0; i <= 1; i++)
				if (b[i][j+1][m-k])
					ans += f[i][j][k] + g[i][j][k];
		}
}

int main() {
	rds(s[0], n), rds(s[1], n), rds(s[2], m), p[0] = mp(1, 1);
	for (int i = 1; i <= max(n, m); i++) p[i] = p[i-1] * B;
	for (int i = 0; i <= 1; i++) {
		for (int j = 1; j <= n; j++)
			h[0][i][j] = h[0][i][j-1] * B + s[i][j];
		for (int j = n; j; j--)
			h[1][i][j] = h[1][i][j+1] * B + s[i][j];
	}
	solve(), reverse(s[2] + 1, s[2] + m + 1), solve(), print(ans + now / 2);
	return 0;
}
```

> [CF527E Data Center Drama](https://codeforces.com/contest/527/problem/E)

## 题意

- 给定一张 $n$ 个点 $m$ 条边无向图。
- 你需要加尽可能少的边，然后给所有边定向，使得每一个点的出入度都是偶数。
- 边可以是自环，也可以由重边。
- $n \le 10^5$，$m \le 2 \times 10^5$。

## 题解

若每个点的出入度都是偶数，则每个点的总度数是偶数，而这是一张图存在**欧拉回路**的充要条件。

所以将所有总度数为奇数的点两两相连。

但是并不是所有存在欧拉回路的图都满足条件，还需要满足边数为偶数。

那么随便找一个点加一个自环即可。

这显然是最少的加边方案。

最后跑一个欧拉回路出来，然后隔一条边换一个方向即可。

## 代码

```cpp
const int N = 1e5 + 7, M = 1e6 + 7;
int n, m, h[N], e[M], t[M], tot = 1, d[N], v[M], k;
vi p;

inline void add(int x, int y, int o = 1) {
	e[++tot] = y, t[tot] = h[x], h[x] = tot;
	if (o) ++d[x], ++d[y], add(y, x, 0);
}

void dfs(int x) {
	for (int &i = h[x]; i; i = t[i]) {
		if (v[i]) continue;
		v[i] = v[i^1] = 1;
		int y = e[i];
		dfs(y);
		if ((++k) & 1) print(x, ' '), print(y);
		else print(y, ' '), print(x);
	}
}

int main() {
	rd(n), rd(m);
	for (int i = 1, x, y; i <= m; i++) rd(x), rd(y), add(x, y);
	for (int i = 1; i <= n; i++) if (d[i] & 1) p.pb(i);
	for (ui i = 0; i < p.size(); i += 2) add(p[i], p[i+1]), ++m;
	if (m & 1) add(1, 1), ++m;
	print(m), dfs(1);
	return 0;
}
```

> [CF611H New Year and Forgotten Tree](https://codeforces.com/contest/611/problem/H)

## 题意

- 有一棵 $n$ 个节点的树，节点编号为 $1 \sim n$。
- 记录这棵树的方式是记录下每条边连接的两点的编号。
- 现在，你不知道这些编号具体是多少，你只知道它们在十进制下的位数。
- 请你构造出一棵满足要求的树，或判断没有满足要求的树。
- $n \le 2 \times 10^5$。

## 题解

不妨把位数相同的点称为同种颜色，则显然有 $m = \lfloor \log_{10} n \rfloor + 1$ 种颜色。

对于每种颜色选择一个关键点，可以发现，如果存在合法的树，一定存在一种情况，使得关键点连成一个连通块，其他点连向某一个关键点。

那么，我们可以 $\mathcal O(m^{m-2})$ 枚举 Prufer 序列得到关键点的连通方式，对于剩下的颜色边 $(x,y)$，我们可以将 $x$ 接到 $y$ 的关键点上，也可以将 $y$ 接到 $x$ 的关键点上。

这相当于要做一个二分图多重匹配：

1. 二分图的左部点为每种类型的边，一共有 $\frac{m(m+1)}2$ 个点，每个点的数量为原树对应的边的数量减去关键点之间对应的边的数量。
2. 二分图的右部点为每种颜色的点，一共有 $m$ 个点，每个点的数量为原树对应的点的数量减去关键点中对应的点的数量。
3. 对于颜色边 $(x,y)$，将其对应的左部点分别与 $x,y$ 对应的右部点连边，数量为 $+\infty$。

如果这个二分图存在多重完备匹配，则说明有解，否则无解。

那么跑一遍网络流即可判断，如果有解则可以直接根据残量网络构造。

由于 $m$ 非常小，所以可以不用考虑时间复杂度，保证正确性即可。

## 代码

```cpp
namespace Dinic {
	const int N = 107, M = 1e3 + 7;
	const ll inf = 1e18;
	int n, m, S, T, h[N], hi[N], e[M], t[M], tot = 1, d[N];
	ll mxf, f[M];
	inline void add(int x, int y, ll z, int o = 1) {
		e[++tot] = y, f[tot] = z, t[tot] = h[x], h[x] = tot;
		if (o) add(y, x, 0, 0);
	}
	inline bool bfs() {
		for (int i = 1; i <= n; i++) d[i] = 0;
		queue<int> q;
		q.push(S), d[S] = 1;
		while (q.size()) {
			int x = q.front();
			q.pop();
			for (int i = h[x]; i; i = t[i]) {
				int y = e[i];
				ll z = f[i];
				if (d[y] || !z) continue;
				q.push(y), d[y] = d[x] + 1;
				if (y == T) return 1;
			}
		}
		return 0;
	}
	ll dinic(int x, ll nwf) {
		if (x == T) return nwf;
		ll rst = nwf;
		for (int &i = hi[x]; i; i = t[i]) {
			int y = e[i];
			ll z = f[i];
			if (d[y] != d[x] + 1 || !z) continue;
			ll k = dinic(y, min(z, rst));
			if (!k) d[y] = 0;
			else f[i] -= k, f[i^1] += k, rst -= k;
			if (!rst) break;
		}
		return nwf - rst;
	}
	inline void main() {
		while (bfs()) {
			for (int i = 1; i <= n; i++) hi[i] = h[i];
			ll now;
			while ((now = dinic(S, inf))) mxf += now; 
		}
	}
}

const int N = 2e5 + 7, M = 9;
int n, p[M], q[M], m, a[M], b[M], d[M], g[M];
char s[M];
map<pi, int> c, f;

inline void work() {
	for (int i = 1; i <= m; i++) d[i] = 0;
	for (int i = 1; i <= m - 2; i++) ++d[a[i]]; a[m-1] = m;
	map<pi, int> c = ::c;
	vector<pi> e;
	for (int i = 1, j = 1; i < m; i++, j++) {
		while (d[j]) ++j; e.pb(mp(j, a[i]));
		while (i < m && !--d[a[i]] && a[i] < j) e.pb(mp(a[i], a[i+1])), ++i;
	}
	for (pi o : e) {
		if (o.fi > o.se) swap(o.fi, o.se);
		if (!c[o]--) return;
	}
	Dinic::n = 2 + m + m * (m + 1) / 2;
	Dinic::S = Dinic::n - 1, Dinic::T = Dinic::n;
	Dinic::tot = 1, Dinic::mxf = 0;
	for (int i = 1; i <= Dinic::n; i++) Dinic::h[i] = 0;
	int k = m;
	vector<pi> ff(Dinic::n);
	for (int i = 1; i <= m; i++) {
		Dinic::add(i, Dinic::T, b[i]);
		for (int j = i; j <= m; j++) {
			f[mp(i,j)] = ++k, ff[k] = mp(i, j);
			Dinic::add(Dinic::S, k, c[mp(i,j)]);
			Dinic::add(k, i, Dinic::inf);
			Dinic::add(k, j, Dinic::inf);
		}
	}
	Dinic::main();
	if (Dinic::mxf != n - m) return;
	for (pi o : e) print(p[o.fi], ' '), print(p[o.se]);
	for (int x = 1; x <= m; x++) {
		q[x] = p[x];
		for (int i = Dinic::h[x]; i; i = Dinic::t[i]) {
			int y = Dinic::e[i];
			if (y <= m || y >= Dinic::S) continue;
			y = ff[y].fi == x ? ff[y].se : ff[y].fi;
			while (Dinic::f[i]--) print(++q[x], ' '), print(p[y]);
		}
	}
	exit(0);
}

void dfs(int o) {
	if (o == m - 1) return work();
	for (int i = 1; i <= m; i++) a[o] = i, dfs(o + 1);
}

int main() {
	rd(n);
	for (int o = 1; o <= n; o *= 10) p[++m] = o;
	for (int i = 1; i < m; i++) b[i] = p[i+1] - 1 - p[i];
	b[m] = n - p[m];
	for (int i = 1, x, y; i < n; i++) {
		rds(s, x), rds(s, y);
		if (x > y) swap(x, y);
		++c[mp(x,y)];
	}
	if (m == 1) {
		if (c[mp(1,1)] != n - 1) return print(-1), 0;
		for (int i = 1; i < n; i++) print(i, ' '), print(i + 1);
		return 0;
	}
	dfs(1), print(-1);
	return 0;
}
```

> Prufer 序列是一种将带标号的树用一个唯一的整数序列表示的方法。
> 在本文中，我们要求树的节点数 $\ge 2$。

## Prufer 序列

Prufer 序列可以将一个带标号 $n$ 个节点的树用 $[1,n]$ 中的 $n-2$ 个整数表示，即 **$n$ 个点的完全图的生成树**与**长度为 $n-2$ 值域为 $[1,n]$ 的数列**构成的双射。

Prufer 序列可以方便的解决一类树相关的计数问题，比如[凯莱定理](https://www.luogu.com.cn/problem/UVA10843)：$n$ 个点的完全图的生成树有 $n^{n-2}$ 个。

## 对树构造 Prufer 序列

Prufer 是这样构造的：

每次选择一个编号最小的叶节点并删掉它，然后在序列中记录下它连接到的那个节点。

重复 $n-2$ 次后就只剩下两个节点，算法结束。

#### $\mathcal O(n \log n)$

显然，使用堆可以做到 $O(n\log n)$ 的复杂度。

#### $\mathcal O(n)$

使用一个指针代替堆找最小值，可以做到 $\mathcal O(n)$ 的复杂度。

具体而言，指针指向编号最小的叶节点。每次删掉它之后，如果产生了新的叶节点且编号比指针指向的更小，则直接继续删掉，否则自增找到下一个编号最小的叶节点。

#### Prufer 序列的性质

从上述构造 Prufer 序列的过程可以看出 Prufer 序列具有以下两个性质：

1. 在构造完 Prufer 序列后原树中会剩下两个节点，其中一个一定是编号最大的点 $n$。
2. 每个节点在序列中出现的次数是其度数减 $1$，因此没有出现的就是叶节点。

## 用 Prufer 序列构造树

根据 Prufer 序列的性质，我们可以得到原树上每个点的度数。

每次我们选择一个编号最小的度数为 $1$ 的节点，与当前枚举到的 Prufer 序列的点连接，然后同时减掉两个点的度数。重复 $n-2$ 次后就只剩下两个度数为 $1$ 的节点，其中一个是 $n$，把它们连接起来即可。

#### $\mathcal O(n \log n)$

同样地，显然，使用堆可以做到 $O(n\log n)$ 的复杂度。

#### $\mathcal O(n)$

类似地，使用一个指针代替堆找最小值，可以做到 $\mathcal O(n)$ 的复杂度。

具体而言，指针指向编号最小的度数为 $1$ 的节点。每次将它与当前枚举到的 Prufer 序列的点连接之后，如果产生了新的度数为 $1$ 的节点且编号比指针指向的更小，则直接继续将它与下一个 Prufer 序列的点连接，否则自增找到下一个编号最小的度数为 $1$ 的节点。

#### 【模板】[P6086 【模板】Prufer 序列](https://www.luogu.com.cn/problem/P6086)

```cpp
const int N = 5e6 + 7;
int n, o, f[N], p[N], d[N];
ll ans;

inline void TP() {
	for (int i = 1; i < n; i++) rd(f[i]), ++d[f[i]];
	for (int i = 1, j = 1; i <= n - 2; i++, j++) {
		while (d[j]) ++j; p[i] = f[j];
		while (i <= n - 2 && !--d[p[i]] && p[i] < j) p[i+1] = f[p[i]], ++i;
	}
	for (int i = 1; i <= n - 2; i++) ans ^= 1ll * i * p[i];
}

inline void PT() {
	for (int i = 1; i <= n - 2; i++) rd(p[i]), ++d[p[i]]; p[n-1] = n;
	for (int i = 1, j = 1; i < n; i++, j++) {
		while (d[j]) ++j; f[j] = p[i];
		while (i < n && !--d[p[i]] && p[i] < j) f[p[i]] = p[i+1], ++i;
	}
	for (int i = 1; i < n; i++) ans ^= 1ll * i * f[i];
}

int main() {
	rd(n), rd(o), o == 1 ? TP() : PT(), print(ans);
	return 0;
}
```

## 应用：图连通方案数

前面提到，Prufer 序列可以方便的解决一类树相关的计数问题。

考虑下面这个问题：

> 给定一个 $n$ 个点 $m$ 条边的带标号无向图，它有 $k$ 个连通块，求添加 $k-1$ 条边使得整个图连通的方案数。

设 $s_i$ 为第 $i$ 个连通块的点数，$d_i$ 为第 $i$ 个连通块的度数。

对于给定的 $d$ 序列构造 Prufer 序列的方案数为：
$$
\binom{k-2}{d_1-1,d_2-1,\cdots,d_k-1}=\frac{(k-2)!}{(d_1-1)!(d_2-1)!\cdots(d_k-1)!}
$$

对于给定的 $d$ 序列使图连通的方案数为：

$$
\binom{k-2}{d_1-1,d_2-1,\cdots,d_k-1}\cdot \prod_{i=1}^k{s_i}^{d_i}
$$

枚举 $d$ 序列使图连通的方案数为：

$$
\sum_{d_i\ge 1,\sum_{i=1}^kd_i=2k-2}\binom{k-2}{d_1-1,d_2-1,\cdots,d_k-1}\cdot \prod_{i=1}^k{s_i}^{d_i}
$$

设 $e_i=d_i-1$：

$$
\sum_{e_i\ge 0,\sum_{i=1}^ke_i=k-2}\binom{k-2}{e_1,e_2,\cdots,e_k}\cdot \prod_{i=1}^k{s_i}^{e_i+1}
$$

考虑多元二项式定理：

$$
(x_1 + \dots + x_m)^p = \sum_{c_i \ge 0,\sum_{i=1}^m c_i = p}\binom{p}{c_1, c_2, \cdots ,c_m} \cdot \prod_{i=1}^m{x_i}^{c_i}
$$

原式变为：

$$
(s_1+s_2+\cdots+s_k)^{k-2}\cdot \prod_{i=1}^ks_i
$$

即：

$$
n^{k-2}\cdot\prod_{i=1}^ks_i
$$

#### 【例题】[CF156D Clues](https://codeforces.com/contest/156/problem/D)

```cpp
const int N = 1e5 + 7;
int n, m, k, f[N], s[N];
modint ans = 1;

int get(int x) {
	return x == f[x] ? x : (f[x] = get(f[x]));
}

int main() {
	rd(n), rd(m), rd(P);
	if (P == 1) return print(0), 0;
	for (int i = 1; i <= n; i++) f[i] = i;
	for (int i = 1, x, y; i <= m; i++) rd(x), rd(y), f[get(x)] = get(y);
	for (int i = 1; i <= n; i++) ++s[get(i)];
	for (int i = 1; i <= n; i++) if (i == get(i)) ++k, ans *= s[i];
	if (k == 1) return print(1), 0;
	print(ans *= (modint)n ^ (k - 2));
	return 0;
}
```

