		set(1, l[a[i]], r[a[i]], i);
	}
	int asks(int p, int x) {
		if (t[p].l == t[p].r) return t[p].s;
		spd(p);
		return asks(x <= md ? ls : rs, x);
	}
	inline int asks(int i) {
		return asks(1, l[a[i]]);
