```cpp
const int N = 3.5e3 + 7;
int n, m, k, a[N];

inline void solve() {
	rd(n), rd(m), rd(k);
	for (int i = 1; i <= n; i++) rd(a[i]);
	if (k >= m - 1) return print(max(*max_element(a + 1, a + m + 1), *max_element(a + n - m + 1, a + n + 1)));
	int ans = 0;
	for (int i = 0; i <= k; i++) {
		int p = i + 1, q = n - (k - i), now = 1e9;
		for (int j = 0; j <= m - 1 - k; j++)
			now = min(now, max(a[p+j], a[q-(m-1-k-j)]));
		ans = max(ans, now);
	}
	print(ans);
}

int main() {
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
