## Infinite Prefixes

判掉 $\Sigma = 0$ 的情况（要么无解要么无限），枚举每个下标作为前缀最后一个数是否符合条件即可。

```cpp
const int N = 1e5 + 7;
int n, m, a[N];
char s[N];

inline void solve() {
	rd(n), rd(m), rds(s, n);
	for (int i = 1; i <= n; i++) a[i] = a[i-1] + (s[i] == '0' ? 1 : -1);
	if (!a[n]) {
		int l = 0, r = 0;
		for (int i = 1; i <= n; i++)
			l = min(l, a[i]), r = max(r, a[i]);
		if (l <= m && m <= r) print(-1);
		else print(0);
		return;
	}
	int t = !m;
	for (int i = 1; i <= n; i++)
		if ((m - a[i]) % a[n] == 0 && (m - a[i]) / a[n] >= 0) ++t;
	print(t);
}

int main() {
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
```

## Obtain The String

预处理每个位置往后的第一个 $\texttt{a} \sim \texttt{z}$，用 $t$ 去模拟匹配即可。

```cpp
const int N = 1e5 + 7;
int n, m, f[N][26], v[26];
char s[N], t[N];

inline void solve() {
	rds(s, n), rds(t, m);
	int ans = 1;
	for (int i = 0; i < 26; i++) v[i] = n + 1;
	for (int i = n; i; i--) {
		for (int j = 0; j < 26; j++) f[i][j] = v[j];
		v[s[i]-'a'] = i;
	}
	for (int i = 0; i < 26; i++) f[0][i] = v[i];
	for (int i = 1, j = 0; i <= m; i++) {
		int c = t[i] - 'a';
		if (f[j][c] != n + 1) j = f[j][c];
		else {
			++ans;
			if (f[0][c] == n + 1) return print(-1);
			j = f[0][c];
		}
	}
	print(ans);
}

int main() {
	int T;
	rd(T);
	while (T--) solve();
	return 0;
}
