const int N = 1e6 + 7;
int n, k, c[N];
ll a[N];

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(a[i]), a[i] += a[i-1];
	a[++n] = 1e18, rd(k);
	for (int i = 1, p = 2; i < n; i++) {
		while (a[p] < 2 * a[i]) ++p;
		if (a[i] <= k) ++c[a[i]];
		if (a[p] - a[i] <= k) --c[a[p]-a[i]];
