> [CF587D Duff in Mafia](https://codeforces.com/contest/587/problem/D)

## 题意

- 给定一张 $n$ 个点 $m$ 条边的无向图，每条边有一个颜色 $c$ 和权值 $t$。
- 你要选出一些边，使得它们是一个**匹配**，同时剩下的边每种颜色也是一个**匹配**。
- 同时，你要最小化选出的边的最大权值。
- $n,m \le 5 \times 10^4$。

## 题解

首先二分答案，若此时二分的值为 $o$，则所有 $> o$ 的边都不能选。

每条边有选和不选两种状态，所以考虑 2-SAT。设第 $i$ 条边的状态为 $x_i$ 表示选择它，$x^{\prime}_i$ 表示不选。连边如下：

1. 对于一定不能选的边，连边 $x_i \to x^{\prime}_ i$。
2. 对于选出的边一定要是一个匹配，考虑一个点 $p$ 上的所有边 $x_{1\dots k}$，连边 $x_i \to x^{\prime}_ j(i \ne j)$。
3. 对于剩下的边每种颜色也一定要是一个匹配，考虑一个点 $p$ 上颜色相同的所有边 $x_{1\dots k}$，连边 $x^{\prime}_ i \to x_j(i \ne j)$。

但这样做第 $2,3$ 类边的边数为 $\mathcal O(m^2)$，注意到 2-SAT 有一个经典的建图优化——前缀优化。

先考虑第 $2$ 类边，设 $x_{1\dots k}$ 的前缀点为 $s_{1\dots k}$，$x^{\prime}_ {1\dots k}$ 的后缀点为 $s^{\prime}_ {1\dots k}$。连边如下：

1. $x_i \to s_i$，$s^{\prime}_ i \to x^{\prime}_ i$。
2. $s_{i-1} \to s_i$，$s^{\prime}_ i \to s^{\prime}_ {i-1}$。
3. $s_{i-1} \to x^{\prime}_ i$，$x_i \to s^{\prime}_ {i-1}$。

![](http://www.xht37.com/wp-content/uploads/2020/01/TIM图片20200117230357.png)

容易发现和第 $2$ 类边是等效的。

而第 $3$ 类边，就把第 $2$ 类边的箭头全部反过来即可。

然后 tarjan 就好了。

总时间复杂度 $\mathcal O((n + m) \log w)$。

## 代码

```cpp
const int N = 5e4 + 7, M = 10 * N;
int n, m, tot, l, r;
int dfn[M], low[M], num, stk[M], top, ins[M], scc[M], cnt;
vi v[N], s, e[M], ans;
struct P {
	int u, v, c, t;
	inline void in() { 	rd(u), rd(v), rd(c), rd(t), r = max(r, t); }
} p[N];

inline void work1() {
	int S, T;
	for (ui i = 0; i < s.size(); i++) {
		int x = ::s[i], y = ::s[i] + m, s = ++tot, t = ++tot;
		e[x].pb(s), e[t].pb(y);
		if (i) e[S].pb(s), e[t].pb(T), e[S].pb(y), e[x].pb(T);
		S = s, T = t;
	}
	s.clear();
}

inline void work2() {
	int S, T;
	for (ui i = 0; i < s.size(); i++) {
		int x = ::s[i], y = ::s[i] + m, s = ++tot, t = ++tot;
		e[s].pb(x), e[y].pb(t);
		if (i) e[s].pb(S), e[T].pb(t), e[y].pb(S), e[T].pb(x);
		S = s, T = t;
	}
	s.clear();
}

void tarjan(int x) {
	dfn[x] = low[x] = ++num, stk[++top] = x, ins[x] = 1;
	for (auto y : e[x])
		if (!dfn[y]) tarjan(y), low[x] = min(low[x], low[y]);
		else if (ins[y]) low[x] = min(low[x], dfn[y]);
	if (dfn[x] == low[x]) {
		ins[x] = 0, scc[x] = ++cnt;
		while (x != stk[top--]) {
			int y = stk[top+1];
			ins[y] = 0, scc[y] = cnt;
		}
	}
}

inline void init(int o) {
	for (int i = 1; i <= m; i++) if (p[i].t > o) e[i].pop_back();
}

inline bool pd(int o) {
	for (int i = 1; i <= m; i++) if (p[i].t > o) e[i].pb(i + m);
	for (int i = 1; i <= tot; i++) dfn[i] = 0;
	cnt = num = 0;
	for (int i = 1; i <= tot; i++) if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= m; i++)
		if (scc[i] == scc[i+m]) return init(o), 0;
	return init(o), 1;
}

int main() {
	rd(n), rd(m), tot = m << 1;
	for (int i = 1; i <= m; i++)
		p[i].in(), v[p[i].u].pb(i), v[p[i].v].pb(i);
	for (int i = 1; i <= n; i++) {
		sort(v[i].begin(), v[i].end(),
			[&](int i, int j) { return p[i].c < p[j].c; });
		s = v[i], work1();
		for (ui l = 0, r = 0; l < v[i].size(); l = ++r) {
			s.pb(v[i][l]);
			while (r + 1 < v[i].size()
				&& p[v[i][r+1]].c == p[v[i][r]].c) s.pb(v[i][++r]);
			work2();
		}
	}
	if (!pd(r)) return prints("No"), 0;
	prints("Yes");
	while (l < r) {
		int mid = (l + r) >> 1;
		if (pd(mid)) r = mid;
		else l = mid + 1;
	}
	pd(l);
	for (int i = 1; i <= m; i++) if (scc[i] < scc[i+m]) ans.pb(i);
	print(l, ' '), print(ans.size());
	for (auto x : ans) print(x, ' ');
	return 0;
}
```

> [CF575I Robots protection](https://codeforces.com/contest/575/problem/I)

## 题意

- 你需要在平面直角坐标系上进行 $q$ 次操作。
- 每次操作有两种，要么放置一个两条直角边平行于坐标轴的等腰直角三角形，要么查询某一个点被多少个三角形覆盖。
- 每个等腰直角三角形可以用四个参数 $dir,x,y,len$ 确定，其中 $dir \in [1,4]$ 表示三角形的方向，$(x,y)$ 表示直角的顶点坐标，$len$ 表示直角边的长度。
- 保证所有点的坐标都是整数且 $\in [1,n]$。
- $n \le 5 \times 10^3$，$q \le 10^5$。

## 题解

$n$ 很小，二维树状数组即可。

注意到要分五类考虑，所以要在时间和空间卡一下常数。

![](http://www.xht37.com/wp-content/uploads/2020/01/1126418-20200108213332804-1585535723.png)

（图来自兔）

## 代码

```cpp
const int N = 1e4 + 7, M = 1e5 + 7;
int n, m, op[M], dir[M], x[M], y[M], c[M], ans[M];
int X, Y, bit[N][N], stx[M], sty[M], stz[M], top;

inline void add(int x, int y, int z) {
	stx[++top] = x, sty[top] = y, stz[top] = z;
	for (int i = x; i <= X; i += i & -i)
		for (int j = y; j <= Y; j += j & -j)
			bit[i][j] += z;
}

inline int ask(int x, int y) {
	int z = 0;
	for (int i = x; i; i -= i & -i)
		for (int j = y; j; j -= j & -j)
			z += bit[i][j];
	return z;
}

inline void clear() {
	while (top) add(stx[top], sty[top], -stz[top]), top -= 2;
}

int main() {
	rd(n), rd(m);
	for (int i = 1; i <= m; i++) {
		rd(op[i]);
		if (op[i] == 1) rd(dir[i]), rd(x[i]), rd(y[i]), rd(c[i]);
		else rd(x[i]), rd(y[i]);
	}

	X = n, Y = n;
	for (int i = 1; i <= m; i++)
		if (op[i] == 1) {
			if (dir[i] == 1) add(x[i], y[i], 1);
			if (dir[i] == 2) add(x[i], y[i] + 1, -1);
			if (dir[i] == 3) add(x[i] + 1, y[i], -1);
			if (dir[i] == 4) add(x[i] + 1, y[i] + 1, 1);
		} else ans[i] += ask(x[i], y[i]);
	clear();

	X = n + n, Y = n;
	for (int i = 1; i <= m; i++)
		if (op[i] == 1) {
			if (dir[i] == 1)
				add(x[i] + y[i] + c[i] + 1, y[i], -1);
			if (dir[i] == 4)
				add(x[i] + y[i] - c[i], y[i] + 1, -1);
		} else ans[i] += ask(x[i] + y[i], y[i]);
	clear();

	X = n, Y = n + n;
	for (int i = 1; i <= m; i++)
		if (op[i] == 1) {
			if (dir[i] == 1)
				add(n - x[i] + 2, x[i] + y[i] + c[i] + 1, 1);
			if (dir[i] == 4)
				add(n - x[i] + 1, x[i] + y[i] - c[i], 1);
		} else ans[i] += ask(n - x[i] + 1, x[i] + y[i]);
	clear();

	X = n + n, Y = n;
	for (int i = 1; i <= m; i++)
		if (op[i] == 1) {
			if (dir[i] == 2)
				add(n + x[i] - y[i] + c[i] + 2, y[i] + 1, 1);
			if (dir[i] == 3)
				add(n + x[i] - y[i] - c[i] + 1, y[i], 1);
		} else ans[i] += ask(n + x[i] - y[i] + 1, y[i]);
	clear();

	X = n, Y = n + n;
	for (int i = 1; i <= m; i++)
		if (op[i] == 1) {
			if (dir[i] == 2)
				add(x[i], n - x[i] + y[i] - c[i] + 1, 1);
			if (dir[i] == 3)
				add(x[i] + 1, n - x[i] + y[i] + c[i] + 2, 1);
		} else ans[i] += ask(x[i], n - x[i] + y[i] + 1);
	clear();

	for (int i = 1; i <= m; i++)
		if (op[i] == 2) printf("%d\n", ans[i]);
	return 0;
}
```

> [CF504E Misha and LCP on Tree](https://codeforces.com/contest/504/problem/E)

## 题意

- 给定一棵 $n$ 个节点的树，每个节点有一个小写字母。
- 有 $m$ 组询问，每组询问为树上 $a \to b$ 和 $c \to d$ 组成的字符串的最长公共前缀。
- $n \le 3 \times 10^5$，$m \le 10^6$。

## 题解

首先，根据 hash 值具有可减性，可以通过预处理每个点到根以及根到每个点的 hash 值，$\mathcal O(1)$ 求出任意一条没有拐点的路径的 hash 值。

考虑树剖，我们可以将 $a \to b$ 和 $c \to d$ 的路径分别拆成 $\mathcal O(\log n)$ 个区间，然后每次消掉一个区间。

如果消不掉这个区间，则在这个区间上二分找到答案。

总时间复杂度 $\mathcal O(n + m \log n)$。

另外，在 CF 上最好写双 hash，且不能采用自然溢出，否则大概率被卡。

## 代码

```cpp
#define Hash pair <modint, modint>

const int N = 3e5 + 7, mod = 1e9 + 7;
const Hash B = mp((modint)131, (modint)13331);
int n, m, d[N], f[N], s[N], son[N], dfn[N], rnk[N], top[N], num;
Hash p[N], h1[N], h2[N];
char c[N];
vi e[N];

inline Hash operator + (Hash a, Hash b) {
	return mp(a.fi + b.fi, a.se + b.se);
}

inline Hash operator - (Hash a, Hash b) {
	return mp(a.fi - b.fi, a.se - b.se);
}

inline Hash operator * (Hash a, Hash b) {
	return mp(a.fi * b.fi, a.se * b.se);
}

inline Hash H(bool o, int x, int k) {
	if (o) return h2[x-k+1] - h2[x+1] * p[k];
	return h1[x+k-1] - h1[x-1] * p[k];
}

void dfs(int x) {
	s[x] = 1;
	for (auto y : e[x])
		if (y != f[x]) {
			f[y] = x, d[y] = d[x] + 1, dfs(y), s[x] += s[y];
			if (s[y] > s[son[x]]) son[x] = y;
		}
}

void dfs(int x, int p) {
	top[x] = p, dfn[x] = ++num, rnk[num] = x;
	if (son[x]) dfs(son[x], p);
	for (auto y : e[x]) if (y != f[x] && y != son[x]) dfs(y, y);
}

inline int lca(int x, int y) {
	while (top[x] != top[y]) {
		if (d[top[x]] > d[top[y]]) swap(x, y);
		y = f[top[y]];
	}
	if (d[x] > d[y]) swap(x, y);
	return x;
}

inline vector <pi> get(int x, int y) {
	int z = lca(x, y);
	vector <pi> o, w;
	while (d[top[x]] > d[z]) o.pb(mp(x, top[x])), x = f[top[x]];
	o.pb(mp(x, z));
	while (d[top[y]] > d[z]) w.pb(mp(top[y], y)), y = f[top[y]];
	if (y != z) w.pb(mp(son[z], y));
	while (w.size()) o.pb(w.back()), w.pop_back();
	return o;
}

int main() {
	rd(n), rds(c, n), p[0] = mp(1, 1), p[1] = B;
	for (int i = 1, x, y; i < n; i++)
		rd(x), rd(y), e[x].pb(y), e[y].pb(x), p[i+1] = p[i] * B;
	d[1] = 1, dfs(1), dfs(1, 1);
	for (int i = 1; i <= n; i++)
		h1[i] = h1[i-1] * B + mp(c[rnk[i]], c[rnk[i]]),
		h2[n+1-i] = h2[n+2-i] * B + mp(c[rnk[n+1-i]], c[rnk[n+1-i]]);
	rd(m);
	while (m--) {
		int a, b, c, d, ans = 0;
		ui s = 0, t = 0;
		rd(a), rd(b), rd(c), rd(d);
		vector <pi> f = get(a, b), g = get(c, d);
		while (s < f.size() && t < g.size()) {
			int df1 = dfn[f[s].fi], df2 = dfn[f[s].se];
			int dg1 = dfn[g[t].fi], dg2 = dfn[g[t].se];
			bool of = df1 > df2, og = dg1 > dg2;
			int lf = (of ? df1 - df2 : df2 - df1) + 1;
			int lg = (og ? dg1 - dg2 : dg2 - dg1) + 1;
			int len = min(lf, lg);
			Hash hf = H(of, df1, len);
			Hash hg = H(og, dg1, len);
			if (hf == hg) {
				if (len == lf) ++s;
				else f[s].fi = rnk[df1+(of?-1:1)*len];
				if (len == lg) ++t;
				else g[t].fi = rnk[dg1+(og?-1:1)*len];
				ans += len;
			} else {
				int l = 1, r = len;
				while (l < r) {
					int mid = (l + r) >> 1;
					hf = H(of, df1, mid);
					hg = H(og, dg1, mid);
					if (hf == hg) l = mid + 1;
					else r = mid;
				}
				ans += l - 1; break;
			}
		}
		print(ans);
	}
	return 0;
}
```

> [CF521D Shop](https://codeforces.com/contest/521/problem/D)

## 题意

- 有 $k$ 个正整数 $a_{1\dots k}$。
- 有 $n$ 个操作，每个操作给定正整数 $b$，有三种可能：将 $a_i$ 赋值为 $b$，将 $a_i$ 加上 $b$，将 $a_i$ 乘以 $b$。
- 你可以从 $n$ 个操作中选择最多 $m$ 个操作，并按照一定顺序执行。
- 你的目标是最大化 $\prod_{i=1}^k a_i$ 的值。
- $k,n \le 10^5$。

## 题解

首先赋值可以转化成加法，只是要注意赋值必须在加法之前。

其次加法可以转化成乘法，不过必须按照从大到小贪心的转化，且加法也要在乘法之前。

对于加法转乘法，有一个麻烦一点的等价方法是，同样对每个数从大到小贪心的选择，只不过动态维护。

一开始假设所有乘法操作都要选，如果乘法操作的个数多于 $m$ 个，则去掉多出来贡献最小的。

对 $k$ 个数上的加法操作进行排序，我们要从大到小贪心的选择，可以用 $k$ 个指针维护。

用一个堆，每次取出贡献最大的加法操作，然后与贡献最小的乘法操作相比较。若加法操作的贡献更大，则去掉这个贡献最小的乘法操作，同时加入贡献最大的加法操作；否则说明此时达到最优解。

若 $n,m,k$ 同阶，则总时间复杂度为 $\mathcal O(n \log n)$。

## 代码

```cpp
const int N = 1e5 + 7;
int n, m, k, s;
ui t[N];
ll a[N], b;
pair <ll, int> v1[N];
vector <pair <ll, int> > v2[N], v3;
pq <pair <ld, int> > q;
vi ans;

inline void print() {
	for (int i = 1; i <= k; i++) {
		for (ui j = 0; j < t[i]; j++)
			if (v2[i][j].se < 0) ans.pb(-v2[i][j].se);
		for (ui j = 0; j < t[i]; j++)
			if (v2[i][j].se > 0) ans.pb(v2[i][j].se);
	}
	while (v3.size()) ans.pb(v3.back().se), v3.pop_back();
	print(ans.size());
	for (auto x : ans) print(x, ' ');
}

inline void get(int x) {
	if (t[x] < v2[x].size())
		q.push(mp(1.0L * v2[x][t[x]++].fi / a[x], x));
}

int main() {
	rd(k), rd(n), rd(m);
	for (int i = 1; i <= k; i++) rd(a[i]);
	for (int i = 1, o, x; i <= n; i++) {
		rd(o), rd(x), rd(b);
		if (o == 1) v1[x] = max(v1[x], mp(b, i));
		if (o == 2) v2[x].pb(mp(b, i));
		if (o == 3) v3.pb(mp(b, i));
	}
	for (int i = 1; i <= k; i++) {
		if (v1[i].fi > a[i])
			v2[i].pb(mp(v1[i].fi - a[i], -v1[i].se));
		sort(v2[i].begin(), v2[i].end());
		reverse(v2[i].begin(), v2[i].end());
		s += v2[i].size();
	}
	sort(v3.begin(), v3.end());
	reverse(v3.begin(), v3.end());
	while ((int)v3.size() > m) v3.pop_back();
	if (s + (int)v3.size() <= m) {
		for (int i = 1; i <= k; i++) t[i] = v2[i].size();
		return print(), 0;
	}
	for (int i = 1; i <= k; i++) get(i);
	for (int i = v3.size(); i < m; i++) {
		int x = q.top().se;
		q.pop(), a[x] += v2[x][t[x]-1].fi, get(x);
	}
	while (v3.size()) {
		int x = q.top().se;
		ll b1 = v2[x][t[x]-1].fi, b2 = v3.back().fi;
		if (b1 <= a[x] * (b2 - 1)) break;
		q.pop(), v3.pop_back(), a[x] += b1, get(x);
	}
	while (q.size()) {
		int x = q.top().se;
		q.pop(), --t[x];
	}
	return print(), 0;
}
```

