	}
}

int dfs(int x, int d) {
	if (!trie[x][0] && !trie[x][1]) return 0;
	if (!trie[x][0]) return dfs(trie[x][1], d - 1);
	if (!trie[x][1]) return dfs(trie[x][0], d - 1);
	return 1 << d | min(dfs(trie[x][0], d - 1), dfs(trie[x][1], d - 1));
}

