const int N = 107;
int n, a[N], f[N][N][N];

inline void upd(int &x, int y) {
	x = min(x, y);
}

int main() {
	rd(n);
	if (n == 1) return print(0), 0;
	for (int i = 1; i <= n; i++) rd(a[i]);
	memset(f, 0x3f, sizeof(f));
	if (a[1]) {
		if (a[1] & 1) {
			upd(f[1][0][a[1]], 0);
		} else {
			upd(f[1][1][a[1]], 0);
		}
	} else {
		for (a[1] = 1; a[1] <= n; a[1]++) {
			if (a[1] & 1) {
				upd(f[1][0][a[1]], 0);
			} else {
				upd(f[1][1][a[1]], 0);
			}
		}
	}
	for (int i = 2; i <= n; i++) {
		for (int j = 0; j <= min(i - 1, n >> 1); j++)
			for (int k = 1; k <= n; k++) {
				if (a[i]) {
					if (a[i] & 1) {
						if (i - 1 - j == n - (n >> 1)) continue;
						upd(f[i][j][a[i]], f[i-1][j][k] + ((k ^ a[i]) & 1));
					} else {
						if (j == (n >> 1)) continue;
						upd(f[i][j+1][a[i]], f[i-1][j][k] + ((k ^ a[i]) & 1));
					}
				} else {
					for (a[i] = 1; a[i] <= n; a[i]++) {
						if (a[i] & 1) {
							if (i - 1 - j == n - (n >> 1)) continue;
							upd(f[i][j][a[i]], f[i-1][j][k] + ((k ^ a[i]) & 1));
						} else {
							if (j == (n >> 1)) continue;
							upd(f[i][j+1][a[i]], f[i-1][j][k] + ((k ^ a[i]) & 1));
						}
					}
					a[i] = 0;
				}
			}
	}
	int ans = 0x3f3f3f3f;
	for (int i = 1; i <= n; i++) ans = min(ans, f[n][n>>1][i]);
	print(ans);
	return 0;
}
