P a[N];

inline int f(P o) {
	int x = o.x, y = o.y;
	if (x <= 0 && y < 0) return 0;
	if (x > 0 && y <= 0) return 1;
	if (x >= 0 && y > 0) return 2;
	return 3;
}

inline bool cmpa(P x, P y) { return f(x) == f(y) ? x % y > 0 : f(x) < f(y); }

inline ll solve(int o) {
	if (n <= 3) return 0;
	ll ans = 1ll * (n - 1) * (n - 2) * (n - 3) / 6;
	vector <P> p;
	for (int i = 1; i <= n; i++)
		if (i != o) p.pb(a[i] - a[o]);
	sort(p.begin(), p.end(), cmpa);
	int w = p.size();
	for (int i = 0; i < w; i++) p.pb(p[i]);
	for (int i = 0, j = 1; i < w; i++) {
		if (j == i) j = i + 1;
		while (j < 2 * w && j != i + w && p[i] % p[j] > 0) ++j;
		int w = j - i - 1;
		ans -= 1ll * w * (w - 1) / 2;
	}
	return ans;
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%lf %lf", &a[i].x, &a[i].y);
	ll ans = 0;
	for (int i = 1; i <= n; i++) ans += solve(i);
	print(ans * (n - 4) / 2);
	return 0;
}
```

