## Decreasing Debts

最终只关心每个人的净借出/负债，构造时用个堆配对一下即可。

```cpp
const int N = 1e5 + 7;
int n, m;
ll a[N];
pq< pair< ll, int > > p, q;

int main() {
	rd(n), rd(m);
	for (int i = 1; i <= m; i++) {
		int x, y, z;
		rd(x), rd(y), rd(z);
		a[x] += z, a[y] -= z;
	}
	for (int i = 1; i <= n; i++)
		if (a[i] > 0) p.push(mp(a[i], i));
		else q.push(mp(-a[i], i));
	vector< pair < pi, ll > > ans;
	while (p.size()) {
		int x = p.top().se, y = q.top().se;
		ll s = p.top().fi, t = q.top().fi, z;
		p.pop(), q.pop();
		ans.pb(mp(mp(x, y), z = min(s, t)));
		s -= z, t -= z;
		if (s) p.push(mp(s, x));
		if (t) q.push(mp(t, y));
	}
	cout << ans.size() << endl;
	for (auto i : ans) printf("%d %d %lld\n", i.fi.fi, i.fi.se, i.se);
	return 0;
}
```

## Spaceship Solitaire

有结论：一个位置会超出当且仅当落在这个位置上的奖励超过了需要，且超出的多少等于超过的需要。

那么用个 `map` 模拟即可。

```cpp
const int N = 2e5 + 7;
int n, q, a[N], c[N], sz;
map< pi, int > p;
ll s;

inline void del(int x, int y) {
	--sz;
	int z = p[mp(x,y)];
	p.erase(mp(x,y));
	if (c[z] > a[z]) --s;
	c[z]--;
}

inline void add(int x, int y, int z) {
	++sz;
	p[mp(x,y)] = z;
	++c[z];
	if (c[z] > a[z]) ++s;
}

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(a[i]), s += a[i];
	rd(q);
	while (q--) {
		int x, y, z;
		rd(x), rd(y), rd(z);
		if (p[mp(x,y)]) del(x, y);
		if (z) add(x, y, z);
		print(s - sz);
	}
	return 0;
}
```

