		for (int j = 1; j <= m; j++)
			if (s[i][j] == 'P') return 0;
	return 1;
}

inline bool pd1() {
	bool ok = 1;
	for (int i = 1; i <= n; i++)
		if (s[i][1] == 'P') ok = 0;
	if (ok) return 1;
	ok = 1;
	for (int i = 1; i <= n; i++)
		if (s[i][m] == 'P') ok = 0;
	if (ok) return 1;
	ok = 1;
	for (int i = 1; i <= m; i++)
		if (s[1][i] == 'P') ok = 0;
	if (ok) return 1;
	ok = 1;
	for (int i = 1; i <= m; i++)
		if (s[n][i] == 'P') ok = 0;
	if (ok) return 1;
	return 0;
}

inline bool pd4() {
	for (int i = 1; i <= n; i++)
		if (s[i][1] == 'A' || s[i][m] == 'A') return 0;
	for (int i = 1; i <= m; i++)
		if (s[1][i] == 'A' || s[n][i] == 'A') return 0;
	return 1;
}

inline bool pd2() {
	if (s[1][1] == 'A') return 1;
	if (s[1][m] == 'A') return 1;
	if (s[n][1] == 'A') return 1;
	if (s[n][m] == 'A') return 1;
	for (int i = 2; i < n; i++) {
		bool ok = 1;
		for (int j = 1; j <= m; j++)
			if (s[i][j] == 'P') ok = 0;
		if (ok) return 1;
	}
	for (int j = 2; j < m; j++) {
		bool ok = 1;
		for (int i = 1; i <= n; i++)
			if (s[i][j] == 'P') ok = 0;
		if (ok) return 1;
	}
	return 0;
}

inline void solve() {
	rd(n), rd(m);
	for (int i = 1; i <= n; i++) rds(s[i], m);
	if (pd()) return prints("MORTAL"), void();
	if (pd0()) return print(0), void();
	if (pd1()) return print(1), void();
	if (pd4()) return print(4), void();
	if (pd2()) return print(2), void();
