## 题意

- 给定 $n$ 个字符串 $s_{1 \dots n}$。
- $q$ 次询问 $s_k$ 在 $s_{l \dots r}$ 中出现了多少次。
- $n, \sum |s| \le 2 \times 10^5$，$q \le 5 \times 10^5$。

## 题解

首先对 $n$ 个字符串建出 AC 自动机。

将询问离线并差分成两个询问。

将字符串顺着扫一遍，对扫过的字符串在 trie 上的所有节点贡献 $+1$。

假设此时扫到串 $i$，那么在 $i$ 上的询问 $s_k$ 的贡献等于 **$s_k$ 在 trie 上的终点**在 fail 树上的子树贡献和。

按 fail 树的 dfs 序建树状数组维护即可，时间复杂度 $\mathcal O((n + q) \log n)$。

## 代码

```cpp
const int N = 2e5 + 7, M = 26, Q = 5e5 + 7;
int n, m, q, p[N], trie[N][M], fail[N], f[N], t = 1, dfn[N], num, siz[N], c[N], k[Q], ans[Q];
char s[N];
vi e[N];

inline int ins(int n) {
	int p = 1;
	for (int i = 1; i <= n; i++) {
		int c = s[i] - 'a';
		if (!trie[p][c]) f[trie[p][c]=++t] = p;
		p = trie[p][c];
	}
	return p;
}

void dfs(int x) {
	dfn[x] = ++num, siz[x] = 1;
	for (ui i = 0; i < e[x].size(); i++) dfs(e[x][i]), siz[x] += siz[e[x][i]];
}

inline void build() {
	queue< int > q;
	for (int i = 0; i < M; i++)
		if (trie[1][i]) fail[trie[1][i]] = 1, q.push(trie[1][i]);
		else trie[1][i] = 1;
	while (q.size()) {
		int x = q.front();
		q.pop();
		for (int i = 0; i < M; i++)
			if (trie[x][i]) fail[trie[x][i]] = trie[fail[x]][i], q.push(trie[x][i]);
			else trie[x][i] = trie[fail[x]][i];
	}
	for (int i = 2; i <= t; i++) e[fail[i]].pb(i);
	dfs(1);
}

inline void add(int x) {
	while (x <= t) ++c[x], x += x & -x;
}

inline int ask(int x) {
	int ret = 0;
	while (x) ret += c[x], x -= x & -x;
	return ret;
}

int main() {
	rd(n), rd(q);
	for (int i = 1; i <= n; i++) rds(s, m), p[i] = ins(m);
	build();
	for (int i = 1; i <= n; i++) e[i].clear();
	for (int i = 1, l, r; i <= q; i++) {
		rd(l), rd(r), rd(k[i]);
		if (l > 1) e[l-1].pb(-i);
		e[r].pb(i);
	}
	for (int i = 1; i <= n; i++) {
		int x = p[i];
		while (x ^ 1) add(dfn[x]), x = f[x];
		for (ui j = 0; j < e[i].size(); j++) {
			int o = e[i][j] > 0 ? 1 : -1, t = abs(e[i][j]), x = p[k[t]];
			ans[t] += o * (ask(dfn[x] + siz[x] - 1) - ask(dfn[x] - 1));
		}
	}
	for (int i = 1; i <= q; i++) print(ans[i]);
	return 0;
}
```

> [CF547D Mike and Fish](https://codeforces.com/contest/547/problem/D)

## 题意

- 给定 $n$ 个整点。
- 你要给每个点染成红色或蓝色。
- 要求同一水平线或垂直线上两种颜色的数量最多相差 $1$。
- $n,x_i, y_i \le 2 \times 10^5$。

## 题解

对于每个点，将横纵坐标之间连一条边。

那么题意转化为对每条边定向使得每个点的入度和出度最多相差 $1$。

由于奇点一定只有偶数个，不妨将其全都连向 $0$。

然后跑一遍欧拉回路即可，时间复杂度 $\mathcal O(n)$。

## 代码

```cpp
const int N = 2e5 + 7;
int n, v[N<<1], d[N<<1], h[N<<1], e[N<<2], t[N<<2], c = 1;

inline void add(int x, int y, int z = 1) {
	e[++c] = y, t[c] = h[x], h[x] = c;
	if (z) add(y, x, 0);
}

void dfs(int x) {
	for (int &i = h[x]; i; i = t[i])
		if (!v[i>>1]) v[i>>1] = 1 + (x < N), dfs(e[i]);
}

int main() {
	rd(n);
	for (int i = 1, x, y; i <= n; i++)
		rd(x), rd(y), add(x, y + N), ++d[x], ++d[y+N];
	for (int i = 1; i < N << 1; i++)
		if (d[i] & 1) add(0, i);
	for (int i = 1; i < N; i++) dfs(i);
	for (int i = 1; i <= n; i++) putchar("br"[v[i]-1]);
	return 0;
}
```

> [CF575A Fibonotci](https://codeforces.com/contest/575/problem/A)

## 题意

- $s_{0\dots +\infty}$ 是一个正整数序列。
- 给定 $s_{0 \dots n - 1}$，对于 $i \ge n$，有 $m$ 个 $i$ 给定 $s_i$，剩下的 $i$ 满足 $s_i = s_{i \bmod n}$。
- $f_{0 \dots +\infty}$ 同样是一个正整数序列。
- 给定 $f_0,f_1$，对于 $i \ge 2$，$f_i = s_{i-1}f_{i-1} + s_{i-2}f_{i-2}$。
- 求 $f_k \bmod p$。
- $n,m \le 5 \times 10^4$，$k \le 10^{18}$，$s_i,p \le 10^9$。

## 题解

首先考虑 $m = 0$ 的情况。

由于 $f_i = s_{i-1}f_{i-1} + s_{i-2}f_{i-2}$，有：

$$
\begin{bmatrix} f_{i-2} & f_{i-1} \end{bmatrix} \times \begin{bmatrix} 0 & s_{i-2} \\\\ 1 & s_{i-1}
\end{bmatrix} = \begin{bmatrix} f_{i-1} & f_i \end{bmatrix}
$$

因此：

$$
\begin{bmatrix} f_{0} & f_{1} \end{bmatrix} \times \prod_{i=1}^{n} \begin{bmatrix} 0 & s_{i-1} \\\\ 1 & s_{i \bmod n} \end{bmatrix} = \begin{bmatrix} f_{n} & f_{n+1} \end{bmatrix}
$$

于是可以矩阵快速幂，最后一段可以暴力转移。

考虑 $m \ne 0$ 时，**线段树**维护矩阵乘积。

每次只会修改两个矩阵，因此一共只有 $\mathcal O(m)$ 个单点修改。

因此可以在没有特殊值的周期内用矩阵快速幂转移，有特殊值的周期内单点修改之后再转移再修改回去。

总时间复杂度 $\mathcal O(n + m (\log k + \log n))$。

## 代码

```cpp
const int N = 5e4 + 7;
ll k, o;
int n, m, x;
modint s[N];

struct mt {
	int n, m; modint a[2][2];
	inline mt() {}
	inline mt(int n, int m) : n(n), m(m) { memset(a, 0, sizeof(a)); }
	inline friend mt operator * (mt x, mt y) {
		mt z(x.n, y.m);
		for (int i = 0; i < z.n; i++)
			for (int k = 0; k < x.m; k++)
				for (int j = 0; j < z.m; j++)
					z.a[i][j] += x.a[i][k] * y.a[k][j];
		return z;
	}
} a[N], b[N], f;

inline void ksm(mt x, ll y, mt &z) {
	while (y) {
		if (y & 1) z = z * x;
		x = x * x, y >>= 1;
	}
}

struct Q {
	ll x, k; modint y;
	inline bool operator < (Q o) { return x < o.x; }
} q[N<<1];

struct T {
	int l, r; mt x;
} t[N<<2];

inline void build(int p, int l, int r) {
	t[p].l = l, t[p].r = r;
	if (l == r) return t[p].x = a[l], void();
	build(ls, l, md), build(rs, md + 1, r);
	t[p].x = t[ls].x * t[rs].x;
}

inline void chg(int p, int x, mt y) {
	if (t[p].l == t[p].r) return t[p].x = y, void();
	chg(x <= md ? ls : rs, x, y), t[p].x = t[ls].x * t[rs].x;
}

int main() {
	rd(k), rd(P), rd(n);
	for (int i = 0; i < n; i++) rd(x), s[i] = x % P;
	for (int i = 1; i <= n; i++) a[i] = mt(2, 2), a[i].a[0][1] = s[i-1], a[i].a[1][1] = s[i%n], a[i].a[1][0] = 1, b[i] = a[i];
	build(1, 1, n), rd(m);
	for (int i = 1; i <= m; i++) rd(q[i].x), q[m+i].x = q[i].x + 1, q[i].k = 1, rd(x), q[m+i].y = q[i].y = x % P;
	sort(q + 1, q + (m <<= 1) + 1);
	while (m && q[m].x > k) --m;
	f = mt(1, 2), f.a[0][1] = 1;
	for (int i = 1, j = 1; i <= m; i = ++j) {
		ll w = (q[i].x - 1) / n;
		while (j < m && w == (q[j+1].x - 1) / n) ++j;
		ksm(t[1].x, w - o, f), o = w;
		for (int k = i; k <= j; k++) {
			int d = (q[k].x - 1) % n + 1;
			b[d].a[q[k].k][1] = q[k].y, chg(1, d, b[d]);
		}
		if (w == k / n) break;
		f = f * t[1].x, o = w + 1;
		for (int k = i; k <= j; k++) {
			int d = (q[k].x - 1) % n + 1;
			chg(1, d, b[d] = a[d]);
		}
	}
	ll w = k / n;
	ksm(t[1].x, w - o, f);
	for (int i = 1, d = k % n; i <= d; i++) f = f * b[i];
	print(f.a[0][0]);
	return 0;
}
```

> [CF559E Gerald and Path](https://codeforces.com/contest/559/problem/E)

## 题意

- 有 $n$ 条线段。
- 每条线段给定其中一端的位置及长度。
- 求所有线段覆盖的最大长度。
- $n \le 100$。

## 题解

首先对一端位置排序。

考虑 dp，设 $f_{i,j,p}$ 表示考虑前 $i$ 条线段，最靠右的线段是第 $j$ 条，其方向为 $p$（$0$ 左 $1$ 右）。

考虑如何转移，从小到大枚举 $i$ 后面的线段以及它的方向，同时维护枚举过的线段中最靠右的线段以及它的方向。

设线段 $j$ 在 $p$ 方向的右端点是 $o$；此时枚举到线段 $k$，它的方向为 $q$，长度为 $l$，右端点是 $t$；枚举过的线段中最靠右的线段是 $x$，它的方向为 $y$，右端点是 $z$。

那么有转移：

$$
f_{k,x,y} \leftarrow f_{i,j,p} + \min(l, t - o) + z - t
$$

时间复杂度 $\mathcal O(n^3)$。

## 代码

```cpp
const int N = 107;
int n, ans, f[N][N][2];
pi a[N];

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) rd(a[i].fi), rd(a[i].se);
	sort(a + 1, a + n + 1);
	a[0].fi = -1e9;
	for (int i = 0; i <= n; i++)
		for (int j = 0; j <= i; j++)
			for (int p = 0; p < 2; p++) {
				ans = max(ans, f[i][j][p]);
				int o = a[j].fi + p * a[j].se, mx = -1e9, x, y;
				for (int k = i + 1; k <= n; k++)
					for (int q = 0; q < 2; q++) {
						int t = a[k].fi + q * a[k].se;
						if (t > mx) mx = t, x = k, y = q;
						f[k][x][y] = max(f[k][x][y], f[i][j][p] + min(a[k].se, t - o) + mx - t);
					}
			}
	print(ans);
	return 0;
}
```

> [CF512D Fox And Travelling](https://codeforces.com/contest/512/problem/D)

## 题意

- 给定一张 $n$ 个点 $m$ 条边的无向图。
- 一个点只有当**与它直接相连的点中最多只有一个点未被遍历过时**才可被遍历。
- 询问对于每个 $k \in [0,n]$，遍历 $k$ 个点的方案数。
- $n \le 100$，$m \le \frac{n(n-1)}2$，答案对 $10^9+9$ 取模。

## 题解

首先，在环中的点一定不会被遍历。

用类似拓扑排序的过程可以把环上的点全部扔掉，剩下的点会构成若干个有根树和无根树，其中有根树的根是树中**唯一与环中的点相连**的点。

每棵树求出答案后，01 背包合并即可，中间只需要乘上一个组合数。

对于有根树，设 $f_{i,j}$ 为 $i$ 的子树中选 $j$ 个的方案数，那么就是树上背包，同样需要乘上一个组合数。

对于无根树，以树中每个点为根做一次有根树的树上背包，这样会发现每种选择 $i$ 个点的方案会被算 $s - i$ 次，其中 $s$ 为这棵无根树的大小，那么除掉即可。

总时间复杂度 $\mathcal O(n^3)$，其中背包经过了上下界优化，原理简单来说就是「每对点只会在 LCA 处合并一次」。

## 代码

```cpp
const int N = 107;
int n, m, d[N], w[N], b[N], s[N], S;
vi e[N];
modint p[N], v[N], vp[N], f[N][N], ans[N];

inline modint C(int a, int b) {
	return p[a] * vp[b] * vp[a-b];
}

void dfs(int x, int o, int &s) {
	b[x] = o, ++s;
	for (ui i = 0; i < e[x].size(); i++) {
		int y = e[x][i];
		if (!d[y] && !b[y]) dfs(y, o, s);
	}
}

void dp(int x, int fa) {
	s[x] = 1, f[x][0] = 1;
	for (ui i = 0; i < e[x].size(); i++) {
		int y = e[x][i];
		if (b[x] != b[y] || y == fa) continue;
		dp(y, x);
		for (int j = 0; j < s[y]; j++) f[x][s[x]+j] = 0;
		for (int j = s[x] - 1; ~j; j--)
			for (int k = 1; k <= s[y]; k++)
				f[x][j+k] += f[x][j] * f[y][k] * C(j + k, j);
		s[x] += s[y];
	}
	f[x][s[x]] = f[x][s[x]-1];
}

void get(int x) {
	dp(x, 0);
	for (int i = 0; i <= s[x]; i++) f[0][i] += f[x][i];
}

int main() {
	rd(n), rd(m);
	p[0] = v[0] = 1;
	for (int i = 1; i <= n; i++) p[i] = p[i-1] * i;
	vp[n] = p[n] ^ -1;
	for (int i = n; i; i--) v[i] = p[i-1] * vp[i], vp[i-1] = vp[i] * i;
	for (int i = 1, x, y; i <= m; i++) rd(x), rd(y), e[x].pb(y), e[y].pb(x), ++d[x], ++d[y];
	queue<int> q;
	for (int i = 1; i <= n; i++) if (d[i] <= 1) w[i] = 1, q.push(i);
	while (q.size()) {
		int x = q.front();
		q.pop();
		for (ui i = 0; i < e[x].size(); i++) {
			int y = e[x][i];
			if (--d[y] <= 1 && !w[y]) w[y] = 1, q.push(y);
		}
	}
	for (int i = 1; i <= n; i++) if (d[i] == 1) dfs(i, i, s[i]);
	for (int i = 1; i <= n; i++) if (!d[i] && !b[i]) dfs(i, i, s[i]);
	ans[0] = 1;
	for (int i = 1; i <= n; i++)
		if (i == b[i]) {
			int o = s[i];
			if (d[i] == 1) get(i);
			else {
				for (int j = 1; j <= n; j++)
					if (b[j] == i) get(j);
				for (int j = 0; j <= o; j++) f[0][j] *= v[o-j];
			}
			for (int j = S; ~j; j--)
				for (int k = 1; k <= o; k++)
					ans[j+k] += ans[j] * f[0][k] * C(j + k, j);
			for (int j = 0; j <= o; j++) f[0][j] = 0;
			S += o;
		}
	for (int i = 0; i <= n; i++) print(ans[i]);
	return 0;
}
```

> [CF576D Flights for Regular Customers](https://codeforces.com/contest/576/problem/D)

## 题意

- 给定一张 $n$ 个点 $m$ 条边的有向图。
- 一开始你在 $1$ 号节点，你要走到 $n$ 号节点去。
- 只有当你已经走过了至少 $d_i$ 条边时，你才能走第 $i$ 条边。
- 问最少要走多少条边，或判断无法到达。
- $n,m \le 150$，$d_i \le 10^9$。

## 题解

首先对边排序，然后从小到大依次加入每条边。

考虑只有当前存在的边时，答案怎么求。

假设此时加入的边的 $d$ 值为 $t$，首先要求的是经过恰好 $t$ 条边时可以到达哪些点。

这个可以从加入上一条边时的答案递推过来，这个递推式可以矩阵加速。

求出恰好 $t$ 条边时可以到达哪些点后，对整个图进行一次 bfs 即可求出当前的答案。

这样时间复杂度是 $\mathcal O(n^3m \log d)$ 的，无法通过。

注意到每个点的状态只有 $0/1$ 两种，分别对应着无法到达和可以到达。

因此可以 bitset 优化，时间复杂度 $\mathcal O(\frac{n^3m \log d}w)$。

## 代码

```cpp
const int N = 150;
const ll inf = 1e18;
int n, m;
struct E {
	int x, y, z;
	inline void input() { rd(x), rd(y), rd(z), --x, --y; }
	inline friend bool operator < (E a, E b) { return a.z < b.z; }
} e[N];
ll d[N], ans;
#define bt bitset<N>
bt v;
struct mt {
	bt a[N];
	inline friend bt operator * (bt x, mt y) {
		bt z;
		for (int i = 0; i < n; i++) z[i] = (x & y.a[i]).any();
		return z;
	}
	inline friend mt operator * (mt x, mt y) {
		mt z;
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (x.a[i][j]) z.a[i] |= y.a[j];
		return z;
	}
} a;

inline void ksm(mt x, int y, bt &z) {
	while (y) {
		if (y & 1) z = z * x;
		x = x * x, y >>= 1;
	}
}

int main() {
	rd(n), rd(m);
	for (int i = 0; i < m; i++) e[i].input();
	sort(e, e + m);
	v[0] = 1;
	ans = inf;
	for (int i = 0, t = 0; i < m; i++) {
		if (e[i].z >= ans) break;
		int o = e[i].z - t;
		ksm(a, o, v);
		a.a[e[i].y][e[i].x] = 1;
		t = e[i].z;
		queue<int> q;
		for (int x = 0; x < n; x++)
			if (v[x]) q.push(x), d[x] = 0;
			else d[x] = inf;
		while (q.size()) {
			int x = q.front();
			q.pop();
			for (int y = 0; y < n; y++)
				if (a.a[y][x] && d[y] == inf)
					d[y] = d[x] + 1, q.push(y);
		}
		ans = min(ans, t + d[n-1]);
	}
	if (ans == inf) prints("Impossible");
	else print(ans);
	return 0;
}
```

> [CF505E Mr. Kitayuta vs. Bamboos](https://codeforces.com/contest/505/problem/E)

## 题意

- 给定 $n$ 个数 $h_{1 \dots n}$。
- 你需要进行 $m$ 轮操作，每轮操作为 $k$ 次修改，每次修改可以选择一个数 $h_i$ 修改为 $\max(h_i - p, 0)$。
- 每轮操作后每个 $h_i$ 将会被修改为 $h_i + a_i$。
- 你需要最小化最终 $h_{1 \dots n}$ 中的最大值。
- $n \le 10^5$，$m \le 5 \times 10^3$，$k \le 10$。

## 题解

首先二分答案。

判定的时候，发现正着判很麻烦，考虑倒序。

那么就相当于，每轮操作为：

- 将每个 $h_i$ 修改为 $h_i - a_i$，这里需要保证 $h_i - a_i \ge 0$。
- $k$ 次修改，每次修改可以选择一个数 $h_i$ 修改为 $h_i + p$。
- 要求最终的 $h_{1 \dots n}$ 均不小于给定的 $n$ 个数。

那么可以考虑贪心：

- 每次选择最容易导致 $h_i - a_i < 0$ 的位置加上 $p$，如果选完了还是会导致则判定不合法。
- 如果不存在可能导致 $h_i - a_i < 0$ 的位置，则直接判定剩下的次数是否足够使最终的 $h_{1 \dots n}$ 均不小于给定的 $n$ 个数。

时间复杂度 $\mathcal O((n + mk) \log n \log w)$。

## 代码

```cpp
const int N = 1e5 + 7;
int n, m, k, c[N];
ll h[N], a[N], p, l, r;

inline bool pd(ll o) {
	pq< pi > q;
	for (int i = 1; i <= n; i++) {
		if (h[i] + m * a[i] <= o) continue;
		q.push(mp(-(o / a[i]), i)), c[i] = 0;
	}
	int cnt = 0;
	for (int i = 1; q.size() && i <= m; i++)
		for (int j = 1; q.size() && j <= k; j++) {
			if (-q.top().fi < i) return 0;
			int x = q.top().se;
			q.pop();
			ll w = (o + (++c[x]) * p) / a[x];
			if (w < m) q.push(mp(-w, x));
			++cnt;
		}
	for (int i = 1; i <= n; i++) {
		ll w = o + c[i] * p - m * a[i];
		if (h[i] <= w) continue;
		w = (h[i] - w - 1) / p + 1;
		if (cnt + w > m * k) return 0;
		cnt += w;
	}
	return 1;
}

int main() {
	rd(n), rd(m), rd(k), rd(p);
	for (int i = 1; i <= n; i++)
		rd(h[i]), rd(a[i]),
		l = max(l, a[i]), r = max(r, h[i] + m * a[i]);
	while (l < r) {
		ll o = (l + r) >> 1;
		if (pd(o)) r = o;
		else l = o + 1;
	}
	print(l);
	return 0;
}
```

> [CF516D Drazil and Morning Exercise](https://codeforces.com/contest/516/problem/D)

## 题意

- 给定一棵 $n$ 个点的树，边有边权。
- 定义 $f_x = \max_{i=1}^n \text{dist}(x,i)$。
- $q$ 次询问最大的满足 $\max_{x \in s} f_x - \min_{x \in s} f_x \le l$ 的连通块 $s$ 包含的点数。
- $n \le 10^5$，$q \le 50$。

## 题解

先把 $f$ 线性求出来，然后由大到小双指针扫一遍，发现只会合并，因此并查集维护连通性即可，时间复杂度 $\mathcal O(n \log n + qn\alpha(n))$。

## 代码

```cpp
const int N = 1e5 + 7;
int n, q, fa[N], s[N], v[N], ans;
ll m, f[N][2], g[N];
pair< ll, int > p[N];
vector< pi > e[N];

void dfs1(int x, int fa) {
	for (ui i = 0; i < e[x].size(); i++) {
		int y = e[x][i].fi;
		if (y == fa) continue;
		dfs1(y, x);
		ll z = f[y][0] + e[x][i].se;
		if (z > f[x][1]) f[x][1] = z;
		if (z > f[x][0]) swap(f[x][0], f[x][1]);
	}
}

void dfs2(int x, int fa) {
	for (ui i = 0; i < e[x].size(); i++) {
		int y = e[x][i].fi;
		if (y == fa) continue;
		int z = e[x][i].se;
		g[y] = max(g[x], f[y][0] + z == f[x][0] ? f[x][1] : f[x][0]) + z;
		dfs2(y, x);
	} 
}

int get(int x) {
	return x == fa[x] ? x : (fa[x] = get(fa[x]));
}

inline void merge(int x, int y) {
	if (x == y) return;
	if (s[x] > s[y]) swap(x, y);
	fa[x] = y, s[y] += s[x];
	ans = max(ans, s[y]);
}

int main() {
	rd(n);
	for (int i = 1, x, y, z; i < n; i++)
		rd(x), rd(y), rd(z), e[x].pb(mp(y, z)), e[y].pb(mp(x, z));
	dfs1(1, 0);
	dfs2(1, 0);
	for (int i = 1; i <= n; i++) p[i] = mp(max(f[i][0], g[i]), i);
	sort(p + 1, p + n + 1);
	reverse(p + 1, p + n + 1);
	rd(q);
	while (q--) {
		rd(m), ans = 1;
		for (int i = 1; i <= n; i++) fa[i] = i, s[i] = 1, v[i] = 0;
		for (int l = 1, r = 0; l <= n; l++) {
			while (r < n && p[l].fi - p[r+1].fi <= m) {
				int x = p[++r].se;
				v[x] = 1;
				for (ui i = 0; i < e[x].size(); i++) {
					int y = e[x][i].fi;
					if (v[y]) merge(get(x), get(y));
				}
			}
			--s[get(p[l].se)], v[get(p[l].se)] = 0;
		}
		print(ans);
	}
	return 0;
}
```

> [CF582E Boolean Function](https://codeforces.com/contest/582/problem/E)

## 题意

- `A,B,C,D,a,b,c,d` 为八个布尔「变量」，其中小写字母的值等于对应大写字母的值取反。
- `&,|` 为两个布尔「操作符」。
- 布尔「表达式」为一个「变量」，或通过「操作符」连接起来的两个「表达式」。
- 布尔「函数」`f(A,B,C,D)` 为一个布尔「表达式」。
- 给定一个可能缺少某些「变量」和「操作符」（用 `?` 代替）的「函数」`s`，并给出 $n$ 个**函数在 `A,B,C,D` 确定时**的值。
- 求可能的「函数」个数。
- $|\texttt{s}|\le 500$，$n \le 16$，答案对 $10^9+7$ 取模。

## 题解

先建出表达式树，设 $f[i][j]$ 表示树中点 $i$ 处将 $n$ 个值压缩成 $j$ 的方案数。

对于一个非叶节点 $i$ 转移为
$$
f[i][x] = \sum_{x = y \oplus z} f[j][y] \times f[k][z]
$$
因此可以 FWT 优化，总时间复杂度 $\mathcal O(|\texttt{s}|n2^n)$。

## 代码

```cpp
const int N = 507, M = 16;
int k, n, m, fa[N], t = 1, p = 1;
char s[N], c[N];
int h[M|1][5];
vi e[N];
modint f[N][1<<M|1], a[1<<M|1], b[1<<M|1];

inline void in(modint *A, modint *B) {
	for (int i = 0; i < n; i++) a[i] = A[i], b[i] = B[i];
}

inline void get() {
	for (int i = 0; i < n; i++) a[i] *= b[i];
}

inline void out(modint *f) {
	for (int i = 0; i < n; i++) f[i] += a[i];
}

inline void OR(modint *f, modint x = 1) {
	for (int o = 2, k = 1; o <= n; o <<= 1, k <<= 1)
		for (int i = 0; i < n; i += o)
			for (int j = 0; j < k; j++)
				f[i+j+k] += f[i+j] * x;
}

inline void AND(modint *f, modint x = 1) {
	for (int o = 2, k = 1; o <= n; o <<= 1, k <<= 1)
		for (int i = 0; i < n; i += o)
			for (int j = 0; j < k; j++)
				f[i+j] += f[i+j+k] * x;
}

void dfs(int x) {
	if (!e[x].size()) {
		if (c[x] == '?')
			for (int i = 0; i < 4; i++) {
				int k = 0;
				for (int j = 0; j < m; j++) k |= h[j][i] << j;
				f[x][k] += 1, f[x][((1<<m)-1)^k] += 1;
			}
		else {
			int i = c[x] - (c[x] >= 'A' && c[x] <= 'D' ? 'A' : 'a'), k = 0;
			for (int j = 0; j < m; j++) k |= h[j][i] << j;
			f[x][c[x]>='A'&&c[x]<='D'?k:(((1<<m)-1)^k)] += 1;
		}
		return;
	}
	dfs(e[x][0]);
	dfs(e[x][1]);
	if (c[x] != '&') in(f[e[x][0]], f[e[x][1]]), OR(a), OR(b), get(), OR(a, P - 1), out(f[x]);
	if (c[x] != '|') in(f[e[x][0]], f[e[x][1]]), AND(a), AND(b), get(), AND(a, P - 1), out(f[x]);
}

int main() {
	rds(s, k), rd(m), n = 1 << m;
	for (int i = 1; i <= k; i++)
		if (s[i] == '(') e[p].pb(++t), fa[t] = p, p = t;
		else if (s[i] == ')') p = fa[p];
		else c[p] = s[i];
	for (int i = 0; i < m; i++)
		for (int j = 0; j < 5; j++)
			rd(h[i][j]);
	dfs(1);
	int o = 0;
	for (int i = 0; i < m; i++) o |= h[i][4] << i;
	print(f[1][o]);
	return 0;
}
```

> [CF611G New Year and Cake](https://codeforces.com/contest/611/problem/G)

## 题意

- 给定一个 $n$ 个顶点的严格凸多边形。
- 要求 $\frac{n(n-3)}2$ 个**由对角线将多边形割成两个部分的面积差 $\times 2$** 之和。
- $n \le 5 \times 10^5$，答案对 $10^9+7$ 取模。

## 题解

双指针扫一遍，动态维护对角线隔开的最大面积以及面积对答案的贡献和，其中贡献需要利用叉积的分配率维护有贡献的向量和。

注意本题根据写法不同可能需要开 `unsigned long long`，但同时需要对答案取模，因此细节很多。

## 代码

```cpp
struct Po {
	int x, y;
	inline Po &operator -= (Po o) { return x -= o.x, y -= o.y, *this; }
	inline friend Po operator - (Po a, Po b) { return a -= b; }
	inline friend ll operator % (Po a, Po b) { return 1ll * a.x * b.y - 1ll * a.y * b.x; }
};

inline pair< modint, modint > &operator += (pair< modint, modint > &a, Po b) {
	return a.fi += (b.x % P + P) % P, a.se += (b.y % P + P) % P, a;
}

inline modint operator % (pair< modint, modint > a, Po b) {
	return a.fi * ((b.y % P + P) % P) - a.se * ((b.x % P + P) % P);
}

inline pair< modint, modint > operator * (modint a, Po b) {
	return mp(a * ((b.x % P + P) % P), a * ((b.y % P + P) % P));
}

inline pair< modint, modint > &operator -= (pair< modint, modint > &a, pair< modint, modint > b) {
	return a.fi -= b.fi, a.se -= b.se, a;
}

const int N = 5e5 + 7;
int n, cnt;
Po a[N];
modint ans, o;
pair< modint, modint > p;
ul s, m;

int main() {
	rd(n);
	for (int i = 0; i < n; i++) rd(a[i].x), rd(a[i].y);
	for (int i = 2; i < n; i++) s += (a[i] - a[0]) % (a[i-1] - a[0]);
	for (int i = 0, j = 0; i < n; i++) {
		while (1) {
			int k = (j + 1) % n;
			ul w = (a[k] - a[i]) % (a[j] - a[i]);
			if (2 * (m + w) >= s) {
				if (2 * (m + w) == s) ++cnt;
				break;
			}
			o += (m += w) % P;
			p += a[k] - a[i];
			j = k;
		}
		ans -= o * 2;
		int k = (i + 1) % n;
		m -= (a[j] - a[i]) % (a[k] - a[i]);
		o -= p % (a[k] - a[i]);
		p -= (modint)((j - i + n) % n) * (a[k] - a[i]);
	}
	ans += (modint)((1ll * n * (n - 3) - cnt) / 2 % P) * (modint)(s % P);
	print(ans);
	return 0;
}
```

> [CF555E Case of Computer Network](https://codeforces.com/contest/555/problem/E)

## 题意

- 给定一张 $n$ 个点 $m$ 条边的无向图。
- 给定 $q$ 组有向点对 $(s, t)$。
- 询问是否存在**使得所有 $s$ 都能到达 $t$** 的无向图中每条边的定向方案。
- $n,m,q \le 2 \times 10^5$。

## 题解

先求边双，缩点变成森林。

判定时先求 lca，树上差分一下即可，时间复杂度 $\mathcal O(n \log n)$。

## 代码

```cpp
const int N = 2e5 + 7;
int n, m, q;
int h[N], e[N<<1], t[N<<1], p = 1;
int dfn[N], low[N], num;
int b[N<<1], c[N], k;
int hc[N], ec[N<<1], tc[N<<1], pc = 1;
int v[N], w, f[N][20], d[N], g1[N], g2[N];

inline void add(int x, int y, int z = 1) {
	e[++p] = y;
	t[p] = h[x];
	h[x] = p;
	if (z) add(y, x, 0);
}

void tarjan(int x, int f) {
	dfn[x] = low[x] = ++num;
	for (int i = h[x]; i; i = t[i]) {
		if (i == f) continue;
		int y = e[i];
		if (dfn[y]) low[x] = min(low[x], dfn[y]);
		else {
			tarjan(y, i ^ 1), low[x] = min(low[x], low[y]);
			if (low[y] > dfn[x]) b[i] = b[i^1] = 1;
		}
	}
}

void dfs(int x) {
	c[x] = k;
	for (int i = h[x]; i; i = t[i]) {
		if (b[i]) continue;
		int y = e[i];
		if (c[y]) continue;
		dfs(y);
	}
}

inline void addc(int x, int y, int z = 1) {
	ec[++pc] = y;
	tc[pc] = hc[x];
	hc[x] = pc;
	if (z) addc(y, x, 0);
}

void dfsc(int x) {
	v[x] = w;
	for (int i = hc[x]; i; i = tc[i]) {
		int y = ec[i];
		if (y == f[x][0]) continue;
		f[y][0] = x, d[y] = d[x] + 1;
		for (int j = 0; f[y][j]; j++)
			f[y][j+1] = f[f[y][j]][j];
		dfsc(y);
	}
}

inline int lca(int x, int y) {
	if (d[x] > d[y]) swap(x, y);
	for (int i = 19; ~i; i--)
		if (d[f[y][i]] >= d[x]) y = f[y][i];
	if (x == y) return x;
	for (int i = 19; ~i; i--)
		if (f[x][i] ^ f[y][i]) x = f[x][i], y = f[y][i];
	return f[x][0];
}

bool dfspd(int x) {
	for (int i = hc[x]; i; i = tc[i]) {
		int y = ec[i];
		if (y == f[x][0]) continue;
		if (!dfspd(y) || (g1[y] && g2[y])) return 0;
		g1[x] += g1[y], g2[x] += g2[y];
	}
	return 1;
}

int main() {
	rd(n), rd(m), rd(q);
	for (int i = 1, x, y; i <= m; i++)
		rd(x), rd(y), add(x, y);
	for (int i = 1; i <= n; i++)
		if (!dfn[i]) tarjan(i, 0);
	for (int i = 1; i <= n; i++)
		if (!c[i]) ++k, dfs(i);
	for (int x = 1; x <= n; x++)
		for (int i = h[x]; i; i = t[i]) {
			int y = e[i];
			if (c[x] >= c[y]) continue;
			addc(c[x], c[y]);
		}
	for (int i = 1; i <= k; i++)
		if (!v[i]) ++w, d[i] = 1, dfsc(i);
	for (int i = 1, x, y; i <= q; i++) {
		rd(x), rd(y), x = c[x], y = c[y];
		if (x == y) continue;
		if (v[x] != v[y]) return prints("No"), 0;
		int z = lca(x, y);
		++g1[x], --g1[z], ++g2[y], --g2[z];
	}
	for (int i = 1; i <= n; i++)
		if (d[i] == 1 && !dfspd(i)) return prints("No"), 0;
	prints("Yes");
	return 0;
}
```

> [CF585F Digits of Number Pi](https://codeforces.com/contest/585/problem/F)

## 题意

- 给定长度为 $n$ 的数字串 $s$ 和长度为 $d$ 的不含前导零的数字串 $x,y(x \le y)$。
- 求**存在长度至少为 $\left\lfloor\frac{d}{2}\right\rfloor$ 的子串是 $s$ 的子串**的数字串 $t \in [x,y]$ 的数量。
- $n \le 10^3$，$d \le 50$，答案对 $10^9+7$ 取模。

## 题解

把 $s$ 所有长度为 $\left\lfloor\frac{d}{2}\right\rfloor$ 的子串拿出来建 AC 自动机，然后数位 dp 即可。

设 $f[i][j][1/0]$ 表示考虑到第 $i$ 位，在 AC 自动机的 $j$ 节点，是否 $(1/0)$ 有上界限制时的方案数，预处理出 $p[i][1/0]$ 为第 $i \sim d$ 位是否 $(1/0)$ 有上界限制时的方案数。

初始时 $f[0][1][1] = 1$。

枚举下一位的数字 $k$，设 $j\to k$ 为 AC 自动机中 $j$ 节点的第 $k$ 个儿子，设限制数字为 $c$。

- 任意时刻有 $f[i][j][0] \to f[i+1][j\to k][0]$；
- 若 $k < c$，则 $f[i][j][1] \to f[i+1][j\to k][0]$；
- 若 $k=c$，则 $f[i][j][1] \to f[i+1][j\to k][1]$；

最后用乘法原理将每种方案的 $f,p$ 相乘即可，时间复杂度 $\mathcal O(10nd^2)$。

## 代码

```cpp
const int N = 1e3 + 7, D = 53, K = 11;
int n, d, trie[N*D][K], ed[N*D], fail[N*D], tot = 1;
char s[N], a[D], b[D];
modint p[N][2], f[D][N*D][2];

inline void build() {
	int m = d / 2;
	for (int i = 1; i + m - 1 <= n; i++) {
		int p = 1;
		for (int j = i, k = 1; k <= m; j++, k++) {
			int c = s[j] - '0';
			if (!trie[p][c]) trie[p][c] = ++tot;
			p = trie[p][c];
		}
		ed[p] = 1;
	}
	queue< int > q;
	for (int i = 0; i < 10; i++)
		if (trie[1][i]) fail[trie[1][i]] = 1, q.push(trie[1][i]);
		else trie[1][i] = 1;
	while (q.size()) {
		int x = q.front();
		q.pop();
		for (int i = 0; i < 10; i++)
			if (trie[x][i]) fail[trie[x][i]] = trie[fail[x]][i], q.push(trie[x][i]);
			else trie[x][i] = trie[fail[x]][i];
	}
}

inline modint calc(char *t) {
	p[d+1][0] = p[d+1][1] = 1;
	for (int i = d; i; i--) p[i][0] = p[i+1][0] * 10, p[i][1] = (t[i] - '0') * p[i+1][0] + p[i+1][1];
	modint ans = 0;
	for (int i = 1; i <= d; i++)
		for (int j = 1; j <= tot; j++)
			for (int k = 0; k < 2; k++)
				f[i][j][k] = 0;
	f[0][1][1] = 1;
	for (int i = 0; i < d; i++)
		for (int j = 1; j <= tot; j++)
			if (!ed[j])
				for (int k = 0; k < 10; k++) {
					int o = trie[j][k];
					f[i+1][o][0] += f[i][j][0];
					if (k < t[i+1] - '0') f[i+1][o][0] += f[i][j][1];
					if (k == t[i+1] - '0') f[i+1][o][1] += f[i][j][1];
				}
	for (int i = 1; i <= d; i++)
		for (int j = 1; j <= tot; j++)
			if (ed[j]) ans += f[i][j][0] * p[i+1][0] + f[i][j][1] * p[i+1][1];
	return ans;
}

int main() {
	rds(s, n), rds(a, d), rds(b, d), build();
	int k = d;
	while (a[k] == '0') a[k--] = '9';
	--a[k];
	print(calc(b) - calc(a));
	return 0;
}
```

> [CF578E Walking!](https://codeforces.com/contest/578/problem/E)

## 题意

- 给定一个长度为 $n$ 的只包含 `L,R` 的字符串 $s$。
- 构造一个 $n$ 排列 $p$ 满足 $s[p_i] \ne s[p_{i+1}](1 \le i < n)$。
- 最小化 $p$ 中 $p_i > p_{i+1}(1 \le i < n)$ 的数量。
- $n \le 10^5$，数据保证有解。

## 题解

问题等价于，将 $s$ 划分成尽可能少的 `L,R` 交替的非连续子序列。

考虑贪心，每添加一个字符，就在前面划分好的子序列中找一个可以接到末尾的接进去，没有可以接的就新开一个子序列。

最后要将若干个子序列拼接在一起，分类讨论一下即可。

## 代码

```cpp
const int N = 1e5 + 7;
int n, t[N];
char s[N];
vi e[2], Ans;
vector< pi > g[4], ans;

int main() {
	rds(s, n);
	map< char, int > p;
	p['L'] = 0, p['R'] = 1;
	for (int i = 1; i <= n; i++) {
		int c = p[s[i]];
		if (e[c^1].size()) {
			t[i] = e[c^1].back();
			e[c^1].pop_back();
		}
		e[c].pb(i);
	}
	print(e[0].size() + e[1].size() - 1);
	for (ui i = 0; i < e[0].size(); i++) {
		int x = e[0][i], y = x;
		while (t[y]) y = t[y];
		g[p[s[y]]<<1|p[s[x]]].pb(mp(y, x));
	}
	for (ui i = 0; i < e[1].size(); i++) {
		int x = e[1][i], y = x;
		while (t[y]) y = t[y];
		g[p[s[y]]<<1|p[s[x]]].pb(mp(y, x));
	}
	while (g[1].size() > 1u) {
		pi x = g[1].back();
		g[1].pop_back(); 
		t[x.fi] = g[1].back().se;
		g[1].back().se = x.se;
	}
	while (g[2].size() > 1u) {
		pi x = g[2].back();
		g[2].pop_back(); 
		t[x.fi] = g[2].back().se;
		g[2].back().se = x.se;
	}
	if (g[1].size() && g[2].size()) {
		pi x = g[1][0], y = g[2][0];
		g[1].pop_back(), g[2].pop_back();
		if (x.se > y.se) {
			g[0].pb(mp(x.fi, t[x.se]));
			t[x.se] = y.se;
			g[3].pb(mp(y.fi, x.se));
		} else {
			g[3].pb(mp(y.fi, t[y.se]));
			t[y.se] = x.se;
			g[0].pb(mp(x.fi, y.se));
		}
	}
	if (g[0].size() > g[3].size() || (g[0].size() == g[3].size() && !g[2].size())) {
		if (g[1].size()) ans.pb(g[1][0]);
		for (ui i = 0; i < g[3].size(); i++)
			ans.pb(g[0][i]), ans.pb(g[3][i]);
		if (g[0].size() > g[3].size()) ans.pb(g[0].back());
	} else {
		if (g[2].size()) ans.pb(g[2][0]);
		for (ui i = 0; i < g[0].size(); i++)
			ans.pb(g[3][i]), ans.pb(g[0][i]);
		if (g[3].size() > g[0].size()) ans.pb(g[3].back());
	}
	while (ans.size() > 1u) {
		pi x = ans.back();
		ans.pop_back(); 
		t[x.fi] = ans.back().se;
		ans.back().se = x.se;
	}
	Ans.pb(ans.back().se);
	while (t[Ans.back()]) Ans.pb(t[Ans.back()]);
	while (Ans.size()) print(Ans.back(), " \n"[Ans.size()==1u]), Ans.pop_back();
	return 0;
}
