## Optimal Subsequences

二分 + 树状数组，$\mathcal O(n \log^2 n)$。

```cpp
const int N = 2e5 + 7;
int n, m, a[N], c[N], ans[N];
pq< pi > q;
pair< pi, int > p[N];

inline void add(int x) {
	while (x <= n) c[x]++, x += x & -x;
}

inline int ask(int x) {
	int k = 0;
	while (x) k += c[x], x -= x & -x;
	return k;
}

inline int qry(int x) {
	int l = 1, r = n;
	while (l < r) {
		int mid = (l + r) >> 1;
		if (ask(mid) < x) l = mid + 1;
		else r = mid;
	}
	return a[l];
}

int main() {
	rd(n);
	for (int i = 1; i <= n; i++) {
		rd(a[i]);
		q.push(mp(a[i], -i));
	}
	rd(m);
	for (int i = 1, x, y; i <= m; i++) {
		rd(x), rd(y), p[i] = mp(mp(x, y), i);
	}
	sort(p + 1, p + m + 1);
	int t = 0;
	for (int i = 1; i <= m; i++) {
		while (t < p[i].fi.fi) {
			int x = -q.top().se;
			q.pop();
			add(x);
			++t;
		}
		ans[p[i].se] = qry(p[i].fi.se);
	}
	for (int i = 1; i <= m; i++) print(ans[i]);
	return 0;
}
