namespace Rd {
	inline bool gt() {
		int a = rand(), b = rand();
		while (a == b) a = rand(), b = rand();
		return a < b;
	}
	template <class I>
	inline I rd(I k) {
		I w = 1;
		while (w < k) w <<= 1;
		while (w >= k) {
			I o = 1, x = 0;
			while (o < k) o <<= 1, x = x << 1 | gt();
			w = x;
		}
		return w;
