inline void dij(int S, int *d) {
	for (int i = 1; i <= n; i++) d[i] = inf, v[i] = 0;
	d[S] = 0, q.push(mp(0, S));
	while (q.size()) {
		int x = q.top().se;
		q.pop();
		if (v[x]) continue;
		v[x] = 1;
		for (pi o : e[x]) {
			int y = o.fi, z = o.se;
			if (d[y] > d[x] + z)
				d[y] = d[x] + z, q.push(mp(-d[y], y));
		}
	}
}
