inline vi virtual_tree(vi p) {
	sort(p.begin(), p.end(), [&](int x, int y) { return dfn[x] < dfn[y]; });
	vi q = p;
	for (int x : p) {
		int lca = HLD::lca(x, s[t]);
		if (lca != s[t]) {
			while (t && d[s[t-1]] >= d[lca]) g[s[t-1]].pb(s[t]), --t;
			if (lca != s[t]) g[lca].pb(s[t]), q.pb(s[t] = lca);
		}
		s[++t] = x;
	}
	while (t > 1) g[s[t-1]].pb(s[t]), --t;
	return t = 0, q;
}
